--
-- Name: turno_hash(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.turno_hash() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.hash := encode(
        sha256(convert_to(
            COALESCE(NEW.rol,'') || '|' || COALESCE(NEW.contenido,'') || '|'
            || COALESCE(NEW.contenido_json::text,'') || '|'
            || COALESCE(NEW.modelo_id::text,'') || '|'
            || to_char(COALESCE(NEW.ts, now()), 'YYYYMMDDHH24MISSUS'),
        'UTF8')),
        'hex');
    RETURN NEW;
END $$;


