CREATE FUNCTION config.leer_parametro(p_codigo text, p_en timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  SELECT valor FROM config.parametro
   WHERE codigo = p_codigo AND valid_from <= p_en AND (valid_to IS NULL OR valid_to > p_en)
   ORDER BY valid_from DESC LIMIT 1;
$$;


