--
-- Name: actor_datos_personales_descifrar(uuid, text); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.actor_datos_personales_descifrar(p_actor_uid uuid, p_motivo text) RETURNS TABLE(dni text, email text, telefono text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'core', 'audit'
    AS $$
DECLARE
    v_clave text     := current_setting('app.crypto_key', true);
    v_nivel smallint := core.clasificacion_max();
    v_fila  core.actor_datos_personales%ROWTYPE;
BEGIN
    -- Ley 29733: finalidad declarada y nivel de acceso mínimo.
    IF v_nivel < 3 THEN
        RAISE EXCEPTION
            'Acceso denegado: se requiere clasificación 3 (Confidencial). Nivel de sesión: %', v_nivel
            USING ERRCODE = '42501',
                  HINT = 'app.clasificacion_max la fija el aplicativo tras autenticar. '
                         'No es una credencial: ver limitación DC-02 en el informe P9.';
    END IF;

    IF p_motivo IS NULL OR btrim(p_motivo) = '' THEN
        RAISE EXCEPTION 'El motivo del descifrado es obligatorio (principio de finalidad)'
            USING ERRCODE = '22023';
    END IF;

    IF v_clave IS NULL OR v_clave = '' THEN
        RAISE EXCEPTION 'No hay clave en la sesión: falta app.crypto_key'
            USING ERRCODE = '42501';
    END IF;

    SELECT * INTO v_fila
      FROM core.actor_datos_personales d
     WHERE d.actor_uid = p_actor_uid
       AND d.nivel_clasificacion <= v_nivel;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'El actor % no existe o su clasificación excede el nivel de la sesión',
            p_actor_uid USING ERRCODE = 'P0002';
    END IF;

    -- Se audita antes de devolver: si el INSERT falla, no hay descifrado.
    INSERT INTO audit.datos_personales_acceso
        (usuario, operacion, actor_uid, motivo, filas_afectadas, contexto)
    VALUES
        (session_user, 'select_descifrado', p_actor_uid, p_motivo, 1,
         jsonb_build_object(
             'origen', COALESCE(NULLIF(current_setting('app.p9_origen', true), ''), 'aplicacion'),
             'funcion', 'core.actor_datos_personales_descifrar',
             'clasificacion_sesion', v_nivel,
             'descifro_dni',      v_fila.dni_cifrado      IS NOT NULL,
             'descifro_email',    v_fila.email_cifrado    IS NOT NULL,
             'descifro_telefono', v_fila.telefono_cifrado IS NOT NULL));

    RETURN QUERY
    SELECT CASE WHEN v_fila.dni_cifrado      IS NOT NULL
                THEN public.pgp_sym_decrypt(v_fila.dni_cifrado, v_clave) END,
           CASE WHEN v_fila.email_cifrado    IS NOT NULL
                THEN public.pgp_sym_decrypt(v_fila.email_cifrado, v_clave) END,
           CASE WHEN v_fila.telefono_cifrado IS NOT NULL
                THEN public.pgp_sym_decrypt(v_fila.telefono_cifrado, v_clave) END;
END $$;


--
-- Name: FUNCTION actor_datos_personales_descifrar(p_actor_uid uuid, p_motivo text); Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON FUNCTION core.actor_datos_personales_descifrar(p_actor_uid uuid, p_motivo text) IS 'Único camino soportado para ver PII en claro. Exige nivel 3, motivo no vacío y registra el acceso en audit.datos_personales_acceso. pgcrypto se invoca cualificado (public.pgp_sym_decrypt) porque el search_path está endurecido; si pgcrypto se mueve de schema, hay que actualizar esta función.';


--
-- Name: alcance_caso(uuid); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.alcance_caso(p_caso_id uuid) RETURNS smallint
    LANGUAGE sql STABLE PARALLEL SAFE
    SET search_path TO 'pg_catalog', 'core'
    AS $$
  with alcances as (
    select r.alcance_id
      from core.caso_regiones cr
      join core.regiones r on r.id = cr.region_id
     where cr.caso_id = p_caso_id
       and r.alcance_id is not null
    union
    select r.alcance_id
      from core.casos c
      join core.regiones r
        on r.id = coalesce(
             c.region_principal_id,
             (select p.region_id from core.provincias p where p.id = c.provincia_principal_id),
             (select p.region_id from core.distritos d join core.provincias p on p.id = d.provincia_id
               where d.id = c.distrito_principal_id)
           )
     where c.id = p_caso_id
       and r.alcance_id is not null
       and not exists (select 1 from core.caso_regiones x where x.caso_id = p_caso_id)
  )
  select case
           when count(*) = 0 then null
           when count(distinct alcance_id) = 1 then min(alcance_id)
           else 5::smallint
         end
    from alcances
$$;


--
-- Name: FUNCTION alcance_caso(p_caso_id uuid); Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON FUNCTION core.alcance_caso(p_caso_id uuid) IS 'Alcance geográfico derivado de las regiones del caso (Nacional si hay varios alcances).';


--
-- Name: anular_caso(uuid, text); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.anular_caso(p_caso_id uuid, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'core'
    AS $$
declare
  v_lote    uuid := gen_random_uuid();
  v_usuario uuid := nullif(current_setting('app.usuario_id', true), '')::uuid;
  v_nivel   smallint;
  n_casos   integer := 0;
  n_alertas integer := 0;
  n_eventos integer := 0;
  n_demandas integer := 0;
  n_compromisos integer := 0;
  n_hitos   integer := 0;
  n_docs    integer := 0;
begin
  if p_motivo is null or btrim(p_motivo) = '' then
    raise exception 'El motivo de la anulación es obligatorio'
      using errcode = '22023';
  end if;

  select nivel_clasificacion into v_nivel
    from core.casos
   where id = p_caso_id and anulado_en is null;

  if not found then
    raise exception 'El caso no existe o ya está anulado'
      using errcode = 'P0002';
  end if;

  perform core.exigir_anulacion(v_nivel);

  update core.casos
     set anulado_en = now(),
         anulado_por = v_usuario,
         anulacion_id = v_lote,
         motivo_anulacion = p_motivo
   where id = p_caso_id;
  get diagnostics n_casos = row_count;

  update core.caso_cronologia
     set anulado_en = now(), anulado_por = v_usuario,
         anulacion_id = v_lote, motivo_anulacion = p_motivo
   where caso_id = p_caso_id and anulado_en is null;
  get diagnostics n_eventos = row_count;

  update core.alertas_tempranas
     set anulado_en = now(), anulado_por = v_usuario,
         anulacion_id = v_lote, motivo_anulacion = p_motivo
   where caso_id = p_caso_id and anulado_en is null;
  get diagnostics n_alertas = row_count;

  update core.demandas
     set anulado_en = now(), anulado_por = v_usuario,
         anulacion_id = v_lote, motivo_anulacion = p_motivo
   where caso_id = p_caso_id and anulado_en is null;
  get diagnostics n_demandas = row_count;

  update core.compromisos
     set anulado_en = now(), anulado_por = v_usuario,
         anulacion_id = v_lote, motivo_anulacion = p_motivo
   where caso_id = p_caso_id and anulado_en is null;
  get diagnostics n_compromisos = row_count;

  update core.hitos_compromiso h
     set anulado_en = now(), anulado_por = v_usuario,
         anulacion_id = v_lote, motivo_anulacion = p_motivo
    from core.compromisos c
   where c.id = h.compromiso_id
     and c.caso_id = p_caso_id
     and h.anulado_en is null;
  get diagnostics n_hitos = row_count;

  update core.documentos
     set anulado_en = now(), anulado_por = v_usuario,
         anulacion_id = v_lote, motivo_anulacion = p_motivo
   where caso_id = p_caso_id and anulado_en is null;
  get diagnostics n_docs = row_count;

  return jsonb_build_object(
    'anulacionId', v_lote,
    'casos', n_casos,
    'alertas', n_alertas,
    'eventos', n_eventos,
    'demandas', n_demandas,
    'compromisos', n_compromisos,
    'hitos', n_hitos,
    'documentos', n_docs
  );
end $$;


--
-- Name: anular_registro(text, uuid, text); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.anular_registro(p_tabla text, p_id uuid, p_motivo text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'core'
    AS $_$
declare
  v_lote uuid := gen_random_uuid();
  v_usuario uuid := nullif(current_setting('app.usuario_id', true), '')::uuid;
  v_nivel smallint;
  n_filas integer := 0;
  v_tablas text[] := array[
    'alertas_tempranas', 'compromisos', 'hitos_compromiso',
    'documentos', 'demandas', 'caso_cronologia'
  ];
begin
  if not (p_tabla = any (v_tablas)) then
    raise exception
      'Tabla no admitida para anulación: % (los casos usan core.anular_caso)', p_tabla
      using errcode = '22023';
  end if;

  if p_motivo is null or btrim(p_motivo) = '' then
    raise exception 'El motivo de la anulación es obligatorio'
      using errcode = '22023';
  end if;

  -- `EXECUTE` no actualiza `FOUND`: la comprobación va por `GET DIAGNOSTICS`.
  execute format(
    'select nivel_clasificacion from core.%I where id = $1 and anulado_en is null',
    p_tabla)
    into v_nivel using p_id;
  get diagnostics n_filas = row_count;

  if n_filas = 0 then
    raise exception 'El registro no existe o ya está anulado'
      using errcode = 'P0002';
  end if;

  perform core.exigir_anulacion(v_nivel);

  execute format(
    'update core.%I
        set anulado_en = now(), anulado_por = $2,
            anulacion_id = $3, motivo_anulacion = $4
      where id = $1 and anulado_en is null', p_tabla)
    using p_id, v_usuario, v_lote, p_motivo;

  -- Los hitos acompañan a su compromiso.
  if p_tabla = 'compromisos' then
    update core.hitos_compromiso
       set anulado_en = now(), anulado_por = v_usuario,
           anulacion_id = v_lote, motivo_anulacion = p_motivo
     where compromiso_id = p_id and anulado_en is null;
  end if;

  return v_lote;
end $_$;


--
-- Name: aplicar_cambio_normativo(uuid, uuid); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.aplicar_cambio_normativo(p_cambio_id uuid, p_aprobado_por uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE c core.cambio_normativo%ROWTYPE;
BEGIN
  SELECT * INTO c FROM core.cambio_normativo WHERE id = p_cambio_id FOR UPDATE;
  IF c.id IS NULL THEN RAISE EXCEPTION 'cambio_normativo % no existe', p_cambio_id; END IF;
  IF c.aplicado_en IS NOT NULL THEN RAISE EXCEPTION 'cambio_normativo % ya fue aplicado', p_cambio_id; END IF;
  PERFORM set_config('app.cambio_normativo_en_curso', 'true', true);
  IF c.accion = 'insertar' THEN
    INSERT INTO core.cat_niveles_conflicto (id, codigo, nombre, orden)
    SELECT (c.payload_despues->>'id')::smallint, c.payload_despues->>'codigo', c.payload_despues->>'nombre', (c.payload_despues->>'orden')::smallint;
  ELSIF c.accion = 'modificar' THEN
    UPDATE core.cat_niveles_conflicto SET codigo = c.payload_despues->>'codigo', nombre = c.payload_despues->>'nombre',
           orden = (c.payload_despues->>'orden')::smallint WHERE id = c.fila_id;
  ELSIF c.accion = 'desactivar' THEN
    DELETE FROM core.cat_niveles_conflicto WHERE id = c.fila_id;
  END IF;
  PERFORM set_config('app.cambio_normativo_en_curso', 'false', true);
  UPDATE core.cambio_normativo SET aprobado_por = p_aprobado_por, aprobado_en = now(), aplicado_en = now() WHERE id = p_cambio_id;
END $$;


--
-- Name: autenticar_usuario(text, text); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.autenticar_usuario(p_dni text, p_password text) RETURNS TABLE(usuario_id uuid, codigo_legado text, nombre text, dni text, email text, cargo text, unidad_siglas text, rol_codigo text, roles text[], regiones text[])
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'core', 'public'
    AS $$
    with candidato as (
        select u.*
          from core.usuarios u
         where btrim(u.dni) = btrim(p_dni)
           and u.activo
           and u.clave_hash is not null
           and u.clave_hash = crypt(p_password, u.clave_hash)
    ),
    roles_vigentes as (
        select ur.usuario_id,
               array_agg(
                   ro.codigo::text
                   order by case ro.codigo
                       when 'administrador' then 1
                       when 'direccion_oaipcs' then 2
                       when 'alta_direccion' then 3
                       when 'sectorista' then 4
                       when 'consulta_lectura' then 5
                       when 'auditor' then 6
                       when 'analista_cualitativo' then 7
                       when 'curador_politica' then 8
                       when 'servicio_agente' then 9
                       when 'externo_publico' then 10
                       else 99
                   end
               ) as roles
          from core.usuario_roles ur
          join core.roles ro on ro.id = ur.rol_id
         where ur.hasta is null or ur.hasta >= current_date
         group by ur.usuario_id
    )
    select c.id,
           c.codigo_legado::text,
           c.nombre::text,
           c.dni::text,
           c.email::text,
           c.cargo::text,
           cu.siglas::text,
           rv.roles[1],
           rv.roles,
           (select array_agg(reg.nombre::text order by reg.nombre)
              from core.usuario_territorio ut
              join core.regiones reg on reg.id = ut.region_id
             where ut.usuario_id = c.id)
      from candidato c
      left join core.cat_unidades_organicas cu on cu.id = c.unidad_id
      left join roles_vigentes rv on rv.usuario_id = c.id;
$$;


--
-- Name: FUNCTION autenticar_usuario(p_dni text, p_password text); Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON FUNCTION core.autenticar_usuario(p_dni text, p_password text) IS 'Autentica por DNI y clave bcrypt. `rol_codigo` es el rol de mayor jerarquía: administrador > direccion_oaipcs > alta_direccion > sectorista > …';


--
-- Name: bloquear_escritura_directa(); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.bloquear_escritura_directa() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF COALESCE(current_setting('app.cambio_normativo_en_curso', true), '') <> 'true' THEN
    RAISE EXCEPTION 'core.%: escritura directa no permitida. Use core.aplicar_cambio_normativo() — este catálogo representa la tipología oficial de la Guía (RM N.° 00207-2026-PRODUCE) y solo cambia por decisión del admin.', TG_TABLE_NAME;
  END IF;
  RETURN COALESCE(NEW, OLD);
END $$;


--
-- Name: caso_historial(); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.caso_historial() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT' OR (NEW.nivel_conflicto_id, NEW.nivel_riesgo_id, NEW.estado_id)
     IS DISTINCT FROM (OLD.nivel_conflicto_id, OLD.nivel_riesgo_id, OLD.estado_id) THEN
    UPDATE core.caso_estado_historial SET hasta = now() WHERE caso_id = NEW.id AND hasta IS NULL;
    INSERT INTO core.caso_estado_historial (caso_id, nivel_conflicto_id, nivel_riesgo_id, estado_id, usuario_id)
    VALUES (NEW.id, NEW.nivel_conflicto_id, NEW.nivel_riesgo_id, NEW.estado_id,
            NULLIF(current_setting('app.user_id', true), '')::uuid);
  END IF;
  RETURN NEW;
END $$;


--
-- Name: FUNCTION caso_historial(); Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON FUNCTION core.caso_historial() IS 'Mantiene core.caso_estado_historial. El alta del nodo en el grafo la hace kag.caso_nace() desde el parche 11.';


--
-- Name: caso_nudo_critico_valida_hito(); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.caso_nudo_critico_valida_hito() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_compromiso uuid;
BEGIN
    IF NEW.hito_id IS NULL THEN
        RETURN NEW;
    END IF;

    SELECT h.compromiso_id INTO v_compromiso
    FROM core.hitos_compromiso h
    WHERE h.id = NEW.hito_id;

    IF v_compromiso IS NULL THEN
        RAISE EXCEPTION 'El hito % no existe o no tiene compromiso', NEW.hito_id;
    END IF;

    IF NEW.compromiso_id IS NOT NULL AND NEW.compromiso_id <> v_compromiso THEN
        RAISE EXCEPTION 'Incoherencia: el hito % pertenece al compromiso %, no a %',
            NEW.hito_id, v_compromiso, NEW.compromiso_id;
    END IF;

    NEW.compromiso_id := v_compromiso;
    RETURN NEW;
END;
$$;


--
-- Name: FUNCTION caso_nudo_critico_valida_hito(); Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON FUNCTION core.caso_nudo_critico_valida_hito() IS 'El hito manda: completa compromiso_id y rechaza un nudo que intente colgar de un hito ajeno.';


--
-- Name: casos_touch_actualizacion(); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.casos_touch_actualizacion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW IS DISTINCT FROM OLD THEN
        NEW.fecha_ultima_actualizacion := now();
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: FUNCTION casos_touch_actualizacion(); Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON FUNCTION core.casos_touch_actualizacion() IS 'Mantiene core.casos.fecha_ultima_actualizacion al día en cada UPDATE real de la fila.';


--
-- Name: chk_compromiso(); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.chk_compromiso() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE v_cod text;
BEGIN
  SELECT codigo INTO v_cod FROM core.cat_estados_compromiso WHERE id = NEW.estado_id;
  IF v_cod = 'Cumplido' AND NEW.evidencia_cumplimiento_uri IS NULL THEN
    RAISE EXCEPTION 'Compromiso % no puede cerrarse como Cumplido sin evidencia (Protocolo SGSD/SSGC)', NEW.codigo_compromiso;
  END IF;
  IF v_cod = 'Redefinido' AND NOT EXISTS (SELECT 1 FROM core.compromisos x WHERE x.redefinido_de_id = NEW.id) AND TG_OP = 'UPDATE' THEN
    NULL;  -- la fila sucesora se inserta después; la unicidad la garantiza UNIQUE(redefinido_de_id)
  END IF;
  RETURN NEW;
END $$;


--
-- Name: chk_outbox_aprobacion(); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.chk_outbox_aprobacion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.estado_id IN (2,3,4) THEN
    IF NEW.aprobado_por IS NULL THEN
      RAISE EXCEPTION 'core.outbox_integracion %: no puede pasar al estado % sin aprobado_por (gate HITL)',
                      NEW.id, NEW.estado_id;
    END IF;
    IF NEW.aprobado_en IS NULL THEN NEW.aprobado_en := now(); END IF;
    IF NEW.proximo_intento_en IS NULL THEN NEW.proximo_intento_en := now(); END IF;
  END IF;
  RETURN NEW;
END $$;


