--

CREATE FUNCTION core.codigo_subsector(p_subsector_id integer) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select case p_subsector_id
           when 1 then 'PA'    -- Pesca y Acuicultura
           when 2 then 'MI'    -- MYPE e Industria
           else 'GEN'          -- sin subsector asignado
         end;
$$;


--
-- Name: FUNCTION codigo_subsector(p_subsector_id integer); Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON FUNCTION core.codigo_subsector(p_subsector_id integer) IS 'Sigla del subsector para el código de caso del Anexo 15: 1=PA (Pesca y Acuicultura), 2=MI (MYPE e Industria), null/otro=GEN (sin clasificar).';


--
-- Name: codigo_tematica(integer); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.codigo_tematica(p_tematica_id integer) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select case p_tematica_id
           when 1 then 'INF'   -- Infraestructura (fijado por la Guía)
           when 2 then 'OAT'   -- Ordenamiento y acceso territorial
           when 3 then 'NOR'   -- Normatividad
           when 4 then 'DBE'   -- Distribución de beneficios
           when 5 then 'GOB'   -- Gobernanza
           when 6 then 'ITE'   -- Impactos de terceros
           else 'GEN'          -- sin temática asignada
         end;
$$;


--
-- Name: FUNCTION codigo_tematica(p_tematica_id integer); Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON FUNCTION core.codigo_tematica(p_tematica_id integer) IS 'Sigla de la temática para el código de caso del Anexo 15. La Guía sólo fija INF; OAT/NOR/DBE/GOB/ITE son el acuerdo de la migración 16; null/otro=GEN (sin clasificar).';


--
-- Name: crear_particion(text, text, date, date); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.crear_particion(p_schema text, p_tabla text, p_desde date, p_hasta date) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  EXECUTE format('CREATE TABLE IF NOT EXISTS %I.%I PARTITION OF %I.%I FOR VALUES FROM (%L) TO (%L)',
                 p_schema, p_tabla || '_' || to_char(p_desde, 'YYYYMM'), p_schema, p_tabla, p_desde, p_hasta);
END $$;


--
-- Name: deriv_limite(); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.deriv_limite() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE v_sla smallint;
BEGIN
  SELECT p.sla_horas INTO v_sla FROM core.alertas_tempranas a JOIN core.cat_prioridades_alerta p ON p.id = a.prioridad_id WHERE a.id = NEW.alerta_id;
  IF NEW.fecha_limite IS NULL AND v_sla IS NOT NULL THEN NEW.fecha_limite := NEW.fecha_derivacion + make_interval(hours => v_sla); END IF;
  RETURN NEW;
END $$;


--
-- Name: etl_conteos(); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.etl_conteos() RETURNS TABLE(esquema text, tabla text, filas bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_esquema text;
  v_tabla text;
begin
  foreach v_esquema in array array['core', 'legacy', 'staging']
  loop
    for v_tabla in
      select c.relname::text
      from pg_class c
      join pg_namespace n on n.oid = c.relnamespace
      where n.nspname = v_esquema
        and c.relkind in ('r', 'p')
      order by c.relname
    loop
      return query execute format(
        'select %L::text, %L::text, count(*)::bigint from %I.%I',
        v_esquema, v_tabla, v_esquema, v_tabla
      );
    end loop;
  end loop;
end;
$$;


--
-- Name: FUNCTION etl_conteos(); Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON FUNCTION core.etl_conteos() IS 'Conteos exactos por tabla de core, legacy y staging. SECURITY DEFINER: sólo cardinalidades, nunca filas. Consumida por /api/v1/etl/resumen.';


--
-- Name: exigir_anulacion(smallint); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.exigir_anulacion(p_nivel smallint) RETURNS void
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'core'
    AS $$
begin
  if not core.puede_eliminar() then
    raise exception 'Su rol no permite anular ni restaurar registros'
      using errcode = '42501';
  end if;

  if coalesce(p_nivel, 99) > core.clasificacion_max() then
    raise exception 'El registro excede su nivel de acceso'
      using errcode = '42501';
  end if;
end $$;


--
-- Name: icd_aplicar_ajuste(numeric, numeric); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.icd_aplicar_ajuste(p_base numeric, p_ajuste numeric) RETURNS TABLE(icd_analista numeric, ajuste_propuesto numeric, ajuste_aplicado numeric, ajuste_recortado boolean, icd_final numeric)
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_tope numeric;
BEGIN
    IF p_base IS NULL THEN
        RAISE EXCEPTION 'ICD: la base del analista (p_base) es obligatoria; no se sustituye por un valor inventado'
            USING ERRCODE = 'null_value_not_allowed',
                  HINT = 'Calcular el ICD del analista con las seis condiciones y su evidencia (mvp.md K5).';
    END IF;

    SELECT (valor #>> '{}')::numeric
      INTO v_tope
      FROM config.parametro
     WHERE codigo = 'ICD.ajuste_tope_puntos'
       AND valid_to IS NULL;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'ICD: falta el parámetro vigente config.parametro(codigo = ''ICD.ajuste_tope_puntos'')'
            USING ERRCODE = 'no_data_found',
                  HINT = 'Ejecutar docs/PARCHE_8_ICD_TOPE_Q40.sql (Q40: tope de ±10 puntos).';
    END IF;

    IF v_tope IS NULL OR v_tope < 0 THEN
        RAISE EXCEPTION 'ICD: el tope del ajuste debe ser un número mayor o igual que 0 (valor leído: %)', v_tope
            USING ERRCODE = 'invalid_parameter_value';
    END IF;

    icd_analista     := p_base;
    ajuste_propuesto := p_ajuste;

    IF p_ajuste IS NULL THEN
        ajuste_aplicado  := 0;
        ajuste_recortado := false;
    ELSE
        ajuste_aplicado  := greatest(-v_tope, least(v_tope, p_ajuste));
        ajuste_recortado := (ajuste_aplicado <> p_ajuste);
    END IF;

    icd_final := greatest(0, least(100, icd_analista + ajuste_aplicado));

    RETURN NEXT;
END;
$$;


--
-- Name: FUNCTION icd_aplicar_ajuste(p_base numeric, p_ajuste numeric); Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON FUNCTION core.icd_aplicar_ajuste(p_base numeric, p_ajuste numeric) IS 'Q40 (AVISA_PRODUCE_v10.md §18.ter; decisión v10 en §8.4.ter y mvp.md K5): acota el ajuste automático del ICD al tope vigente en config.parametro (codigo = ''ICD.ajuste_tope_puntos'', hoy 10) y devuelve ICD del analista y ajuste aplicado en columnas separadas, rotulable como PROXY. Nunca mezcla la evaluación del analista con la corrección de la máquina.';


--
-- Name: normalizar_ref(text); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.normalizar_ref(p_texto text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  select regexp_replace(
           translate(
             lower(coalesce(p_texto, '')),
             'áéíóúüñ',
             'aeiouun'
           ),
           '[\s_\-]+',
           '',
           'g'
         );
$$;


--
-- Name: FUNCTION normalizar_ref(p_texto text); Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON FUNCTION core.normalizar_ref(p_texto text) IS 'Clave de comparación tolerante para referencias de catálogo: minúsculas, sin tildes ni separadores (En_ejecucion = En ejecución).';


--
-- Name: puede_aprobar(uuid, text); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.puede_aprobar(p_usuario uuid, p_objeto text DEFAULT 'aprobacion_alerta'::text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'core'
    AS $$
    SELECT p_usuario IS NOT NULL
       AND (
            --  Camino 1 · tiene el rol de la Dirección y la asignación está
            --  vigente hoy: `hasta` nulo significa «abierta».
            EXISTS (
                SELECT 1
                  FROM core.usuario_roles ur
                  JOIN core.roles r ON r.id = ur.rol_id
                 WHERE ur.usuario_id = p_usuario
                   AND r.codigo = 'direccion_oaipcs'
                   AND ur.desde <= CURRENT_DATE
                   AND (ur.hasta IS NULL OR ur.hasta >= CURRENT_DATE))
            OR
            --  Camino 2 · tiene una suplencia vigente para ese objeto.
            EXISTS (
                SELECT 1
                  FROM core.permiso_aprobacion pa
                 WHERE pa.usuario_id = p_usuario
                   AND pa.objeto = p_objeto
                   AND pa.vigente_desde <= CURRENT_DATE
                   AND (pa.vigente_hasta IS NULL OR pa.vigente_hasta >= CURRENT_DATE))
       );
$$;


--
-- Name: FUNCTION puede_aprobar(p_usuario uuid, p_objeto text); Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON FUNCTION core.puede_aprobar(p_usuario uuid, p_objeto text) IS 'true si el usuario puede aprobar el objeto indicado: o tiene el rol direccion_oaipcs vigente en core.usuario_roles, o tiene una suplencia vigente en core.permiso_aprobacion para ese objeto. p_objeto vale aprobacion_alerta por defecto. No escribe nada y no sustituye al gate G21: el gate sigue exigiendo las dos firmas en la alerta';


