-- Name: restaurar_caso(uuid); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.restaurar_caso(p_caso_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'core'
    AS $_$
declare
  v_lote uuid;
  v_nivel smallint;
  v_total integer := 0;
  v_tablas text[] := array[
    'caso_cronologia', 'alertas_tempranas', 'demandas',
    'compromisos', 'hitos_compromiso', 'documentos', 'casos'
  ];
  t text;
begin
  select anulacion_id, nivel_clasificacion into v_lote, v_nivel
    from core.casos
   where id = p_caso_id and anulado_en is not null;

  if v_lote is null then
    raise exception 'El caso no existe o no está anulado'
      using errcode = 'P0002';
  end if;

  perform core.exigir_anulacion(v_nivel);

  foreach t in array v_tablas loop
    execute format(
      'update core.%I
          set anulado_en = null, anulado_por = null,
              anulacion_id = null, motivo_anulacion = null
        where anulacion_id = $1', t)
      using v_lote;
    v_total := v_total + 1;
  end loop;

  return jsonb_build_object('anulacionId', v_lote, 'tablas', v_total);
end $_$;


--
-- Name: restaurar_registro(text, uuid); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.restaurar_registro(p_tabla text, p_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'core'
    AS $_$
declare
  v_lote uuid;
  v_nivel smallint;
  n integer := 0;
  v_tablas text[] := array[
    'casos', 'alertas_tempranas', 'compromisos', 'hitos_compromiso',
    'documentos', 'demandas', 'caso_cronologia'
  ];
begin
  if not (p_tabla = any (v_tablas)) then
    raise exception 'Tabla no admitida para restauración: %', p_tabla
      using errcode = '22023';
  end if;

  execute format(
    'select anulacion_id, nivel_clasificacion from core.%I
      where id = $1 and anulado_en is not null', p_tabla)
    into v_lote, v_nivel using p_id;

  if v_lote is null then
    raise exception 'El registro no existe o no está anulado'
      using errcode = 'P0002';
  end if;

  perform core.exigir_anulacion(v_nivel);

  -- Restauración por fila: antes era `where anulacion_id = $1`, lo que
  -- levantaba todo el lote. `EXECUTE` no actualiza `FOUND`; el recuento va por
  -- `GET DIAGNOSTICS`.
  execute format(
    'update core.%I
        set anulado_en = null, anulado_por = null,
            anulacion_id = null, motivo_anulacion = null
      where id = $1', p_tabla)
    using p_id;
  get diagnostics n = row_count;

  -- Los hitos acompañan a su compromiso, igual que en `core.anular_registro`.
  if p_tabla = 'compromisos' then
    update core.hitos_compromiso
       set anulado_en = null, anulado_por = null,
           anulacion_id = null, motivo_anulacion = null
     where compromiso_id = p_id and anulado_en is not null;
  end if;

  return n;
end $_$;


--
-- Name: revertir_cambio_normativo(uuid, uuid); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.revertir_cambio_normativo(p_cambio_id uuid, p_revertido_por uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE c core.cambio_normativo%ROWTYPE;
BEGIN
  SELECT * INTO c FROM core.cambio_normativo WHERE id = p_cambio_id FOR UPDATE;
  IF c.aplicado_en IS NULL THEN RAISE EXCEPTION 'cambio_normativo % nunca se aplicó, no hay nada que revertir', p_cambio_id; END IF;
  IF c.revertido_en IS NOT NULL THEN RAISE EXCEPTION 'cambio_normativo % ya fue revertido', p_cambio_id; END IF;
  PERFORM set_config('app.cambio_normativo_en_curso', 'true', true);
  IF c.accion = 'insertar' THEN
    DELETE FROM core.cat_niveles_conflicto WHERE id = (c.payload_despues->>'id')::smallint;
  ELSIF c.accion = 'modificar' THEN
    UPDATE core.cat_niveles_conflicto SET codigo = c.payload_antes->>'codigo', nombre = c.payload_antes->>'nombre',
           orden = (c.payload_antes->>'orden')::smallint WHERE id = c.fila_id;
  ELSIF c.accion = 'desactivar' THEN
    INSERT INTO core.cat_niveles_conflicto (id, codigo, nombre, orden)
    SELECT c.fila_id, c.payload_antes->>'codigo', c.payload_antes->>'nombre', (c.payload_antes->>'orden')::smallint;
  END IF;
  PERFORM set_config('app.cambio_normativo_en_curso', 'false', true);
  UPDATE core.cambio_normativo SET revertido_en = now(), revertido_por = p_revertido_por WHERE id = p_cambio_id;
END $$;


