--
-- Name: siguiente_codigo(text, text, integer); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.siguiente_codigo(p_ambito text, p_prefijo text, p_ancho integer DEFAULT 3) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'core'
    AS $$
declare
  v_ultimo bigint;
begin
  insert into core.secuencia_codigo as s (ambito, ultimo, actualizado_en)
  values (p_ambito, 1, now())
  on conflict (ambito) do update
     set ultimo = s.ultimo + 1,
         actualizado_en = now()
  returning ultimo into v_ultimo;

  return p_prefijo || lpad(v_ultimo::text, greatest(coalesce(p_ancho, 3), 1), '0');
end $$;


