CREATE FUNCTION core.sync_hito_estado() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  UPDATE core.hitos_compromiso h SET estado_id = NEW.estado_id
   WHERE h.id = NEW.hito_id AND NEW.fecha_corte = (SELECT MAX(fecha_corte) FROM core.hitos_compromiso_estado_historico WHERE hito_id = NEW.hito_id);
  RETURN NEW;
END $$;


--
-- Name: tg_alerta_g21_visibilidad(); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.tg_alerta_g21_visibilidad() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_falta text[] := ARRAY[]::text[];
BEGIN
    --  El único caso libre es el valor de nacimiento. Cualquier otro exige
    --  las dos firmas, sin importar la prioridad ni la gravedad de la alerta:
    --  la gravedad decide el destinatario y el plazo, no quién autoriza.
    IF NEW.visibilidad IS NULL OR NEW.visibilidad = 'interna' THEN
        RETURN NEW;
    END IF;

    IF NOT (COALESCE(NEW.es_validado_humano, false)
            AND NEW.fecha_validacion IS NOT NULL
            AND NEW.validada_por IS NOT NULL
            AND COALESCE(NEW.paso_actual, 0) >= 2) THEN
        v_falta := v_falta || 'la validación previa del Sectorista (es_validado_humano, fecha_validacion, validada_por y paso_actual >= 2)'::text;
    END IF;

    IF NEW.aprobada_por IS NULL OR NEW.aprobada_en IS NULL THEN
        v_falta := v_falta || 'la aprobación definitiva de la Dirección de la OAIPCS (aprobada_por y aprobada_en)'::text;
    END IF;

    IF NEW.validada_por IS NOT NULL
       AND NEW.aprobada_por IS NOT NULL
       AND NEW.validada_por = NEW.aprobada_por THEN
        v_falta := v_falta || 'dos firmas de personas distintas: quien valida y quien aprueba no pueden ser la misma (H-79)'::text;
    END IF;

    --  La comprobación de destinatarios solo puede hacerse sobre una fila que
    --  ya existe, porque en un INSERT la clave todavía no sirve para buscar
    --  en la tabla hija. En el alta, la alerta nace `interna` y los
    --  destinatarios se añaden después; el paso a `sectorial` es un UPDATE y
    --  ahí sí se comprueba.
    IF NEW.visibilidad = 'sectorial' AND TG_OP = 'UPDATE' THEN
        IF NOT EXISTS (
            SELECT 1 FROM core.alerta_destinatario d WHERE d.alerta_id = NEW.id
        ) THEN
            v_falta := v_falta || 'al menos un destinatario nombrado para la visibilidad «sectorial» (core.alerta_destinatario)'::text;
        END IF;
    END IF;

    IF cardinality(v_falta) > 0 THEN
        RAISE EXCEPTION
            'G21_SIN_APROBACION: la alerta % no puede pasar a visibilidad «%»; falta %',
            NEW.codigo_alerta, NEW.visibilidad, array_to_string(v_falta, ' y ')
            USING ERRCODE = 'P0001';
    END IF;

    RETURN NEW;
END
$$;


--
-- Name: FUNCTION tg_alerta_g21_visibilidad(); Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON FUNCTION core.tg_alerta_g21_visibilidad() IS 'Gate G21: rechaza con ERRCODE P0001 y mensaje G21_SIN_APROBACION cualquier visibilidad distinta de interna mientras falte la validación previa del Sectorista (con autor y fecha), la aprobación definitiva de la Dirección, la distinción de personas entre ambas firmas o, para la visibilidad sectorial, al menos un destinatario nombrado. Las alertas internas, incluidas las 83 migradas, pasan sin comprobación';


--
-- Name: tg_alerta_nace(); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.tg_alerta_nace() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'core'
    AS $$
DECLARE
    v_fila smallint;
    v_def  uuid;
    v_est  uuid;
BEGIN
    SELECT id INTO v_def
      FROM core.flujo_definicion
     WHERE tipo_flujo = 'alerta' AND orden = 1
     LIMIT 1;
    SELECT id INTO v_est FROM core.flujo_estado WHERE codigo = 'EST-01';

    -- Si falta el catálogo del flujo, no se bloquea el alta de la alerta:
    -- se deja sin fila de proceso y el rellenado del parche la recoge.
    IF v_def IS NULL OR v_est IS NULL THEN
        RETURN NEW;
    END IF;

    -- El UNIQUE (tipo_origen, fila_legado) convierte el max()+1 en una carrera:
    -- dos altas simultáneas calculan el mismo número y la segunda aborta el
    -- INSERT de la alerta. Se serializa por tipo de origen; el bloqueo se
    -- suelta al cerrar la transacción que inserta la alerta.
    PERFORM pg_advisory_xact_lock(hashtext('core.proceso_instancia:alerta'));

    SELECT COALESCE(max(fila_legado), 0) + 1
      INTO v_fila
      FROM core.proceso_instancia
     WHERE tipo_origen = 'alerta';

    INSERT INTO core.proceso_instancia
        (tipo_origen, alerta_id, flujo_definicion_id, estado_id, orden,
         codigo_legado, fila_legado, ocurrido_en, nota, nivel_clasificacion)
    VALUES
        ('alerta', NEW.id, v_def, v_est, 1,
         'ALERTA-' || NEW.codigo_alerta, v_fila, now(),
         'Paso inicial creado automáticamente al registrar la alerta',
         NEW.nivel_clasificacion);

    RETURN NEW;
END
$$;


--
-- Name: tg_audit_datos_personales(); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.tg_audit_datos_personales() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'core', 'audit'
    AS $$
DECLARE
    v_actor  uuid;
    v_campos text[];
BEGIN
    IF TG_OP = 'DELETE' THEN
        v_actor := OLD.actor_uid;
    ELSE
        v_actor := NEW.actor_uid;
    END IF;

    IF TG_OP = 'UPDATE' THEN
        SELECT array_agg(COALESCE(n.key, o.key) ORDER BY COALESCE(n.key, o.key))
          INTO v_campos
          FROM jsonb_each(to_jsonb(NEW)) n
          FULL JOIN jsonb_each(to_jsonb(OLD)) o ON o.key = n.key
         WHERE n.value IS DISTINCT FROM o.value;
    END IF;

    INSERT INTO audit.datos_personales_acceso
        (usuario, operacion, actor_uid, motivo, filas_afectadas, contexto)
    VALUES
        (session_user, lower(TG_OP), v_actor, NULL, 1,
         jsonb_build_object(
             'origen', COALESCE(NULLIF(current_setting('app.p9_origen', true), ''), 'aplicacion'),
             'tabla',  TG_TABLE_SCHEMA || '.' || TG_TABLE_NAME,
             'campos', to_jsonb(COALESCE(v_campos, ARRAY[]::text[]))));

    RETURN NULL;
END $$;


--
-- Name: FUNCTION tg_audit_datos_personales(); Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON FUNCTION core.tg_audit_datos_personales() IS 'Registra en audit.datos_personales_acceso cada INSERT/UPDATE/DELETE de la tabla de PII, con las columnas que cambiaron y el origen (aplicacion o PARCHE_9).';


