--
-- Name: tg_flujo_def_valida_rol(); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.tg_flujo_def_valida_rol() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'core'
    AS $$
DECLARE
    v_token text;
BEGIN
    IF NEW.rol_responsable IS NULL THEN
        RETURN NEW;
    END IF;

    FOREACH v_token IN ARRAY string_to_array(NEW.rol_responsable, ',') LOOP
        IF NOT EXISTS (SELECT 1 FROM core.roles r WHERE r.codigo = v_token) THEN
            RAISE EXCEPTION
                'rol_responsable: el token «%» no existe en core.roles.codigo',
                v_token;
        END IF;
    END LOOP;

    RETURN NEW;
END
$$;


--
-- Name: tg_pii_solo_identificados(); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.tg_pii_solo_identificados() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'core'
    AS $$
DECLARE
    v_nivel smallint;
BEGIN
    SELECT nivel_identificacion_id INTO v_nivel
      FROM core.actores WHERE actor_uid = NEW.actor_uid;

    IF v_nivel IS NOT NULL AND v_nivel >= 4 THEN
        RAISE EXCEPTION
            'ERS §12.4: el actor % es de nivel % (sin identificar); no puede '
            'tener datos personales.', NEW.actor_uid, v_nivel
            USING ERRCODE = 'check_violation';
    END IF;

    RETURN NEW;
END
$$;


--
-- Name: tiene_privilegio(text); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.tiene_privilegio(p_codigo text) RETURNS boolean
    LANGUAGE sql STABLE PARALLEL SAFE
    SET search_path TO 'pg_catalog', 'core'
    AS $$
    SELECT EXISTS (
        SELECT 1
          FROM core.privilegio_usuario pu
          JOIN core.cat_privilegio cp ON cp.id = pu.privilegio_id
         WHERE cp.codigo   = p_codigo
           AND pu.activo
           AND pu.usuario_id = core.usuario_actual()
           AND pu.desde <= CURRENT_DATE
           AND (pu.hasta IS NULL OR pu.hasta >= CURRENT_DATE)
    );
$$;


