--
-- Name: artefacto; Type: TABLE; Schema: domain; Owner: -
--

CREATE TABLE domain.artefacto (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tipo_id uuid NOT NULL,
    caso_id uuid,
    sujeto_actor_uid uuid,
    sujeto_lugar_id uuid,
    sujeto_especie_id smallint,
    sujeto_documento_id uuid,
    payload jsonb NOT NULL,
    version_esquema character varying(10) DEFAULT '1.0'::character varying NOT NULL,
    estado_id smallint DEFAULT 1 NOT NULL,
    valid_from timestamp with time zone DEFAULT now() NOT NULL,
    valid_to timestamp with time zone,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    superseded_at timestamp with time zone,
    supersedes_id uuid,
    created_by uuid,
    updated_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    origen_dato character varying(20) DEFAULT 'MANUAL'::character varying NOT NULL,
    confidence numeric(3,2),
    es_validado_humano boolean DEFAULT false NOT NULL,
    nivel_clasificacion smallint DEFAULT 2 NOT NULL,
    CONSTRAINT artefacto_check CHECK (((valid_to IS NULL) OR (valid_to > valid_from))),
    CONSTRAINT artefacto_confidence_check CHECK (((confidence >= (0)::numeric) AND (confidence <= (1)::numeric))),
    CONSTRAINT artefacto_origen_dato_check CHECK (((origen_dato)::text = ANY (ARRAY[('MANUAL'::character varying)::text, ('KAG'::character varying)::text, ('WORKFLOW'::character varying)::text, ('AVISA_HISTORICO'::character varying)::text, ('WHATSAPP'::character varying)::text, ('AGENTE'::character varying)::text, ('IMPORT'::character varying)::text])))
);

ALTER TABLE ONLY domain.artefacto FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE artefacto; Type: COMMENT; Schema: domain; Owner: -
--

COMMENT ON TABLE domain.artefacto IS 'Artefacto de dominio versionado y bitemporal, con su carga útil, su sujeto, su estado de validación y su clasificación.';


--
-- Name: COLUMN artefacto.id; Type: COMMENT; Schema: domain; Owner: -
--

COMMENT ON COLUMN domain.artefacto.id IS 'Identificador interno de la fila';


--
-- Name: COLUMN artefacto.tipo_id; Type: COMMENT; Schema: domain; Owner: -
--

COMMENT ON COLUMN domain.artefacto.tipo_id IS 'Tipo de artefacto que define su esquema y reglas de validación';


--
-- Name: COLUMN artefacto.caso_id; Type: COMMENT; Schema: domain; Owner: -
--

COMMENT ON COLUMN domain.artefacto.caso_id IS 'Caso al que se vincula el artefacto cuando el tipo lo exige';


--
-- Name: COLUMN artefacto.sujeto_actor_uid; Type: COMMENT; Schema: domain; Owner: -
--

COMMENT ON COLUMN domain.artefacto.sujeto_actor_uid IS 'Actor sobre el que trata el artefacto, si su sujeto es una persona';


--
-- Name: COLUMN artefacto.sujeto_lugar_id; Type: COMMENT; Schema: domain; Owner: -
--

COMMENT ON COLUMN domain.artefacto.sujeto_lugar_id IS 'Lugar o caleta sobre el que trata el artefacto de dominio';


--
-- Name: COLUMN artefacto.sujeto_especie_id; Type: COMMENT; Schema: domain; Owner: -
--

COMMENT ON COLUMN domain.artefacto.sujeto_especie_id IS 'Especie del catálogo sobre la que trata el artefacto';


--
-- Name: COLUMN artefacto.sujeto_documento_id; Type: COMMENT; Schema: domain; Owner: -
--

COMMENT ON COLUMN domain.artefacto.sujeto_documento_id IS 'Documento fuente sobre el que se apoya o del que deriva el artefacto';


--
-- Name: COLUMN artefacto.payload; Type: COMMENT; Schema: domain; Owner: -
--

COMMENT ON COLUMN domain.artefacto.payload IS 'Contenido del artefacto en formato JSON, según su tipo y versión';


--
-- Name: COLUMN artefacto.version_esquema; Type: COMMENT; Schema: domain; Owner: -
--

COMMENT ON COLUMN domain.artefacto.version_esquema IS 'Versión del esquema de validación aplicada al contenido del artefacto';


--
-- Name: COLUMN artefacto.estado_id; Type: COMMENT; Schema: domain; Owner: -
--

COMMENT ON COLUMN domain.artefacto.estado_id IS 'Estado del ciclo de vida del artefacto dentro de su flujo de validación';


--
-- Name: COLUMN artefacto.valid_from; Type: COMMENT; Schema: domain; Owner: -
--

COMMENT ON COLUMN domain.artefacto.valid_from IS 'Inicio de la vigencia temporal del dato según el modelo bitemporal';


--
-- Name: COLUMN artefacto.valid_to; Type: COMMENT; Schema: domain; Owner: -
--

COMMENT ON COLUMN domain.artefacto.valid_to IS 'Fin de la vigencia temporal del dato; nulo si sigue vigente';


--
-- Name: COLUMN artefacto.recorded_at; Type: COMMENT; Schema: domain; Owner: -
--

COMMENT ON COLUMN domain.artefacto.recorded_at IS 'Momento en que el sistema registró el artefacto en la base';


--
-- Name: COLUMN artefacto.superseded_at; Type: COMMENT; Schema: domain; Owner: -
--

COMMENT ON COLUMN domain.artefacto.superseded_at IS 'Momento en que el artefacto fue reemplazado por una versión nueva';


--
-- Name: COLUMN artefacto.supersedes_id; Type: COMMENT; Schema: domain; Owner: -
--

COMMENT ON COLUMN domain.artefacto.supersedes_id IS 'Artefacto anterior al que esta versión reemplaza';


--
-- Name: COLUMN artefacto.created_by; Type: COMMENT; Schema: domain; Owner: -
--

COMMENT ON COLUMN domain.artefacto.created_by IS 'Usuario que registró el artefacto en el sistema';


--
-- Name: COLUMN artefacto.updated_by; Type: COMMENT; Schema: domain; Owner: -
--

COMMENT ON COLUMN domain.artefacto.updated_by IS 'Usuario que realizó la última modificación del artefacto';


--
-- Name: COLUMN artefacto.created_at; Type: COMMENT; Schema: domain; Owner: -
--

COMMENT ON COLUMN domain.artefacto.created_at IS 'Momento en que se creó el registro';


--
-- Name: COLUMN artefacto.updated_at; Type: COMMENT; Schema: domain; Owner: -
--

COMMENT ON COLUMN domain.artefacto.updated_at IS 'Momento de la última modificación del registro';


--
-- Name: COLUMN artefacto.origen_dato; Type: COMMENT; Schema: domain; Owner: -
--

COMMENT ON COLUMN domain.artefacto.origen_dato IS 'Procedencia del registro: legado, captura manual o agente';


--
-- Name: COLUMN artefacto.confidence; Type: COMMENT; Schema: domain; Owner: -
--

COMMENT ON COLUMN domain.artefacto.confidence IS 'Grado de certeza del dato, entre 0 y 1';


--
-- Name: COLUMN artefacto.es_validado_humano; Type: COMMENT; Schema: domain; Owner: -
--

COMMENT ON COLUMN domain.artefacto.es_validado_humano IS 'Indica si una persona revisó y validó el contenido del artefacto';


--
-- Name: COLUMN artefacto.nivel_clasificacion; Type: COMMENT; Schema: domain; Owner: -
--

COMMENT ON COLUMN domain.artefacto.nivel_clasificacion IS 'Nivel de acceso al dato: 1 público, 2 reservado, 3 confidencial';


--
-- Name: artefacto_en(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: domain; Owner: -
--

CREATE FUNCTION domain.artefacto_en(p_id uuid, p_valido_en timestamp with time zone DEFAULT now(), p_conocido_en timestamp with time zone DEFAULT now()) RETURNS domain.artefacto
    LANGUAGE sql STABLE
    AS $$
  WITH RECURSIVE cadena AS (
    SELECT * FROM domain.artefacto WHERE id = p_id
    UNION ALL
    SELECT a.* FROM domain.artefacto a JOIN cadena c ON a.id = c.supersedes_id
  )
  SELECT * FROM cadena
   WHERE valid_from <= p_valido_en AND (valid_to IS NULL OR valid_to > p_valido_en)
     AND recorded_at <= p_conocido_en AND (superseded_at IS NULL OR superseded_at > p_conocido_en)
   ORDER BY recorded_at DESC LIMIT 1;
$$;


--
-- Name: artefacto_supersede(); Type: FUNCTION; Schema: domain; Owner: -
--

CREATE FUNCTION domain.artefacto_supersede() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.supersedes_id IS NOT NULL THEN
    UPDATE domain.artefacto SET superseded_at = NEW.recorded_at WHERE id = NEW.supersedes_id AND superseded_at IS NULL;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: chk_transicion(); Type: FUNCTION; Schema: domain; Owner: -
--

CREATE FUNCTION domain.chk_transicion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND OLD.estado_id IS DISTINCT FROM NEW.estado_id THEN
    IF NOT EXISTS (
      SELECT 1 FROM domain.regla_negocio r
       WHERE r.tipo_artefacto_id = NEW.tipo_id AND r.tipo_regla = 'transicion' AND r.activo
         AND r.estado_desde_id = OLD.estado_id AND r.estado_hasta_id = NEW.estado_id
    ) THEN
      RAISE EXCEPTION 'domain.artefacto: transición % -> % no permitida para el tipo %', OLD.estado_id, NEW.estado_id,
        (SELECT codigo FROM domain.tipo_artefacto WHERE id = NEW.tipo_id);
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: validar_artefacto(); Type: FUNCTION; Schema: domain; Owner: -
--

CREATE FUNCTION domain.validar_artefacto() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE v_tipo domain.tipo_artefacto%ROWTYPE; v_campo text; v_req jsonb;
BEGIN
  SELECT * INTO v_tipo FROM domain.tipo_artefacto WHERE id = NEW.tipo_id;
  IF v_tipo.estado <> 'activo' THEN
    RAISE EXCEPTION 'domain.artefacto: tipo % no está activo', v_tipo.codigo;
  END IF;
  IF v_tipo.requiere_caso AND NEW.caso_id IS NULL THEN
    RAISE EXCEPTION 'domain.artefacto: tipo % requiere caso_id', v_tipo.codigo;
  END IF;
  IF v_tipo.sujeto_requerido = 'actor' AND NEW.sujeto_actor_uid IS NULL THEN
    RAISE EXCEPTION 'domain.artefacto: tipo % requiere sujeto_actor_uid', v_tipo.codigo;
  END IF;
  IF v_tipo.sujeto_requerido = 'lugar' AND NEW.sujeto_lugar_id IS NULL THEN
    RAISE EXCEPTION 'domain.artefacto: tipo % requiere sujeto_lugar_id', v_tipo.codigo;
  END IF;
  v_req := v_tipo.esquema_json -> 'required';
  IF v_req IS NOT NULL THEN
    FOR v_campo IN SELECT jsonb_array_elements_text(v_req) LOOP
      IF NOT (NEW.payload ? v_campo) THEN
        RAISE EXCEPTION 'domain.artefacto: payload no tiene el campo requerido "%" (tipo %)', v_campo, v_tipo.codigo;
      END IF;
    END LOOP;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: chk_brecha_capacidad(); Type: FUNCTION; Schema: ind; Owner: -
--

CREATE FUNCTION ind.chk_brecha_capacidad() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE v_cap NUMERIC; v_carga NUMERIC;
BEGIN
  IF NEW.estado IN ('aprobada','en_campo') AND NEW.requiere_campo
     AND (TG_OP = 'INSERT' OR OLD.estado NOT IN ('aprobada','en_campo')) THEN
    IF NEW.decision_escrita_uri IS NULL THEN
      SELECT COALESCE(sum(horas_disponibles), 0) INTO v_cap FROM core.capacidad_campo WHERE mes = NEW.mes_previsto;
      SELECT COALESCE(sum(horas_estimadas), 0) INTO v_carga FROM ind.brecha
       WHERE mes_previsto = NEW.mes_previsto AND requiere_campo AND estado IN ('aprobada','en_campo') AND id <> NEW.id;
      IF v_carga + NEW.horas_estimadas > v_cap THEN
        RAISE EXCEPTION 'la brecha excede la capacidad de campo de % (% h cargadas + % h > % h): requiere decisión escrita o un proxy',
          NEW.mes_previsto, v_carga, NEW.horas_estimadas, v_cap;
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: chk_sin_ciclo(); Type: FUNCTION; Schema: ind; Owner: -
--

CREATE FUNCTION ind.chk_sin_ciclo() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.depende_de_indicador_id IS NULL THEN RETURN NEW; END IF;
  IF NEW.indicador_id = NEW.depende_de_indicador_id THEN
    RAISE EXCEPTION 'ind.relacion_dependencia: ciclo trivial % -> %', NEW.indicador_id, NEW.depende_de_indicador_id;
  END IF;
  IF EXISTS (
    WITH RECURSIVE alcanza AS (
      SELECT NEW.depende_de_indicador_id AS id, 1 AS d
      UNION
      SELECT rd.depende_de_indicador_id, a.d + 1
        FROM alcanza a JOIN ind.relacion_dependencia rd ON rd.indicador_id = a.id
       WHERE rd.depende_de_indicador_id IS NOT NULL AND a.d < 50
    )
    SELECT 1 FROM alcanza WHERE id = NEW.indicador_id
  ) THEN
    RAISE EXCEPTION 'ind.relacion_dependencia: ciclo detectado al insertar % -> %', NEW.indicador_id, NEW.depende_de_indicador_id;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: exigir_justificacion(); Type: FUNCTION; Schema: ind; Owner: -
--

CREATE FUNCTION ind.exigir_justificacion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.clase = 'proxy' AND NOT EXISTS (SELECT 1 FROM ind.proxy_justificacion WHERE variante_id = NEW.id) THEN
    RAISE EXCEPTION 'la variante proxy % requiere una fila en ind.proxy_justificacion', NEW.id;
  END IF;
  RETURN NULL;
END $$;


--
-- Name: actor_nace(); Type: FUNCTION; Schema: kag; Owner: -
--

CREATE FUNCTION kag.actor_nace() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  INSERT INTO kag.actor_name_history (actor_uid, nombre, valid_from, fuente)
  VALUES (NEW.actor_uid, NEW.nombre_actual, CURRENT_DATE, 'alta');
  PERFORM kag.nodo_asegura('actor', NEW.actor_uid, NEW.nombre_actual);
  RETURN NEW;
END $$;


--
-- Name: actor_renombra(); Type: FUNCTION; Schema: kag; Owner: -
--

CREATE FUNCTION kag.actor_renombra() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  UPDATE kag.nodos SET etiqueta = NEW.nombre_actual
   WHERE tipo = 'actor' AND ref_id = NEW.actor_uid
     AND etiqueta IS DISTINCT FROM NEW.nombre_actual;
  RETURN NEW;
END $$;


--
-- Name: arista_asegura(uuid, uuid, character varying, uuid, text, numeric, integer, character varying); Type: FUNCTION; Schema: kag; Owner: -
--

CREATE FUNCTION kag.arista_asegura(p_origen uuid, p_destino uuid, p_codigo character varying, p_caso uuid DEFAULT NULL::uuid, p_justificacion text DEFAULT NULL::text, p_confidence numeric DEFAULT 0.90, p_nivel integer DEFAULT 2, p_origen_dato character varying DEFAULT 'MIGRACION'::character varying) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE v_tipo SMALLINT; v_id UUID;
BEGIN
  IF p_origen IS NULL OR p_destino IS NULL OR p_origen = p_destino THEN
    RETURN NULL;
  END IF;

  SELECT id INTO v_tipo FROM kag.cat_tipos_arista WHERE codigo = p_codigo;
  IF v_tipo IS NULL THEN
    RAISE EXCEPTION 'tipo de arista desconocido: %', p_codigo;
  END IF;

  SELECT id INTO v_id FROM kag.aristas
   WHERE origen_id = p_origen AND destino_id = p_destino
     AND tipo_id = v_tipo AND superseded_at IS NULL;
  IF v_id IS NOT NULL THEN
    RETURN v_id;
  END IF;

  INSERT INTO kag.aristas (origen_id, destino_id, tipo_id, caso_id, justificacion,
                           valid_from, confidence, origen_dato, nivel_clasificacion)
  VALUES (p_origen, p_destino, v_tipo, p_caso, p_justificacion,
          now(), p_confidence, p_origen_dato, p_nivel)
  RETURNING id INTO v_id;
  RETURN v_id;
END $$;


--
-- Name: caso_actor_nace(); Type: FUNCTION; Schema: kag; Owner: -
--

CREATE FUNCTION kag.caso_actor_nace() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE v_actor UUID; v_caso UUID;
BEGIN
  SELECT kag.nodo_asegura('actor', a.actor_uid, a.nombre_actual) INTO v_actor
    FROM core.actores a WHERE a.actor_uid = NEW.actor_id;
  SELECT kag.nodo_asegura('caso', c.id, c.nombre_caso) INTO v_caso
    FROM core.casos c WHERE c.id = NEW.caso_id;
  PERFORM kag.arista_asegura(v_actor, v_caso, 'PARTICIPA_EN', NEW.caso_id,
    'Vínculo actor-caso registrado en core.casos_actores', 0.95, 2, 'MIGRACION');
  RETURN NEW;
END $$;


--
-- Name: caso_nace(); Type: FUNCTION; Schema: kag; Owner: -
--

CREATE FUNCTION kag.caso_nace() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  PERFORM kag.nodo_asegura('caso', NEW.id, NEW.nombre_caso);
  RETURN NEW;
END $$;


--
-- Name: caso_renombra(); Type: FUNCTION; Schema: kag; Owner: -
--

CREATE FUNCTION kag.caso_renombra() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  UPDATE kag.nodos SET etiqueta = NEW.nombre_caso
   WHERE tipo = 'caso' AND ref_id = NEW.id
     AND etiqueta IS DISTINCT FROM NEW.nombre_caso;
  RETURN NEW;
END $$;


--
-- Name: chk_hipotesis_en_salida(); Type: FUNCTION; Schema: kag; Owner: -
--

CREATE FUNCTION kag.chk_hipotesis_en_salida() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM kag.hipotesis_evidencia WHERE hipotesis_id = NEW.hipotesis_id) THEN
    RAISE EXCEPTION 'la hipótesis % no tiene evidencia enlazada y no puede citarse en una salida', NEW.hipotesis_id;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: demanda_actor_nace(); Type: FUNCTION; Schema: kag; Owner: -
--

CREATE FUNCTION kag.demanda_actor_nace() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE v_actor UUID; v_demanda UUID; v_caso UUID;
BEGIN
  SELECT kag.nodo_asegura('actor', a.actor_uid, a.nombre_actual) INTO v_actor
    FROM core.actores a WHERE a.actor_uid = NEW.actor_id;
  SELECT kag.nodo_asegura('demanda', d.id,
           coalesce(d.problema_3p, d.descripcion_demanda, 'Demanda ' || coalesce(d.codigo_legado, ''))),
         d.caso_id
    INTO v_demanda, v_caso
    FROM core.demandas d WHERE d.id = NEW.demanda_id;
  PERFORM kag.arista_asegura(v_actor, v_demanda, 'EXIGE', v_caso,
    'Demanda formulada por el actor, según core.demandas_actores', 0.90, 2, 'MIGRACION');
  RETURN NEW;
END $$;


--
-- Name: demanda_nace(); Type: FUNCTION; Schema: kag; Owner: -
--

CREATE FUNCTION kag.demanda_nace() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  PERFORM kag.nodo_asegura(
    'demanda', NEW.id,
    coalesce(NEW.problema_3p, NEW.descripcion_demanda, 'Demanda ' || coalesce(NEW.codigo_legado, ''))
  );
  RETURN NEW;
END $$;


--
-- Name: hereda_nivel_corrida(); Type: FUNCTION; Schema: kag; Owner: -
--

CREATE FUNCTION kag.hereda_nivel_corrida() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE v_nivel SMALLINT;
BEGIN
  IF TG_TABLE_NAME = 'comunidad' THEN
    SELECT nivel_clasificacion INTO v_nivel FROM kag.comunidad_corrida WHERE id = NEW.corrida_id;
  ELSE
    SELECT c.nivel_clasificacion INTO v_nivel FROM kag.comunidad c WHERE c.id = NEW.comunidad_id;
  END IF;
  NEW.nivel_clasificacion := GREATEST(NEW.nivel_clasificacion, COALESCE(v_nivel, 1));   -- el resumen hereda L
  RETURN NEW;
END $$;


--
-- Name: membresia_nace(); Type: FUNCTION; Schema: kag; Owner: -
--

CREATE FUNCTION kag.membresia_nace() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE v_persona UUID; v_org UUID;
BEGIN
  SELECT kag.nodo_asegura('actor', a.actor_uid, a.nombre_actual) INTO v_persona
    FROM core.actores a WHERE a.actor_uid = NEW.persona_uid;
  SELECT kag.nodo_asegura('actor', a.actor_uid, a.nombre_actual) INTO v_org
    FROM core.actores a WHERE a.actor_uid = NEW.organizacion_uid;
  PERFORM kag.arista_asegura(v_persona, v_org, 'MIEMBRO_DE', NULL,
    'Pertenencia registrada en core.actor_membresia', 0.95, 3, 'MIGRACION');
  RETURN NEW;
END $$;


--
-- Name: nodo_asegura(character varying, uuid, character varying); Type: FUNCTION; Schema: kag; Owner: -
--

CREATE FUNCTION kag.nodo_asegura(p_tipo character varying, p_ref uuid, p_etiqueta character varying) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE v_id UUID;
BEGIN
  INSERT INTO kag.nodos (tipo, ref_id, etiqueta)
  VALUES (p_tipo, p_ref, left(p_etiqueta, 255))
  ON CONFLICT (tipo, ref_id) DO UPDATE
    SET etiqueta = COALESCE(EXCLUDED.etiqueta, kag.nodos.etiqueta)
    WHERE kag.nodos.etiqueta IS DISTINCT FROM COALESCE(EXCLUDED.etiqueta, kag.nodos.etiqueta)
  RETURNING id INTO v_id;

  IF v_id IS NULL THEN
    SELECT id INTO v_id FROM kag.nodos WHERE tipo = p_tipo AND ref_id = p_ref;
  END IF;
  RETURN v_id;
END $$;


--
-- Name: nodo_toca(); Type: FUNCTION; Schema: kag; Owner: -
--

CREATE FUNCTION kag.nodo_toca() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END $$;


--
-- Name: nombre_cierra_previo(); Type: FUNCTION; Schema: kag; Owner: -
--

CREATE FUNCTION kag.nombre_cierra_previo() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  UPDATE kag.actor_name_history SET valid_to = GREATEST(valid_from, NEW.valid_from - 1)
   WHERE actor_uid = NEW.actor_uid AND valid_to IS NULL;
  RETURN NEW;
END $$;


--
-- Name: subgrafo(uuid, integer, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: kag; Owner: -
--

CREATE FUNCTION kag.subgrafo(p_nodo uuid, p_prof integer DEFAULT 2, p_valido_en timestamp with time zone DEFAULT now(), p_conocido_en timestamp with time zone DEFAULT now()) RETURNS TABLE(arista_id uuid, origen_id uuid, destino_id uuid, tipo_id smallint, intensidad smallint, profundidad integer)
    LANGUAGE sql STABLE
    AS $$
  WITH RECURSIVE act AS (
    SELECT a.* FROM kag.aristas a
     WHERE a.valid_from <= p_valido_en AND (a.valid_to IS NULL OR a.valid_to > p_valido_en)
       AND a.recorded_at <= p_conocido_en AND (a.superseded_at IS NULL OR a.superseded_at > p_conocido_en)
  ), alc(nodo_id, d, ruta) AS (
    SELECT p_nodo, 0, ARRAY[p_nodo]
    UNION ALL
    SELECT CASE WHEN a.origen_id = alc.nodo_id THEN a.destino_id ELSE a.origen_id END, alc.d + 1,
           alc.ruta || CASE WHEN a.origen_id = alc.nodo_id THEN a.destino_id ELSE a.origen_id END
      FROM alc JOIN act a ON a.origen_id = alc.nodo_id OR a.destino_id = alc.nodo_id
     WHERE alc.d < p_prof
       AND NOT (CASE WHEN a.origen_id = alc.nodo_id THEN a.destino_id ELSE a.origen_id END) = ANY (alc.ruta)
  ), vis AS (SELECT nodo_id, MIN(d) AS d FROM alc GROUP BY nodo_id)
  SELECT a.id, a.origen_id, a.destino_id, a.tipo_id, a.intensidad, LEAST(vo.d, vd.d) + 1
    FROM act a JOIN vis vo ON vo.nodo_id = a.origen_id JOIN vis vd ON vd.nodo_id = a.destino_id
   WHERE LEAST(vo.d, vd.d) < p_prof;
$$;


--
-- Name: sync_nombre_actual(); Type: FUNCTION; Schema: kag; Owner: -
--

CREATE FUNCTION kag.sync_nombre_actual() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.valid_to IS NULL THEN
    UPDATE core.actores SET nombre_actual = NEW.nombre, fecha_ultimo_cambio_nombre = NEW.valid_from WHERE actor_uid = NEW.actor_uid;
    UPDATE kag.nodos SET etiqueta = NEW.nombre WHERE tipo = 'actor' AND ref_id = NEW.actor_uid;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: chk_activo_requiere_aplicacion(); Type: FUNCTION; Schema: model; Owner: -
--

CREATE FUNCTION model.chk_activo_requiere_aplicacion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.estado = 'activo' AND NEW.aplicacion_id IS NULL THEN
    RAISE EXCEPTION 'model.model_card %: no puede estar activo sin aplicacion_id (5.1)', NEW.codigo;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: set_tipo_artefacto_nec_lote(); Type: FUNCTION; Schema: mype; Owner: -
--

CREATE FUNCTION mype.set_tipo_artefacto_nec_lote() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.tipo_artefacto_id IS NULL THEN
    NEW.tipo_artefacto_id := (SELECT id FROM domain.tipo_artefacto WHERE codigo = 'nec_lote' AND estado = 'activo');
    IF NEW.tipo_artefacto_id IS NULL THEN RAISE EXCEPTION 'domain.tipo_artefacto ''nec_lote'' no existe o no está activo'; END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: set_tipo_artefacto_cites_permiso(); Type: FUNCTION; Schema: pesca; Owner: -
--

CREATE FUNCTION pesca.set_tipo_artefacto_cites_permiso() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.tipo_artefacto_id IS NULL THEN
    NEW.tipo_artefacto_id := (SELECT id FROM domain.tipo_artefacto WHERE codigo = 'cites_permiso' AND estado = 'activo');
    IF NEW.tipo_artefacto_id IS NULL THEN RAISE EXCEPTION 'domain.tipo_artefacto ''cites_permiso'' no existe o no está activo'; END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: aviso_vencimiento(); Type: FUNCTION; Schema: policy; Owner: -
--

CREATE FUNCTION policy.aviso_vencimiento() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.disparador_vencimiento_fecha IS NOT NULL AND NEW.propuesto_por IS NOT NULL AND NEW.estado <> 'vencida' THEN
    INSERT INTO core.notificaciones (usuario_id, tipo, entidad_tipo, entidad_id, vence_en)
    VALUES (NEW.propuesto_por, 'regla_por_vencer', 'policy.regla', NEW.id, NEW.disparador_vencimiento_fecha::timestamptz);
  END IF;
  RETURN NEW;
END $$;


--
-- Name: chk_regla(); Type: FUNCTION; Schema: policy; Owner: -
--

CREATE FUNCTION policy.chk_regla() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE req TEXT[];
BEGIN
  SELECT claves_requeridas INTO req FROM policy.cat_tipos_regla WHERE id = NEW.tipo_regla_id;
  IF req IS NOT NULL AND cardinality(req) > 0 AND NOT (NEW.parametros ?& req) THEN
    RAISE EXCEPTION 'regla %: faltan claves requeridas en parametros (%)', NEW.codigo, req;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.estado = 'vigente' AND NEW.estado = 'vigente'
     AND (NEW.parametros IS DISTINCT FROM OLD.parametros OR NEW.texto IS DISTINCT FROM OLD.texto) THEN
    RAISE EXCEPTION 'una regla vigente no se edita: se sustituye con una fila nueva (supersedes_id)';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: contexto_activo(text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: policy; Owner: -
--

CREATE FUNCTION policy.contexto_activo(p_rol text, p_valido_en timestamp with time zone DEFAULT now(), p_conocido_en timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  SELECT jsonb_build_object('valido_en', p_valido_en, 'conocido_en', p_conocido_en,
           'reglas', COALESCE(jsonb_agg(jsonb_build_object('codigo', r.codigo, 'clase', r.clase, 'alcance', r.alcance,
                       'titulo', r.titulo, 'parametros', r.parametros)
                     ORDER BY CASE r.clase WHEN 'N' THEN 0 WHEN 'P' THEN 1 ELSE 2 END, r.codigo), '[]'::jsonb))
    FROM policy.reglas_activas(p_rol, p_valido_en, p_conocido_en) r
$$;


--
-- Name: crear_snapshot(text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: policy; Owner: -
--

CREATE FUNCTION policy.crear_snapshot(p_rol text, p_valido_en timestamp with time zone DEFAULT now(), p_conocido_en timestamp with time zone DEFAULT now()) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE v_id UUID := gen_random_uuid(); v_hash TEXT;
BEGIN
  SELECT encode(sha256(convert_to(COALESCE(string_agg(r.id::text, ',' ORDER BY r.id), ''), 'UTF8')), 'hex') INTO v_hash
    FROM policy.reglas_activas(p_rol, p_valido_en, p_conocido_en) r;
  INSERT INTO policy.snapshot (id, rol, valido_en, conocido_en, policy_hash) VALUES (v_id, p_rol, p_valido_en, p_conocido_en, v_hash);
  INSERT INTO policy.snapshot_regla (snapshot_id, regla_id)
    SELECT v_id, r.id FROM policy.reglas_activas(p_rol, p_valido_en, p_conocido_en) r;
  RETURN v_id;
END $$;


--
-- Name: regla; Type: TABLE; Schema: policy; Owner: -
--

CREATE TABLE policy.regla (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    codigo character varying(30) NOT NULL,
    clase character(1) NOT NULL,
    tipo_regla_id smallint NOT NULL,
    titulo character varying(200) NOT NULL,
    texto text NOT NULL,
    parametros jsonb DEFAULT '{}'::jsonb NOT NULL,
    alcance character varying(25) NOT NULL,
    estado character varying(12) DEFAULT 'borrador'::character varying NOT NULL,
    gobierno_id smallint,
    titular_id smallint,
    fuente_documento_id uuid,
    tipo_fuente character varying(25) NOT NULL,
    valid_from timestamp with time zone DEFAULT now() NOT NULL,
    valid_to timestamp with time zone,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    superseded_at timestamp with time zone,
    supersedes_id uuid,
    disparador_vencimiento_fecha date,
    disparador_vencimiento_evento text,
    propuesto_por uuid,
    aprobado_por uuid,
    aprobado_por_2 uuid,
    nivel_clasificacion smallint DEFAULT 2 NOT NULL,
    CONSTRAINT regla_alcance_check CHECK (((alcance)::text = ANY (ARRAY[('ordenamiento'::character varying)::text, ('seleccion_indicadores'::character varying)::text, ('encuadre'::character varying)::text, ('prompt_contexto'::character varying)::text]))),
    CONSTRAINT regla_check CHECK (((valid_to IS NULL) OR (valid_to > valid_from))),
    CONSTRAINT regla_check1 CHECK ((((tipo_fuente)::text <> 'hipotesis_analitica'::text) OR ((estado)::text <> 'vigente'::text))),
    CONSTRAINT regla_check2 CHECK (((clase = 'L'::bpchar) OR ((tipo_fuente)::text = 'hipotesis_analitica'::text) OR (fuente_documento_id IS NOT NULL))),
    CONSTRAINT regla_check3 CHECK (((clase <> 'P'::bpchar) OR ((estado)::text <> 'vigente'::text) OR ((aprobado_por IS NOT NULL) AND (aprobado_por_2 IS NOT NULL) AND (aprobado_por <> aprobado_por_2)))),
    CONSTRAINT regla_clase_check CHECK ((clase = ANY (ARRAY['N'::bpchar, 'P'::bpchar, 'L'::bpchar]))),
    CONSTRAINT regla_estado_check CHECK (((estado)::text = ANY (ARRAY[('borrador'::character varying)::text, ('en_tramite'::character varying)::text, ('vigente'::character varying)::text, ('suspendida'::character varying)::text, ('vencida'::character varying)::text, ('derogada'::character varying)::text]))),
    CONSTRAINT regla_parametros_check CHECK ((jsonb_typeof(parametros) = 'object'::text)),
    CONSTRAINT regla_tipo_fuente_check CHECK (((tipo_fuente)::text = ANY (ARRAY[('norma'::character varying)::text, ('discurso'::character varying)::text, ('plan_gobierno'::character varying)::text, ('instruccion_escrita'::character varying)::text, ('hipotesis_analitica'::character varying)::text])))
);

ALTER TABLE ONLY policy.regla FORCE ROW LEVEL SECURITY;


