COMMENT ON COLUMN agent.lessons_learned.created_at IS 'Momento en que se creó el registro';


--
-- Name: llm_call; Type: TABLE; Schema: agent; Owner: -
--

CREATE TABLE agent.llm_call (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    run_id uuid,
    ts timestamp with time zone DEFAULT now() NOT NULL,
    modelo character varying(80) NOT NULL,
    version_modelo character varying(40) NOT NULL,
    destino character varying(5) NOT NULL,
    temperatura numeric(3,2),
    prompt_hash character(64) NOT NULL,
    version_plantilla_prompt character varying(40),
    policy_snapshot_id uuid,
    tokens_in integer,
    tokens_out integer,
    latencia_ms integer,
    veredicto_guardrails jsonb,
    nivel_clasificacion smallint NOT NULL,
    tokens_thinking integer,
    thinking_budget integer,
    grounding_habilitado boolean DEFAULT false NOT NULL,
    store_habilitado boolean DEFAULT false NOT NULL,
    datos_anonimizados boolean DEFAULT false NOT NULL,
    costo_estimado_usd numeric(12,6),
    CONSTRAINT llm_call_check CHECK (((nivel_clasificacion < 3) OR ((destino)::text = 'local'::text))),
    CONSTRAINT llm_call_destino_check CHECK (((destino)::text = ANY (ARRAY[('local'::character varying)::text, ('nube'::character varying)::text])))
)
PARTITION BY RANGE (ts);

ALTER TABLE ONLY agent.llm_call FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE llm_call; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON TABLE agent.llm_call IS 'Registro de cada llamada a un modelo de lenguaje: modelo, versión, tokens, latencia, hash del prompt y veredicto de los guardrails.';


--
-- Name: COLUMN llm_call.id; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON COLUMN agent.llm_call.id IS 'Identificador interno de la fila';


--
-- Name: COLUMN llm_call.run_id; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON COLUMN agent.llm_call.run_id IS 'Ejecución del agente a la que pertenece la llamada, para agrupar su costo y su latencia';


--
-- Name: COLUMN llm_call.ts; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON COLUMN agent.llm_call.ts IS 'Momento en que se hizo la llamada al modelo, parte de su clave de partición';


--
-- Name: COLUMN llm_call.modelo; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON COLUMN agent.llm_call.modelo IS 'Nombre del modelo de lenguaje invocado en esta llamada';


--
-- Name: COLUMN llm_call.version_modelo; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON COLUMN agent.llm_call.version_modelo IS 'Versión exacta del modelo que respondió, necesaria para reproducir la salida';


--
-- Name: COLUMN llm_call.destino; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON COLUMN agent.llm_call.destino IS 'Destino de ejecución indicado con un código corto, según dónde corre el modelo';


--
-- Name: COLUMN llm_call.temperatura; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON COLUMN agent.llm_call.temperatura IS 'Temperatura usada al generar la respuesta, que fija su grado de variabilidad';


--
-- Name: COLUMN llm_call.prompt_hash; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON COLUMN agent.llm_call.prompt_hash IS 'Huella del prompt enviado, para detectar cambios sin guardar el texto completo';


--
-- Name: COLUMN llm_call.version_plantilla_prompt; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON COLUMN agent.llm_call.version_plantilla_prompt IS 'Versión de la plantilla de prompt aplicada, para rastrear el origen del texto';


--
-- Name: COLUMN llm_call.policy_snapshot_id; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON COLUMN agent.llm_call.policy_snapshot_id IS 'Instantánea de política vigente en la llamada, que fija sus reglas y límites';


--
-- Name: COLUMN llm_call.tokens_in; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON COLUMN agent.llm_call.tokens_in IS 'Cantidad de tokens consumidos por el prompt enviado al modelo';


--
-- Name: COLUMN llm_call.tokens_out; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON COLUMN agent.llm_call.tokens_out IS 'Cantidad de tokens producidos por el modelo en su respuesta';


--
-- Name: COLUMN llm_call.latencia_ms; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON COLUMN agent.llm_call.latencia_ms IS 'Tiempo de respuesta de la llamada al modelo, medido en milisegundos';


--
-- Name: COLUMN llm_call.veredicto_guardrails; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON COLUMN agent.llm_call.veredicto_guardrails IS 'Resultado de los filtros de seguridad aplicados al prompt y a la respuesta';


--
-- Name: COLUMN llm_call.nivel_clasificacion; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON COLUMN agent.llm_call.nivel_clasificacion IS 'Nivel de acceso al dato: 1 público, 2 reservado, 3 confidencial';


--
-- Name: COLUMN llm_call.tokens_thinking; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON COLUMN agent.llm_call.tokens_thinking IS 'Tokens de razonamiento interno. Google los cobra a precio de salida: es el costo oculto nº 1 de la ficha 13.3.1 y RM-11 exige que sea mínimo.';


--
-- Name: COLUMN llm_call.thinking_budget; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON COLUMN agent.llm_call.thinking_budget IS 'Valor de thinking_budget usado en la llamada. RM-11: 0 o el mínimo.';


--
-- Name: COLUMN llm_call.grounding_habilitado; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON COLUMN agent.llm_call.grounding_habilitado IS 'Si se activó búsqueda web. RM-13 lo prohíbe en ingesta y mandatos: queda en falso salvo excepción documentada.';


--
-- Name: COLUMN llm_call.store_habilitado; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON COLUMN agent.llm_call.store_habilitado IS 'Si Google conserva el contenido. RM-15 exige falso (Ley 29733).';


--
-- Name: COLUMN llm_call.datos_anonimizados; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON COLUMN agent.llm_call.datos_anonimizados IS 'Si el texto se anonimizó antes de salir (DNI y teléfonos retirados). RM-15.';


--
-- Name: COLUMN llm_call.costo_estimado_usd; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON COLUMN agent.llm_call.costo_estimado_usd IS 'Costo aproximado de la llamada, calculado por el servicio de aplicación. RNF-13: permite sumar consumo por servicio y por mes.';


