    alta date DEFAULT CURRENT_DATE NOT NULL,
    destinos_permitidos jsonb NOT NULL,
    estado character varying(10) DEFAULT 'activo'::character varying NOT NULL,
    CONSTRAINT modelo_registro_estado_check CHECK (((estado)::text = ANY (ARRAY[('activo'::character varying)::text, ('retirado'::character varying)::text])))
);


--
-- Name: TABLE modelo_registro; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON TABLE agent.modelo_registro IS 'Padrón de modelos autorizados, con versión, hash de pesos, destinos permitidos y estado, para saber qué modelo puede operar cada consulta.';


--
-- Name: COLUMN modelo_registro.id; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON COLUMN agent.modelo_registro.id IS 'Identificador interno de la fila';


--
-- Name: COLUMN modelo_registro.modelo; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON COLUMN agent.modelo_registro.modelo IS 'Nombre del modelo autorizado a operar en el sistema';


--
-- Name: COLUMN modelo_registro.version; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON COLUMN agent.modelo_registro.version IS 'Versión del modelo autorizado que queda bajo control de cambios';


--
-- Name: COLUMN modelo_registro.hash_pesos; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON COLUMN agent.modelo_registro.hash_pesos IS 'Huella de los pesos del modelo, para verificar que no se alteraron';


--
-- Name: COLUMN modelo_registro.alta; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON COLUMN agent.modelo_registro.alta IS 'Fecha en que el modelo se incorporó al padrón de modelos autorizados';


--
-- Name: COLUMN modelo_registro.destinos_permitidos; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON COLUMN agent.modelo_registro.destinos_permitidos IS 'Lista de destinos donde puede ejecutarse el modelo, en formato JSON';


--
-- Name: COLUMN modelo_registro.estado; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON COLUMN agent.modelo_registro.estado IS 'Situación del modelo en el padrón, como activo o retirado';


--
-- Name: plantilla_prompt; Type: TABLE; Schema: agent; Owner: -
--

CREATE TABLE agent.plantilla_prompt (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    codigo character varying(20) NOT NULL,
    version character varying(20) NOT NULL,
    hash_prompt character(64) NOT NULL,
    system_prompt text NOT NULL,
    few_shot_json jsonb DEFAULT '[]'::jsonb NOT NULL,
    output_schema_id character varying(60) NOT NULL,
    vigente_desde timestamp with time zone DEFAULT now() NOT NULL,
    vigente_hasta timestamp with time zone,
    supersedes_id uuid,
    activo boolean DEFAULT false NOT NULL,
    CONSTRAINT plantilla_prompt_codigo_check CHECK (((codigo)::text = ANY (ARRAY[('A1'::character varying)::text, ('A2'::character varying)::text, ('A3'::character varying)::text, ('critic'::character varying)::text])))
);


--
-- Name: TABLE plantilla_prompt; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON TABLE agent.plantilla_prompt IS 'Plantilla de prompt versionada por agente, con su prompt de sistema, ejemplos y esquema de salida, para auditar una respuesta contra su origen.';


--
-- Name: COLUMN plantilla_prompt.id; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON COLUMN agent.plantilla_prompt.id IS 'Identificador interno de la fila';


--
-- Name: COLUMN plantilla_prompt.codigo; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON COLUMN agent.plantilla_prompt.codigo IS 'Código corto que identifica la plantilla entre las de su mismo agente';


--
-- Name: COLUMN plantilla_prompt.version; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON COLUMN agent.plantilla_prompt.version IS 'Versión de la plantilla, que permite comparar lo generado con cada una';


--
-- Name: COLUMN plantilla_prompt.hash_prompt; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON COLUMN agent.plantilla_prompt.hash_prompt IS 'Huella del prompt de sistema, para comprobar que la respuesta provino de él';


--
-- Name: COLUMN plantilla_prompt.system_prompt; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON COLUMN agent.plantilla_prompt.system_prompt IS 'Texto del prompt de sistema que orienta el comportamiento del agente';


--
-- Name: COLUMN plantilla_prompt.few_shot_json; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON COLUMN agent.plantilla_prompt.few_shot_json IS 'Ejemplos de entrada y salida incluidos en el prompt para guiar al agente';


--
-- Name: COLUMN plantilla_prompt.output_schema_id; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON COLUMN agent.plantilla_prompt.output_schema_id IS 'Identificador del esquema que debe cumplir la salida esperada del agente';


--
-- Name: COLUMN plantilla_prompt.vigente_desde; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON COLUMN agent.plantilla_prompt.vigente_desde IS 'Momento desde el que la plantilla puede usarse en producción';


--
-- Name: COLUMN plantilla_prompt.vigente_hasta; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON COLUMN agent.plantilla_prompt.vigente_hasta IS 'Momento en que la plantilla deja de usarse, vacío mientras siga vigente';


--
-- Name: COLUMN plantilla_prompt.supersedes_id; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON COLUMN agent.plantilla_prompt.supersedes_id IS 'Versión anterior de la plantilla que esta reemplaza';


--
-- Name: COLUMN plantilla_prompt.activo; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON COLUMN agent.plantilla_prompt.activo IS 'Indica si la plantilla está habilitada para generar prompts';


--
-- Name: run_log; Type: TABLE; Schema: agent; Owner: -
--

CREATE TABLE agent.run_log (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    ts timestamp with time zone DEFAULT now() NOT NULL,
    query_id uuid,
    usuario_id uuid,
    rol character varying(30),
    agente character varying(30) NOT NULL,
    decision character varying(30),
    confidence numeric(3,2),
    input_hash character(64),
    detalle jsonb,
    prev_hash character(64),
    hash character(64),
    detalle_schema_version smallint
)
PARTITION BY RANGE (ts);


--
-- Name: TABLE run_log; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON TABLE agent.run_log IS 'Bitácora encadenada por hash de las decisiones de cada agente, con confianza, insumos y detalle, para probar que un resultado no fue alterado.';


--
-- Name: COLUMN run_log.id; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON COLUMN agent.run_log.id IS 'Identificador interno de la fila';


--
-- Name: COLUMN run_log.ts; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON COLUMN agent.run_log.ts IS 'Momento en que el agente tomó la decisión, parte de la clave de la bitácora';


--
-- Name: COLUMN run_log.query_id; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON COLUMN agent.run_log.query_id IS 'Consulta o solicitud que originó la decisión registrada por el agente';


--
-- Name: COLUMN run_log.usuario_id; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON COLUMN agent.run_log.usuario_id IS 'Usuario en cuyo nombre actuó el agente durante la ejecución';


--
-- Name: COLUMN run_log.rol; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON COLUMN agent.run_log.rol IS 'Rol del usuario con el que se ejecutó el agente, base de sus permisos';


--
-- Name: COLUMN run_log.agente; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON COLUMN agent.run_log.agente IS 'Agente que tomó la decisión consignada en la bitácora';


--
-- Name: COLUMN run_log.decision; Type: COMMENT; Schema: agent; Owner: -
--

COMMENT ON COLUMN agent.run_log.decision IS 'Tipo de decisión adoptada por el agente para atender la consulta';


--
