--

CREATE TABLE core.casos (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    entidad_id smallint DEFAULT 1 NOT NULL,
    codigo_caso character varying(50) NOT NULL,
    nombre_caso character varying(255) NOT NULL,
    distrito_principal_id integer,
    subsector_id integer NOT NULL,
    tematica_id integer,
    unidad_responsable_id integer NOT NULL,
    punto_focal_usuario_id uuid,
    nivel_conflicto_id smallint,
    nivel_riesgo_id smallint NOT NULL,
    prioridad_id smallint,
    estado_id smallint DEFAULT 1 NOT NULL,
    descripcion_riesgo text,
    latitud numeric(10,7),
    longitud numeric(10,7),
    fecha_inicio date,
    fecha_cierre date,
    fecha_ultima_actualizacion timestamp with time zone DEFAULT now() NOT NULL,
    fuente_original character varying(30),
    es_seed_historico boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_by uuid,
    origen_dato character varying(20) DEFAULT 'MANUAL'::character varying NOT NULL,
    confidence numeric(3,2),
    es_validado_humano boolean DEFAULT false NOT NULL,
    nivel_clasificacion smallint DEFAULT 2 NOT NULL,
    ciclo_intervencion_id smallint,
    pct_avance numeric(5,2),
    resumen_ejecutivo text,
    region_principal_id integer,
    provincia_principal_id integer,
    fecha_reapertura date,
    n_reaperturas smallint DEFAULT 0 NOT NULL,
    motivo_cierre text,
    link_reporte_pdf character varying(500),
    codigo_legado character varying(50),
    anulado_en timestamp with time zone,
    anulado_por uuid,
