    CONSTRAINT casos_confidence_check CHECK (((confidence >= (0)::numeric) AND (confidence <= (1)::numeric))),
    CONSTRAINT casos_fuente_original_check CHECK (((fuente_original)::text = ANY (ARRAY[('avisa_historico'::character varying)::text, ('whatsapp'::character varying)::text, ('acta'::character varying)::text, ('audio'::character varying)::text, ('manual'::character varying)::text]))),
    CONSTRAINT casos_origen_dato_check CHECK (((origen_dato)::text = ANY (ARRAY[('MANUAL'::character varying)::text, ('KAG'::character varying)::text, ('WORKFLOW'::character varying)::text, ('AVISA_HISTORICO'::character varying)::text, ('WHATSAPP'::character varying)::text]))),
    CONSTRAINT casos_pct_avance_check CHECK (((pct_avance >= (0)::numeric) AND (pct_avance <= (100)::numeric))),
    CONSTRAINT chk_casos_estado_actualizacion CHECK (((estado_actualizacion)::text = ANY ((ARRAY['Actualizado'::character varying, 'En proceso'::character varying, 'Pendiente'::character varying, 'No aplica'::character varying])::text[])))
);

