--
-- Name: compromisos; Type: TABLE; Schema: core; Owner: -
--

CREATE TABLE core.compromisos (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    codigo_compromiso character varying(60) NOT NULL,
    caso_id uuid NOT NULL,
    reunion_id uuid,
    documento_origen_id uuid,
    unidad_responsable_id integer NOT NULL,
    alcance_id smallint,
    tematica_id integer,
    fecha_inicio date NOT NULL,
    accion_compromiso text NOT NULL,
    tipo_compromiso character varying(10) NOT NULL,
    nivel_gobierno character varying(15),
    estado_id smallint DEFAULT 1 NOT NULL,
    redefinido_de_id uuid,
    evidencia_cumplimiento_uri character varying(500),
    atiende_brecha_genero boolean DEFAULT false NOT NULL,
    criterios_smart jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_by uuid,
    origen_dato character varying(20) DEFAULT 'MANUAL'::character varying NOT NULL,
    confidence numeric(3,2),
    es_validado_humano boolean DEFAULT false NOT NULL,
    nivel_clasificacion smallint DEFAULT 2 NOT NULL,
    fecha_vencimiento date,
    anulado_en timestamp with time zone,
    anulado_por uuid,
    anulacion_id uuid,
    motivo_anulacion text,
    demanda_id uuid,
    punto_focal_usuario_id uuid,
    punto_focal_texto character varying(200),
    clasificacion_alcance character varying(30),
    formal_verbal character varying(10),
    asumido_ministro boolean DEFAULT false NOT NULL,
    CONSTRAINT chk_compromisos_clasificacion_alcance CHECK (((clasificacion_alcance)::text = ANY ((ARRAY['progresivo_parcial'::character varying, 'entendimiento_operativo'::character varying, 'condicionado'::character varying])::text[]))),
    CONSTRAINT chk_compromisos_formal_verbal CHECK (((formal_verbal)::text = ANY ((ARRAY['formal'::character varying, 'verbal'::character varying])::text[]))),
    CONSTRAINT compromisos_codigo_compromiso_check CHECK (((codigo_compromiso)::text ~ '_COMP[0-9]{3}$'::text)),
    CONSTRAINT compromisos_confidence_check CHECK (((confidence >= (0)::numeric) AND (confidence <= (1)::numeric))),
    CONSTRAINT compromisos_nivel_gobierno_check CHECK (((nivel_gobierno)::text = ANY (ARRAY[('Nacional'::character varying)::text, ('Regional'::character varying)::text, ('Local'::character varying)::text, ('Empresa'::character varying)::text, ('Sociedad_Civil'::character varying)::text]))),
    CONSTRAINT compromisos_origen_dato_check CHECK (((origen_dato)::text = ANY (ARRAY[('MANUAL'::character varying)::text, ('KAG'::character varying)::text, ('WORKFLOW'::character varying)::text, ('AVISA_HISTORICO'::character varying)::text, ('WHATSAPP'::character varying)::text]))),
    CONSTRAINT compromisos_tipo_compromiso_check CHECK (((tipo_compromiso)::text = ANY (ARRAY[('Actividad'::character varying)::text, ('PIP'::character varying)::text])))
);

ALTER TABLE ONLY core.compromisos FORCE ROW LEVEL SECURITY;


