COMMENT ON COLUMN core.compromisos.asumido_ministro IS 'Dimensión «asumido por el Señor Ministro» (item 123), distinta de unidad_responsable_id: un compromiso puede ejecutarse por una unidad y estar asumido políticamente por el Despacho Ministerial. false es el valor por defecto (no asumido o sin declarar) y no se deriva de otra columna.';


--
-- Name: integraciones; Type: TABLE; Schema: core; Owner: -
--

CREATE TABLE core.integraciones (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    sistema_origen character varying(100) NOT NULL,
    sistema_destino character varying(100) NOT NULL,
    entidad_origen_tipo character varying(50) NOT NULL,
    entidad_origen_id uuid NOT NULL,
    entidad_destino_ref character varying(100),
    tipo_sync character varying(5) NOT NULL,
    estado character varying(15) DEFAULT 'pendiente_auth'::character varying NOT NULL,
    workflow_state character varying(50),
    ultima_sincronizacion timestamp with time zone,
    metadata_json jsonb,
    tipo_fuente_id smallint,
    protocolo_sincronizacion character varying(20) DEFAULT 'oficio_manual'::character varying,
    CONSTRAINT integraciones_estado_check CHECK (((estado)::text = ANY (ARRAY[('activa'::character varying)::text, ('pausada'::character varying)::text, ('error'::character varying)::text, ('pendiente_auth'::character varying)::text]))),
    CONSTRAINT integraciones_protocolo_sincronizacion_check CHECK (((protocolo_sincronizacion)::text = ANY (ARRAY[('api_rest_pide'::character varying)::text, ('batch_sftp'::character varying)::text, ('oficio_manual'::character varying)::text]))),
    CONSTRAINT integraciones_tipo_sync_check CHECK (((tipo_sync)::text = ANY (ARRAY[('push'::character varying)::text, ('pull'::character varying)::text, ('dual'::character varying)::text])))
);


--
