--
-- Name: mv_compromisos_inter_ministeriales; Type: MATERIALIZED VIEW; Schema: analytics; Owner: -
--

CREATE MATERIALIZED VIEW analytics.mv_compromisos_inter_ministeriales AS
 SELECT c.codigo_caso,
    co.codigo_compromiso,
    ec.codigo AS estado_compromiso,
    i.sistema_destino,
    i.workflow_state,
    i.ultima_sincronizacion
   FROM (((core.compromisos co
     JOIN core.casos c ON ((co.caso_id = c.id)))
     JOIN core.cat_estados_compromiso ec ON ((ec.id = co.estado_id)))
     JOIN core.integraciones i ON (((i.entidad_origen_id = co.id) AND ((i.entidad_origen_tipo)::text = 'compromiso'::text))))
  WHERE ((i.sistema_destino)::text = ANY (ARRAY[('MEF'::character varying)::text, ('MINAM'::character varying)::text, ('MINCETUR'::character varying)::text, ('MININTER'::character varying)::text, ('RREE'::character varying)::text]))
  WITH NO DATA;


