--
-- Name: mv_dashboard_alta_direccion; Type: MATERIALIZED VIEW; Schema: analytics; Owner: -
--

CREATE MATERIALIZED VIEW analytics.mv_dashboard_alta_direccion AS
 WITH base AS (
         SELECT g.region_id,
            g.region,
            nc.codigo AS nivel,
            nr.codigo AS riesgo,
            c.fecha_ultima_actualizacion
           FROM ((((core.casos c
             JOIN analytics.vw_geo_distrito g ON ((g.distrito_id = c.distrito_principal_id)))
             JOIN core.cat_niveles_conflicto nc ON ((nc.id = c.nivel_conflicto_id)))
             JOIN core.cat_niveles_riesgo nr ON ((nr.id = c.nivel_riesgo_id)))
             JOIN core.cat_estados_caso e ON (((e.id = c.estado_id) AND e.es_activo)))
        ), venc AS (
         SELECT g.region_id,
            count(*) AS n
           FROM ((((core.hitos_compromiso h
             JOIN core.cat_estados_hito eh ON (((eh.id = h.estado_id) AND (NOT eh.es_terminal))))
             JOIN core.compromisos co ON ((co.id = h.compromiso_id)))
             JOIN core.casos c ON ((c.id = co.caso_id)))
             JOIN analytics.vw_geo_distrito g ON ((g.distrito_id = c.distrito_principal_id)))
          WHERE (h.fecha_vencimiento < CURRENT_DATE)
          GROUP BY g.region_id
        )
 SELECT b.region_id,
    b.region,
    count(*) AS casos_activos,
    count(*) FILTER (WHERE ((b.riesgo)::text = 'Alto'::text)) AS riesgo_alto,
    count(*) FILTER (WHERE ((b.nivel)::text = 'Crisis_social'::text)) AS crisis,
    COALESCE(max(v.n), (0)::bigint) AS compromisos_vencidos,
    max(b.fecha_ultima_actualizacion) AS ultima_actividad,
    max((CURRENT_DATE - (b.fecha_ultima_actualizacion)::date)) AS max_dias_estancado
   FROM (base b
     LEFT JOIN venc v ON ((v.region_id = b.region_id)))
  GROUP BY b.region_id, b.region
  WITH NO DATA;


