    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT embedding_check CHECK ((num_nonnulls(fragmento_id, atributo_id) = 1))
);

ALTER TABLE ONLY kag.embedding FORCE ROW LEVEL SECURITY;


--
