--

COMMENT ON COLUMN kag.embedding.created_at IS 'Momento en que se creó el registro';


--
-- Name: mv_drift_embeddings; Type: MATERIALIZED VIEW; Schema: analytics; Owner: -
--

CREATE MATERIALIZED VIEW analytics.mv_drift_embeddings AS
 SELECT mes,
    modelo,
    version_modelo,
    n,
    (centroide OPERATOR(public.<=>) lag(centroide) OVER (PARTITION BY modelo ORDER BY mes)) AS distancia_coseno_mes_previo
   FROM ( SELECT (date_trunc('month'::text, embedding.created_at))::date AS mes,
            embedding.modelo,
            embedding.version_modelo,
            count(*) AS n,
            public.avg(embedding.embedding) AS centroide
           FROM kag.embedding
          GROUP BY ((date_trunc('month'::text, embedding.created_at))::date), embedding.modelo, embedding.version_modelo) x
  WITH NO DATA;


