--
-- Name: mv_drift_grafo; Type: MATERIALIZED VIEW; Schema: analytics; Owner: -
--

CREATE MATERIALIZED VIEW analytics.mv_drift_grafo AS
 SELECT nodo_id,
    periodo,
    valor,
    (valor - lag(valor) OVER (PARTITION BY nodo_id ORDER BY periodo)) AS cambio_vs_periodo_previo
   FROM kag.metrica_nodo
  WHERE (((metrica)::text = 'intermediacion'::text) AND es_critico)
  WITH NO DATA;


