CREATE TABLE kag.contraste (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    caso_id uuid NOT NULL,
    afirmacion_a text NOT NULL,
    fragmento_a_id uuid,
    escala_a character varying(12) NOT NULL,
    afirmacion_b text,
    fragmento_b_id uuid,
    escala_b character varying(12),
    tipo character varying(15) NOT NULL,
    estado character varying(15) DEFAULT 'abierta'::character varying NOT NULL,
    explicacion text,
    propuesto_por character varying(10) DEFAULT 'A2'::character varying NOT NULL,
    calificado_por uuid,
    valid_from timestamp with time zone DEFAULT now() NOT NULL,
    valid_to timestamp with time zone,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    superseded_at timestamp with time zone,
    supersedes_id uuid,
    es_validado_humano boolean DEFAULT false NOT NULL,
    nivel_clasificacion smallint DEFAULT 2 NOT NULL,
    CONSTRAINT contraste_check CHECK ((((estado)::text <> 'explicada'::text) OR (explicacion IS NOT NULL))),
    CONSTRAINT contraste_escala_a_check CHECK (((escala_a)::text = ANY (ARRAY[('campo'::character varying)::text, ('dato_oficial'::character varying)::text, ('medios'::character varying)::text, ('redes'::character varying)::text, ('actor'::character varying)::text]))),
    CONSTRAINT contraste_escala_b_check CHECK (((escala_b)::text = ANY (ARRAY[('campo'::character varying)::text, ('dato_oficial'::character varying)::text, ('medios'::character varying)::text, ('redes'::character varying)::text, ('actor'::character varying)::text]))),
    CONSTRAINT contraste_estado_check CHECK (((estado)::text = ANY (ARRAY[('abierta'::character varying)::text, ('explicada'::character varying)::text, ('sin_explicacion'::character varying)::text]))),
    CONSTRAINT contraste_propuesto_por_check CHECK (((propuesto_por)::text = ANY (ARRAY[('A2'::character varying)::text, ('persona'::character varying)::text]))),
    CONSTRAINT contraste_tipo_check CHECK (((tipo)::text = ANY (ARRAY[('coincidencia'::character varying)::text, ('contradiccion'::character varying)::text, ('vacio'::character varying)::text, ('diferencia'::character varying)::text])))
);

