--
-- Name: vw_marco_situacional_robustez; Type: VIEW; Schema: analytics; Owner: -
--

CREATE VIEW analytics.vw_marco_situacional_robustez AS
 SELECT id AS caso_id,
    (NOT (EXISTS ( SELECT 1
           FROM kag.contraste k
          WHERE ((k.caso_id = c.id) AND (k.superseded_at IS NULL) AND ((k.estado)::text = 'sin_explicacion'::text))))) AS consistencia,
    (EXISTS ( SELECT 1
           FROM kag.contraste k
          WHERE ((k.caso_id = c.id) AND (k.superseded_at IS NULL) AND (((k.escala_a)::text = 'dato_oficial'::text) OR ((k.escala_b)::text = 'dato_oficial'::text))))) AS correspondencia,
    (NOT (EXISTS ( SELECT 1
           FROM kag.anomalia_contextual a
          WHERE ((a.caso_id = c.id) AND ((a.estado)::text = 'marcada'::text))))) AS coherencia_contextual,
    COALESCE(( SELECT (NOT s.cambia_comprension)
           FROM kag.saturacion s
          WHERE (s.caso_id = c.id)
          ORDER BY s.iteracion DESC
         LIMIT 1), false) AS saturacion,
    (NOT (EXISTS ( SELECT 1
           FROM kag.contraste k
          WHERE ((k.caso_id = c.id) AND (k.superseded_at IS NULL) AND ((k.fragmento_a_id IS NULL) OR ((k.fragmento_b_id IS NULL) AND ((k.tipo)::text <> 'vacio'::text))))))) AS trazabilidad
   FROM core.casos c;


