-- Name: alertas_tempranas; Type: TABLE; Schema: core; Owner: -
--

CREATE TABLE core.alertas_tempranas (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    codigo_alerta character varying(50) NOT NULL,
    caso_id uuid,
    prioridad_id smallint,
    fecha_reporte date DEFAULT CURRENT_DATE NOT NULL,
    situacion_actual text,
    riesgos_json jsonb,
    acciones_sugeridas_json jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_by uuid,
    origen_dato character varying(20) DEFAULT 'MANUAL'::character varying NOT NULL,
    confidence numeric(3,2),
    es_validado_humano boolean DEFAULT false NOT NULL,
    nivel_clasificacion smallint DEFAULT 2 NOT NULL,
    titulo character varying(500),
    nivel_alerta_id smallint,
    descripcion_riesgo text,
    hechos_recientes text,
    acciones_oaipcs text,
    paso_actual smallint,
    fecha_validacion date,
    fecha_remision date,
    estado_legado character varying(40),
    fuente_tipo character varying(120),
    fuente_descripcion text,
    fuente_url character varying(500),
    distrito_id integer,
    sectorista_usuario_id uuid,
    mesa_id uuid,
    codigo_legado character varying(50),
    subsector_id integer,
    aprobada_por uuid,
    aprobada_en timestamp with time zone,
    visibilidad character varying(12) DEFAULT 'interna'::character varying NOT NULL,
    validada_por uuid,
    anulado_en timestamp with time zone,
    anulado_por uuid,
    anulacion_id uuid,
    motivo_anulacion text,
    archivado_en timestamp with time zone,
    archivado_por uuid,
    motivo_archivo text,
    nivel_riesgo_id smallint,
    alcance_id smallint,
    region_id integer,
    provincia_id integer,
    actores_clave jsonb,
    demandas_inmediatas jsonb,
    plantilla_whatsapp text,
    CONSTRAINT alertas_aprobacion_coherente CHECK (((aprobada_en IS NULL) OR (aprobada_por IS NOT NULL))),
    CONSTRAINT alertas_cuatro_ojos CHECK (((validada_por IS NULL) OR (aprobada_por IS NULL) OR (validada_por <> aprobada_por))),
    CONSTRAINT alertas_tempranas_confidence_check CHECK (((confidence >= (0)::numeric) AND (confidence <= (1)::numeric))),
    CONSTRAINT alertas_tempranas_origen_dato_check CHECK (((origen_dato)::text = ANY (ARRAY[('MANUAL'::character varying)::text, ('KAG'::character varying)::text, ('WORKFLOW'::character varying)::text, ('AVISA_HISTORICO'::character varying)::text, ('WHATSAPP'::character varying)::text]))),
    CONSTRAINT alertas_validacion_coherente CHECK (((validada_por IS NULL) = (fecha_validacion IS NULL))),
    CONSTRAINT alertas_visibilidad_valida CHECK (((visibilidad)::text = ANY (ARRAY[('interna'::character varying)::text, ('ejecutiva'::character varying)::text, ('sectorial'::character varying)::text])))
);

