--
-- Name: aristas; Type: TABLE; Schema: kag; Owner: -
--

CREATE TABLE kag.aristas (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    origen_id uuid NOT NULL,
    destino_id uuid NOT NULL,
    tipo_id smallint NOT NULL,
    caso_id uuid,
    intensidad smallint,
    justificacion text,
    valid_from timestamp with time zone NOT NULL,
    valid_to timestamp with time zone,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    superseded_at timestamp with time zone,
    supersedes_id uuid,
    split_from_id uuid,
    confidence numeric(3,2),
    origen_dato character varying(20) DEFAULT 'KAG'::character varying NOT NULL,
    es_validado_humano boolean DEFAULT false NOT NULL,
    nivel_clasificacion smallint DEFAULT 2 NOT NULL,
    CONSTRAINT aristas_check CHECK ((origen_id <> destino_id)),
    CONSTRAINT aristas_check1 CHECK (((valid_to IS NULL) OR (valid_to > valid_from))),
    CONSTRAINT aristas_confidence_check CHECK (((confidence >= (0)::numeric) AND (confidence <= (1)::numeric))),
    CONSTRAINT aristas_intensidad_check CHECK (((intensidad >= 1) AND (intensidad <= 5)))
);

ALTER TABLE ONLY kag.aristas FORCE ROW LEVEL SECURITY;


