--
-- Name: mv_tablero_decisional; Type: MATERIALIZED VIEW; Schema: analytics; Owner: -
--

CREATE MATERIALIZED VIEW analytics.mv_tablero_decisional AS
 WITH casos_v AS (
         SELECT c.id,
            g.region_id,
            g.region,
            nr.codigo AS riesgo
           FROM (((core.casos c
             JOIN analytics.vw_geo_distrito g ON ((g.distrito_id = c.distrito_principal_id)))
             JOIN core.cat_niveles_riesgo nr ON ((nr.id = c.nivel_riesgo_id)))
             JOIN core.cat_estados_caso e ON (((e.id = c.estado_id) AND e.es_activo)))
          WHERE c.es_validado_humano
        ), alertas_v AS (
         SELECT cv_1.region_id,
            count(*) AS n
           FROM (core.alertas_tempranas a
             JOIN casos_v cv_1 ON ((cv_1.id = a.caso_id)))
          WHERE a.es_validado_humano
          GROUP BY cv_1.region_id
        ), aristas_v AS (
         SELECT cv_1.region_id,
            count(*) AS total,
            count(*) FILTER (WHERE ar_1.es_validado_humano) AS validadas
           FROM (kag.aristas ar_1
             JOIN casos_v cv_1 ON ((cv_1.id = ar_1.caso_id)))
          WHERE ((ar_1.superseded_at IS NULL) AND (ar_1.valid_to IS NULL))
          GROUP BY cv_1.region_id
        )
 SELECT cv.region_id,
    cv.region,
    count(*) AS casos_validados,
    count(*) FILTER (WHERE ((cv.riesgo)::text = 'Alto'::text)) AS riesgo_alto,
    COALESCE(max(al.n), (0)::bigint) AS alertas_activas,
    count(*) FILTER (WHERE (rb.consistencia AND rb.correspondencia AND rb.coherencia_contextual AND rb.saturacion AND rb.trazabilidad)) AS casos_marco_robusto,
    count(*) FILTER (WHERE (NOT (rb.consistencia AND rb.correspondencia AND rb.coherencia_contextual AND rb.saturacion AND rb.trazabilidad))) AS casos_marco_provisional,
    COALESCE(((max(ar.validadas))::numeric / (NULLIF(max(ar.total), 0))::numeric), (0)::numeric) AS proporcion_aristas_validadas
   FROM (((casos_v cv
     JOIN analytics.vw_marco_situacional_robustez rb ON ((rb.caso_id = cv.id)))
     LEFT JOIN alertas_v al ON ((al.region_id = cv.region_id)))
     LEFT JOIN aristas_v ar ON ((ar.region_id = cv.region_id)))
  GROUP BY cv.region_id, cv.region
  WITH NO DATA;


