--
-- Name: vw_anexo_02_panorama_regional; Type: VIEW; Schema: analytics; Owner: -
--

CREATE VIEW analytics.vw_anexo_02_panorama_regional AS
 SELECT g.region,
    s.nombre AS subsector,
    count(*) AS total_casos,
    count(*) FILTER (WHERE ((nr.codigo)::text = 'Alto'::text)) AS casos_riesgo_alto,
    count(*) FILTER (WHERE ((nc.codigo)::text = 'Crisis_social'::text)) AS casos_crisis
   FROM (((((core.casos c
     JOIN analytics.vw_geo_distrito g ON ((g.distrito_id = c.distrito_principal_id)))
     JOIN core.cat_subsectores s ON ((s.id = c.subsector_id)))
     JOIN core.cat_niveles_riesgo nr ON ((nr.id = c.nivel_riesgo_id)))
     JOIN core.cat_niveles_conflicto nc ON ((nc.id = c.nivel_conflicto_id)))
     JOIN core.cat_estados_caso e ON (((e.id = c.estado_id) AND e.es_activo)))
  GROUP BY g.region, s.nombre;


