CREATE TABLE core.documentos (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tipo_id smallint NOT NULL,
    codigo character varying(60),
    caso_id uuid,
    reunion_id uuid,
    titulo character varying(255) NOT NULL,
    fecha date DEFAULT CURRENT_DATE NOT NULL,
    resumen_ejecutivo text,
    contenido_json jsonb DEFAULT '{}'::jsonb NOT NULL,
    url_pdf character varying(500),
    responsable_usuario_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_by uuid,
    origen_dato character varying(20) DEFAULT 'MANUAL'::character varying NOT NULL,
    confidence numeric(3,2),
    es_validado_humano boolean DEFAULT false NOT NULL,
    nivel_clasificacion smallint DEFAULT 2 NOT NULL,
    codigo_legado character varying(50),
    estado character varying(40),
    distrito_id integer,
    url_lista character varying(500),
    url_foto character varying(500),
    anulado_en timestamp with time zone,
    anulado_por uuid,
    anulacion_id uuid,
    motivo_anulacion text,
    autor_usuario_id uuid,
    autor_texto character varying(200),
    contenido bytea,
    mime character varying(120),
    tamano_bytes bigint,
    hash_sha256 character(64),
    CONSTRAINT chk_documentos_autor_excl CHECK ((num_nonnulls(autor_usuario_id, autor_texto) <= 1)),
    CONSTRAINT documentos_confidence_check CHECK (((confidence >= (0)::numeric) AND (confidence <= (1)::numeric))),
    CONSTRAINT documentos_origen_dato_check CHECK (((origen_dato)::text = ANY (ARRAY[('MANUAL'::character varying)::text, ('KAG'::character varying)::text, ('WORKFLOW'::character varying)::text, ('AVISA_HISTORICO'::character varying)::text, ('WHATSAPP'::character varying)::text])))
);

