--
-- Name: vw_anexo_14_seguimiento_compromisos; Type: VIEW; Schema: analytics; Owner: -
--

CREATE VIEW analytics.vw_anexo_14_seguimiento_compromisos AS
 SELECT c.codigo_compromiso,
    cs.codigo_caso,
    ( SELECT string_agg(DISTINCT (g.region)::text, ', '::text) AS string_agg
           FROM (core.compromiso_distritos cd
             JOIN analytics.vw_geo_distrito g ON ((g.distrito_id = cd.distrito_id)))
          WHERE (cd.compromiso_id = c.id)) AS region,
    ( SELECT string_agg(DISTINCT (g.provincia)::text, ', '::text) AS string_agg
           FROM (core.compromiso_distritos cd
             JOIN analytics.vw_geo_distrito g ON ((g.distrito_id = cd.distrito_id)))
          WHERE (cd.compromiso_id = c.id)) AS provincia,
    ( SELECT string_agg(DISTINCT (g.distrito)::text, ', '::text) AS string_agg
           FROM (core.compromiso_distritos cd
             JOIN analytics.vw_geo_distrito g ON ((g.distrito_id = cd.distrito_id)))
          WHERE (cd.compromiso_id = c.id)) AS distrito,
    al.codigo AS alcance_geografico,
    td.nombre AS documento_origen,
    c.fecha_inicio,
    c.accion_compromiso,
    uo.siglas AS area_responsable,
    h.codigo_hito,
    h.descripcion_hito AS hito,
    eh.codigo AS estado_hito,
        CASE
            WHEN eh.es_terminal THEN 'VERDE'::text
            WHEN (h.fecha_vencimiento < CURRENT_DATE) THEN 'ROJO'::text
            WHEN (h.fecha_vencimiento <= (CURRENT_DATE + 15)) THEN 'AMARILLO'::text
            ELSE 'VERDE'::text
        END AS semaforo,
    h.fecha_vencimiento AS fecha_planificada,
    h.fecha_real
   FROM (((((((core.compromisos c
     JOIN core.casos cs ON ((cs.id = c.caso_id)))
     JOIN core.cat_unidades_organicas uo ON ((uo.id = c.unidad_responsable_id)))
     LEFT JOIN core.cat_alcances_geograficos al ON ((al.id = c.alcance_id)))
     LEFT JOIN core.documentos dc ON ((dc.id = c.documento_origen_id)))
     LEFT JOIN core.cat_tipos_documento td ON ((td.id = dc.tipo_id)))
     LEFT JOIN core.hitos_compromiso h ON ((h.compromiso_id = c.id)))
     LEFT JOIN core.cat_estados_hito eh ON ((eh.id = h.estado_id)));


--
-- Name: VIEW vw_anexo_14_seguimiento_compromisos; Type: COMMENT; Schema: analytics; Owner: -
--

COMMENT ON VIEW analytics.vw_anexo_14_seguimiento_compromisos IS 'Anexo 14. Desde el 2026-11-24 no expone temática.';


--
-- Name: actores; Type: TABLE; Schema: core; Owner: -
--

CREATE TABLE core.actores (
    actor_uid uuid DEFAULT gen_random_uuid() NOT NULL,
    nombre_actual character varying(255) NOT NULL,
    fecha_ultimo_cambio_nombre date,
    naturaleza character varying(12) DEFAULT 'organizacion'::character varying NOT NULL,
    tipo_actor_id integer NOT NULL,
    rol_actor_id integer NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_by uuid,
    origen_dato character varying(20) DEFAULT 'MANUAL'::character varying NOT NULL,
    confidence numeric(3,2),
    es_validado_humano boolean DEFAULT false NOT NULL,
    nivel_clasificacion smallint DEFAULT 2 NOT NULL,
    email_contacto character varying(255),
    cargo_actual character varying(150),
    nivel_gobierno character varying(15),
    categoria character varying(40),
    perfil_id smallint,
    rol_funcional_id smallint,
    distrito_id integer,
    foto_url character varying(500),
    activo boolean DEFAULT true NOT NULL,
    perfil_descripcion text,
    abreviatura character varying(150),
    codigo_legado character varying(50),
    nivel_identificacion_id smallint DEFAULT 3 NOT NULL,
    caso_ancla_id uuid,
    organizacion_ancla_uid uuid,
    confianza numeric(3,2),
    region_id integer,
    telefono_contacto character varying(50),
    CONSTRAINT actores_confianza_check CHECK (((confianza IS NULL) OR ((confianza >= (0)::numeric) AND (confianza <= (1)::numeric)))),
    CONSTRAINT actores_confidence_check CHECK (((confidence >= (0)::numeric) AND (confidence <= (1)::numeric))),
    CONSTRAINT actores_naturaleza_check CHECK (((naturaleza)::text = ANY (ARRAY[('persona'::character varying)::text, ('organizacion'::character varying)::text]))),
    CONSTRAINT actores_nivel_gobierno_check CHECK (((nivel_gobierno)::text = ANY (ARRAY[('Nacional'::character varying)::text, ('Regional'::character varying)::text, ('Local'::character varying)::text, ('Empresa'::character varying)::text, ('Sociedad_Civil'::character varying)::text]))),
    CONSTRAINT actores_origen_dato_check CHECK (((origen_dato)::text = ANY (ARRAY[('MANUAL'::character varying)::text, ('KAG'::character varying)::text, ('WORKFLOW'::character varying)::text, ('AVISA_HISTORICO'::character varying)::text, ('WHATSAPP'::character varying)::text]))),
    CONSTRAINT ck_actor_anclaje CHECK (((nivel_identificacion_id <= 3) OR (caso_ancla_id IS NOT NULL) OR (organizacion_ancla_uid IS NOT NULL))),
    CONSTRAINT ck_actor_sin_geo_si_no_identificado CHECK (((nivel_identificacion_id < 4) OR ((distrito_id IS NULL) AND (region_id IS NULL))))
);

ALTER TABLE ONLY core.actores FORCE ROW LEVEL SECURITY;


