-- Name: casos_actores; Type: TABLE; Schema: core; Owner: -
--

CREATE TABLE core.casos_actores (
    caso_id uuid NOT NULL,
    actor_id uuid NOT NULL,
    nivel_influencia smallint DEFAULT 50,
    posicion character varying(20) DEFAULT 'Neutral'::character varying,
    rol_en_caso character varying(120),
    vigente_desde date,
    vigente_hasta date,
    anulado_en timestamp with time zone,
    anulado_por uuid,
    motivo_anulacion text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    CONSTRAINT casos_actores_nivel_influencia_check CHECK (((nivel_influencia >= 1) AND (nivel_influencia <= 100))),
    CONSTRAINT casos_actores_posicion_check CHECK (((posicion)::text = ANY (ARRAY[('Apoyo'::character varying)::text, ('Oposicion'::character varying)::text, ('Neutral'::character varying)::text, ('No_dialogante'::character varying)::text]))),
    CONSTRAINT chk_casos_actores_vigencia CHECK (((vigente_hasta IS NULL) OR (vigente_desde IS NULL) OR (vigente_hasta >= vigente_desde)))
);

