    CONSTRAINT reuniones_dialogo_confidence_check CHECK (((confidence >= (0)::numeric) AND (confidence <= (1)::numeric))),
    CONSTRAINT reuniones_dialogo_origen_dato_check CHECK (((origen_dato)::text = ANY (ARRAY[('MANUAL'::character varying)::text, ('KAG'::character varying)::text, ('WORKFLOW'::character varying)::text, ('AVISA_HISTORICO'::character varying)::text, ('WHATSAPP'::character varying)::text])))
