--
-- Name: vw_anexo_16_registro_reuniones; Type: VIEW; Schema: analytics; Owner: -
--

CREATE VIEW analytics.vw_anexo_16_registro_reuniones WITH (security_invoker='true') AS
 SELECT
        CASE
            WHEN r.programada THEN 'Programado'::text
            ELSE 'No programado'::text
        END AS tipo,
    r.codigo_reunion AS codigo,
    s.nombre AS sector,
    u.nombre AS responsable,
    r.fecha,
    g.region AS departamento,
    r.lugar,
    r.titulo,
    ( SELECT count(*) AS count
           FROM core.reunion_participantes p
          WHERE ((p.reunion_id = r.id) AND p.asistio)) AS asistentes,
    (EXISTS ( SELECT 1
           FROM core.documentos d
          WHERE ((d.reunion_id = r.id) AND (d.tipo_id = 10)))) AS tiene_ayuda_memoria,
    (EXISTS ( SELECT 1
           FROM core.documentos d
          WHERE ((d.reunion_id = r.id) AND (d.tipo_id = 11)))) AS tiene_relatoria,
    r.nota_publicacion_url AS publicacion_nota
   FROM ((((core.reuniones_dialogo r
     JOIN core.casos c ON ((c.id = r.caso_id)))
     JOIN core.cat_subsectores s ON ((s.id = c.subsector_id)))
     JOIN analytics.vw_geo_distrito g ON ((g.distrito_id = c.distrito_principal_id)))
     LEFT JOIN core.usuarios u ON ((u.id = r.responsable_usuario_id)));


--
-- Name: vw_anexo_17_registro_reportes; Type: VIEW; Schema: analytics; Owner: -
--

CREATE VIEW analytics.vw_anexo_17_registro_reportes WITH (security_invoker='true') AS
 SELECT td.nombre AS tipo,
    d.codigo AS codigo_reporte,
    c.codigo_caso,
    u.nombre AS responsable,
    d.fecha,
    g.region,
    (((g.provincia)::text || ' / '::text) || (g.distrito)::text) AS ubicacion,
    d.titulo,
    d.resumen_ejecutivo,
    (d.contenido_json ->> 'contenido'::text) AS contenido,
    (d.contenido_json ->> 'conclusiones_recomendaciones'::text) AS conclusiones_recomendaciones
   FROM ((((core.documentos d
     JOIN core.cat_tipos_documento td ON ((td.id = d.tipo_id)))
     LEFT JOIN core.casos c ON ((c.id = d.caso_id)))
     LEFT JOIN analytics.vw_geo_distrito g ON ((g.distrito_id = c.distrito_principal_id)))
     LEFT JOIN core.usuarios u ON ((u.id = d.responsable_usuario_id)))
  WHERE ((td.codigo)::text = ANY (ARRAY[('reporte_rapido'::character varying)::text, ('clima_social_general'::character varying)::text, ('clima_social_focalizado'::character varying)::text, ('reporte_actividad'::character varying)::text, ('informe_oficial'::character varying)::text]))
UNION ALL
 SELECT 'Alerta Temprana'::character varying AS tipo,
    a.codigo_alerta AS codigo_reporte,
    c.codigo_caso,
    NULL::character varying AS responsable,
    a.fecha_reporte AS fecha,
    g.region,
    (((g.provincia)::text || ' / '::text) || (g.distrito)::text) AS ubicacion,
    c.nombre_caso AS titulo,
    a.situacion_actual AS resumen_ejecutivo,
    NULL::text AS contenido,
    NULL::text AS conclusiones_recomendaciones
   FROM ((core.alertas_tempranas a
     JOIN core.casos c ON ((c.id = a.caso_id)))
     JOIN analytics.vw_geo_distrito g ON ((g.distrito_id = c.distrito_principal_id)));


