    mes_previsto date,
    estado character varying(10) DEFAULT 'propuesta'::character varying NOT NULL,
    decidido_por uuid,
    decision_escrita_uri character varying(500),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    requiere_censo boolean DEFAULT false NOT NULL,
    censo_referencia character varying(40),
    CONSTRAINT brecha_estado_check CHECK (((estado)::text = ANY (ARRAY[('propuesta'::character varying)::text, ('aprobada'::character varying)::text, ('en_campo'::character varying)::text, ('cerrada'::character varying)::text, ('descartada'::character varying)::text]))),
    CONSTRAINT brecha_horas_estimadas_check CHECK ((horas_estimadas >= (0)::numeric))
);


