--
-- Name: vw_carga_campo; Type: VIEW; Schema: analytics; Owner: -
--

CREATE VIEW analytics.vw_carga_campo AS
 SELECT m.mes,
    COALESCE(( SELECT sum(c.horas_disponibles) AS sum
           FROM core.capacidad_campo c
          WHERE (c.mes = m.mes)), (0)::numeric) AS horas_capacidad,
    COALESCE(sum(b.horas_estimadas) FILTER (WHERE (((b.estado)::text = ANY (ARRAY[('aprobada'::character varying)::text, ('en_campo'::character varying)::text])) AND b.requiere_campo)), (0)::numeric) AS horas_aprobadas
   FROM (( SELECT brecha.mes_previsto AS mes
           FROM ind.brecha
          WHERE (brecha.mes_previsto IS NOT NULL)
        UNION
         SELECT capacidad_campo.mes
           FROM core.capacidad_campo) m
     LEFT JOIN ind.brecha b ON ((b.mes_previsto = m.mes)))
  GROUP BY m.mes;


--
-- Name: vw_casos_estancados; Type: VIEW; Schema: analytics; Owner: -
--

CREATE VIEW analytics.vw_casos_estancados AS
 SELECT c.id,
    c.codigo_caso,
    (CURRENT_DATE - (c.fecha_ultima_actualizacion)::date) AS dias_estancado
   FROM (core.casos c
     JOIN core.cat_estados_caso e ON (((e.id = c.estado_id) AND e.es_activo)));


--
-- Name: vw_eravisa_survival; Type: VIEW; Schema: analytics; Owner: -
--

CREATE VIEW analytics.vw_eravisa_survival AS
 WITH base AS (
         SELECT c.id,
            c.codigo_caso,
            c.fecha_inicio,
            c.fecha_cierre,
                CASE
                    WHEN (c.fecha_cierre IS NULL) THEN (CURRENT_DATE - c.fecha_inicio)
                    ELSE (c.fecha_cierre - c.fecha_inicio)
                END AS dias_abierto,
            (c.fecha_cierre IS NOT NULL) AS evento_cierre
           FROM core.casos c
        )
 SELECT codigo_caso,
    dias_abierto,
    evento_cierre,
    count(*) OVER () AS total_casos,
    count(*) FILTER (WHERE (NOT evento_cierre)) OVER () AS censurados
   FROM base
  WHERE (dias_abierto IS NOT NULL);


--
-- Name: vw_erop_milestones; Type: VIEW; Schema: analytics; Owner: -
--

CREATE VIEW analytics.vw_erop_milestones AS
 SELECT codigo AS regla_codigo,
    titulo,
    estado AS regla_estado,
    disparador_vencimiento_fecha,
    disparador_vencimiento_evento,
    fuente_documento_id
   FROM policy.regla r
  WHERE ((clase = 'N'::bpchar) AND ((codigo)::text ~~ 'N-ROP-%'::text));


