    es_validado_humano boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    requiere_censo boolean DEFAULT false NOT NULL,
    CONSTRAINT variante_clase_check CHECK (((clase)::text = ANY (ARRAY[('estandar'::character varying)::text, ('factible'::character varying)::text, ('proxy'::character varying)::text, ('brecha'::character varying)::text]))),
    CONSTRAINT variante_estado_check CHECK (((estado)::text = ANY (ARRAY[('propuesta'::character varying)::text, ('activa'::character varying)::text, ('retirada'::character varying)::text]))),
    CONSTRAINT variante_horas_estimadas_check CHECK ((horas_estimadas >= (0)::numeric)),
    CONSTRAINT variante_nivel_evidencia_check CHECK (((nivel_evidencia >= 1) AND (nivel_evidencia <= 5)))
);


