--
-- Name: vw_selecciones_vigentes; Type: VIEW; Schema: analytics; Owner: -
--

CREATE VIEW analytics.vw_selecciones_vigentes AS
 SELECT s.id AS seleccion_id,
    p.codigo AS plantilla,
    sl.codigo AS slot,
    i.codigo AS indicador,
    s.caso_id,
    s.distrito_id,
    s.periodo,
    v.id AS variante_id,
    v.clase,
    v.es_validado_humano,
    pj.incertidumbre,
    s.seleccionada_por,
    s.valid_from
   FROM (((((ind.seleccion s
     JOIN ind.plantilla_slot sl ON ((sl.id = s.slot_id)))
     JOIN ind.plantilla p ON ((p.id = sl.plantilla_id)))
     JOIN ind.variante v ON ((v.id = s.variante_id)))
     JOIN ind.indicador i ON ((i.id = v.indicador_id)))
     LEFT JOIN ind.proxy_justificacion pj ON ((pj.variante_id = v.id)))
  WHERE ((s.superseded_at IS NULL) AND ((s.valid_to IS NULL) OR (s.valid_to > now())));


--
-- Name: resultado; Type: TABLE; Schema: ind; Owner: -
--

CREATE TABLE ind.resultado (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    variante_id uuid NOT NULL,
    distrito_id integer,
    periodo character varying(10) NOT NULL,
    valor numeric,
    incertidumbre character varying(5),
    run_id uuid,
    calculado_en timestamp with time zone DEFAULT now() NOT NULL,
    valor_categoria character varying(20),
    denominador numeric,
    cobertura_pct numeric(5,2),
    fuente_denominador character varying(120),
    requiere_censo boolean DEFAULT false NOT NULL,
    censo_referencia character varying(40),
    valido_desde timestamp with time zone DEFAULT now() NOT NULL,
    superseded_at timestamp with time zone,
    CONSTRAINT chk_ind_resultado_censo CHECK (((NOT requiere_censo) OR (censo_referencia IS NOT NULL))),
    CONSTRAINT chk_ind_resultado_denominador CHECK ((((denominador IS NULL) AND (fuente_denominador IS NULL)) OR ((denominador IS NOT NULL) AND (fuente_denominador IS NOT NULL)))),
    CONSTRAINT resultado_cobertura_pct_check CHECK (((cobertura_pct IS NULL) OR ((cobertura_pct >= (0)::numeric) AND (cobertura_pct <= (100)::numeric)))),
    CONSTRAINT resultado_incertidumbre_check CHECK (((incertidumbre)::text = ANY (ARRAY[('baja'::character varying)::text, ('media'::character varying)::text, ('alta'::character varying)::text]))),
    CONSTRAINT resultado_valor_categoria_check CHECK (((valor_categoria IS NULL) OR ((valor_categoria)::text = ANY (ARRAY[('verde'::character varying)::text, ('ambar'::character varying)::text, ('rojo'::character varying)::text, ('sin_dato'::character varying)::text]))))
);


