--
-- Name: vw_indicadores_minister; Type: VIEW; Schema: analytics; Owner: -
--

CREATE VIEW analytics.vw_indicadores_minister AS
 SELECT sv.seleccion_id,
    sv.plantilla,
    sv.slot,
    sv.indicador,
    sv.caso_id,
    sv.distrito_id,
    sv.periodo,
    sv.variante_id,
    sv.clase,
    sv.es_validado_humano,
    sv.incertidumbre,
    sv.seleccionada_por,
    sv.valid_from,
    r.valor,
    r.incertidumbre AS incertidumbre_resultado
   FROM (analytics.vw_selecciones_vigentes sv
     LEFT JOIN ind.resultado r ON (((r.variante_id = sv.variante_id) AND ((r.periodo)::text = (sv.periodo)::text))))
  WHERE (((sv.clase)::text <> 'proxy'::text) OR (sv.es_validado_humano AND ((sv.incertidumbre)::text <> 'alta'::text)));


