-- Name: relacion_dependencia; Type: TABLE; Schema: ind; Owner: -
--

CREATE TABLE ind.relacion_dependencia (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    indicador_id uuid NOT NULL,
    depende_de_indicador_id uuid,
    depende_de_variable_id smallint,
    tipo_dependencia character varying(20) NOT NULL,
    peso numeric(5,4),
    CONSTRAINT relacion_dependencia_check CHECK ((num_nonnulls(depende_de_indicador_id, depende_de_variable_id) = 1)),
    CONSTRAINT relacion_dependencia_check1 CHECK ((((tipo_dependencia)::text <> ALL (ARRAY[('componente'::character varying)::text, ('agregacion'::character varying)::text])) OR (peso IS NOT NULL))),
    CONSTRAINT relacion_dependencia_check2 CHECK ((indicador_id <> COALESCE(depende_de_indicador_id, '00000000-0000-0000-0000-000000000000'::uuid))),
    CONSTRAINT relacion_dependencia_peso_check CHECK (((peso IS NULL) OR (peso > (0)::numeric))),
    CONSTRAINT relacion_dependencia_tipo_dependencia_check CHECK (((tipo_dependencia)::text = ANY (ARRAY[('componente'::character varying)::text, ('insumo'::character varying)::text, ('control'::character varying)::text, ('validacion'::character varying)::text, ('agregacion'::character varying)::text])))
);


