--
-- Name: vw_indicadores_obsoletos; Type: VIEW; Schema: analytics; Owner: -
--

CREATE VIEW analytics.vw_indicadores_obsoletos AS
 WITH RECURSIVE cadena AS (
         SELECT i.id AS indicador_id,
            i.codigo,
            NULL::uuid AS padre,
            0 AS nivel
           FROM ind.indicador i
        UNION
         SELECT rd.indicador_id,
            i.codigo,
            c_1.indicador_id,
            (c_1.nivel + 1)
           FROM ((cadena c_1
             JOIN ind.relacion_dependencia rd ON ((rd.depende_de_indicador_id = c_1.indicador_id)))
             JOIN ind.indicador i ON ((i.id = rd.indicador_id)))
          WHERE (c_1.nivel < 6)
        ), vars_stale AS (
         SELECT rd.indicador_id,
            bool_or(COALESCE(( SELECT ((CURRENT_DATE - o.fecha) > v.ttl_frescura_dias)
                   FROM (ctx.cat_variables v
                     LEFT JOIN LATERAL ctx.ultima_observacion((v.codigo)::text) o(valor, fecha, vigente, ambito_resuelto) ON (true))
                  WHERE (v.id = rd.depende_de_variable_id)), false)) AS stale
           FROM ind.relacion_dependencia rd
          WHERE (rd.depende_de_variable_id IS NOT NULL)
          GROUP BY rd.indicador_id
        )
 SELECT c.indicador_id,
    c.codigo,
    c.padre,
    c.nivel,
    COALESCE(vs.stale, false) AS variable_obsoleta
   FROM (cadena c
     LEFT JOIN vars_stale vs ON ((vs.indicador_id = c.indicador_id)));


