--
-- Name: vw_mactor_red_actores; Type: VIEW; Schema: analytics; Owner: -
--

CREATE VIEW analytics.vw_mactor_red_actores AS
 SELECT a.caso_id,
    no.etiqueta AS actor_origen,
    nd.etiqueta AS actor_destino,
    t.codigo AS tipo,
    t.clase,
    a.intensidad,
    a.valid_from,
    a.valid_to,
    a.confidence
   FROM (((kag.aristas a
     JOIN kag.nodos no ON (((no.id = a.origen_id) AND ((no.tipo)::text = 'actor'::text))))
     JOIN kag.nodos nd ON (((nd.id = a.destino_id) AND ((nd.tipo)::text = 'actor'::text))))
     JOIN kag.cat_tipos_arista t ON ((t.id = a.tipo_id)))
  WHERE ((a.superseded_at IS NULL) AND ((t.clase)::text = ANY (ARRAY[('relacion'::character varying)::text, ('influencia'::character varying)::text])));


