    actor_uid uuid,
    motivo text,
    filas_afectadas integer DEFAULT 0 NOT NULL,
    contexto jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT datos_personales_acceso_operacion_check CHECK ((operacion = ANY (ARRAY['select_descifrado'::text, 'select_reniec'::text, 'insert'::text, 'update'::text, 'delete'::text, 'export'::text])))
);

ALTER TABLE ONLY audit.datos_personales_acceso FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE datos_personales_acceso; Type: COMMENT; Schema: audit; Owner: -
--

COMMENT ON TABLE audit.datos_personales_acceso IS 'Bitácora inmutable de acceso y escritura sobre datos personales de actores, exigida por la Ley 29733: no se corrige, se amplía con una fila nueva.';


--
-- Name: COLUMN datos_personales_acceso.id; Type: COMMENT; Schema: audit; Owner: -
--

COMMENT ON COLUMN audit.datos_personales_acceso.id IS 'Identificador interno del evento registrado en la bitácora';


