--
-- Name: COLUMN datos_personales_acceso.contexto; Type: COMMENT; Schema: audit; Owner: -
--

COMMENT ON COLUMN audit.datos_personales_acceso.contexto IS 'Detalle de la operación registrada: origen, columnas modificadas y resultado';


--
-- Name: datos_personales_acceso_id_seq; Type: SEQUENCE; Schema: audit; Owner: -
--

ALTER TABLE audit.datos_personales_acceso ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME audit.datos_personales_acceso_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: raw_ingest; Type: TABLE; Schema: avisa; Owner: -
--

CREATE TABLE avisa.raw_ingest (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    received_at timestamp with time zone DEFAULT now() NOT NULL,
    fuente character varying(30) NOT NULL,
    sender_hmac character(64) NOT NULL,
    raw_text text,
    audio_uri character varying(500),
    payload_json jsonb,
    schema_version character varying(10),
    extractor_version character varying(30),
    confidence numeric(3,2),
    estado character varying(12) DEFAULT 'pendiente'::character varying NOT NULL,
    caso_id uuid,
    tipo_registro character varying(20) DEFAULT 'evento'::character varying NOT NULL,
    policy_snapshot_id uuid,
    CONSTRAINT raw_ingest_confidence_check CHECK (((confidence >= (0)::numeric) AND (confidence <= (1)::numeric))),
    CONSTRAINT raw_ingest_estado_check CHECK (((estado)::text = ANY (ARRAY[('pendiente'::character varying)::text, ('procesado'::character varying)::text, ('rechazado'::character varying)::text, ('en_hitl'::character varying)::text]))),
    CONSTRAINT raw_ingest_fuente_check CHECK (((fuente)::text = ANY (ARRAY[('whatsapp'::character varying)::text, ('acta_pdf'::character varying)::text, ('audio'::character varying)::text, ('email'::character varying)::text, ('sunat_comprobante'::character varying)::text, ('vuce_permiso'::character varying)::text, ('ana_siagua'::character varying)::text, ('sanipes_pcr'::character varying)::text, ('citered_acta'::character varying)::text, ('dgsfs_tiburon'::character varying)::text]))),
    CONSTRAINT raw_ingest_tipo_registro_check CHECK (((tipo_registro)::text = ANY (ARRAY[('evento'::character varying)::text, ('serie'::character varying)::text, ('permiso'::character varying)::text, ('comprobante'::character varying)::text, ('inspeccion'::character varying)::text, ('diagnostico'::character varying)::text])))
)
PARTITION BY RANGE (received_at);


--
-- Name: TABLE raw_ingest; Type: COMMENT; Schema: avisa; Owner: -
--

COMMENT ON TABLE avisa.raw_ingest IS 'Mensaje crudo recibido por un canal de entrada, con su huella de origen, contenido, versión del extractor y confianza, antes de hacerse registro del modelo.';


--
-- Name: COLUMN raw_ingest.id; Type: COMMENT; Schema: avisa; Owner: -
--

COMMENT ON COLUMN avisa.raw_ingest.id IS 'Identificador interno de la fila';


--
