--

COMMENT ON COLUMN avisa.raw_ingest.received_at IS 'Momento en que el canal de ingesta recibió el mensaje crudo';


--
-- Name: COLUMN raw_ingest.fuente; Type: COMMENT; Schema: avisa; Owner: -
--

COMMENT ON COLUMN avisa.raw_ingest.fuente IS 'Canal o sistema por el que llegó el mensaje crudo';


--
-- Name: COLUMN raw_ingest.sender_hmac; Type: COMMENT; Schema: avisa; Owner: -
--

COMMENT ON COLUMN avisa.raw_ingest.sender_hmac IS 'Firma HMAC del remitente, usada para verificar que el origen es legítimo';


--
-- Name: COLUMN raw_ingest.raw_text; Type: COMMENT; Schema: avisa; Owner: -
--

COMMENT ON COLUMN avisa.raw_ingest.raw_text IS 'Contenido textual original del mensaje, tal como llegó sin normalizar';


--
-- Name: COLUMN raw_ingest.audio_uri; Type: COMMENT; Schema: avisa; Owner: -
--

COMMENT ON COLUMN avisa.raw_ingest.audio_uri IS 'Ubicación del audio cuando el mensaje se recibió como nota de voz';


--
-- Name: COLUMN raw_ingest.payload_json; Type: COMMENT; Schema: avisa; Owner: -
--

COMMENT ON COLUMN avisa.raw_ingest.payload_json IS 'Cuerpo estructurado original del mensaje, antes de interpretarse';


--
-- Name: COLUMN raw_ingest.schema_version; Type: COMMENT; Schema: avisa; Owner: -
--

COMMENT ON COLUMN avisa.raw_ingest.schema_version IS 'Versión del esquema de captura con que se interpreta el mensaje';


--
-- Name: COLUMN raw_ingest.extractor_version; Type: COMMENT; Schema: avisa; Owner: -
--

COMMENT ON COLUMN avisa.raw_ingest.extractor_version IS 'Versión del extractor que procesó el mensaje, para reproducir su lectura';


--
-- Name: COLUMN raw_ingest.confidence; Type: COMMENT; Schema: avisa; Owner: -
--

COMMENT ON COLUMN avisa.raw_ingest.confidence IS 'Grado de certeza del dato, entre 0 y 1';


--
-- Name: COLUMN raw_ingest.estado; Type: COMMENT; Schema: avisa; Owner: -
--

COMMENT ON COLUMN avisa.raw_ingest.estado IS 'Situación del mensaje en la cola de ingesta, por defecto pendiente';


--
-- Name: COLUMN raw_ingest.caso_id; Type: COMMENT; Schema: avisa; Owner: -
--

COMMENT ON COLUMN avisa.raw_ingest.caso_id IS 'Caso al que se vincula el mensaje desde su recepción, si ya se conoce';


--
-- Name: COLUMN raw_ingest.tipo_registro; Type: COMMENT; Schema: avisa; Owner: -
--

COMMENT ON COLUMN avisa.raw_ingest.tipo_registro IS 'Clase de registro que el mensaje representa, por defecto evento';


--
-- Name: COLUMN raw_ingest.policy_snapshot_id; Type: COMMENT; Schema: avisa; Owner: -
--

COMMENT ON COLUMN avisa.raw_ingest.policy_snapshot_id IS 'Foto de las políticas vigentes al momento de recibir el mensaje';


