CREATE TABLE chat.commit (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    repositorio_id uuid NOT NULL,
    hash character(64) NOT NULL,
    parent_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    tree_hash character(64) DEFAULT repeat('0'::text, 64) NOT NULL,
    autor_tipo character varying(10) NOT NULL,
    autor_id uuid NOT NULL,
    mensaje text NOT NULL,
    "timestamp" timestamp with time zone DEFAULT now() NOT NULL,
    modelo_card_id uuid NOT NULL,
    parametros_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    parametros_hash character(64) DEFAULT repeat('0'::text, 64) NOT NULL,
    librerias_snapshot jsonb DEFAULT '[]'::jsonb NOT NULL,
    librerias_hash character(64) DEFAULT repeat('0'::text, 64) NOT NULL,
    aplicacion_id uuid NOT NULL,
    politica_snapshot_id uuid NOT NULL,
    artefacto_id uuid,
    es_merge boolean DEFAULT false NOT NULL,
    es_revert boolean DEFAULT false NOT NULL,
    es_amend boolean DEFAULT false NOT NULL,
    es_cherry_pick boolean DEFAULT false NOT NULL,
    nivel_clasificacion smallint DEFAULT 2 NOT NULL,
    origen_dato character varying(20) DEFAULT 'MANUAL'::character varying NOT NULL,
    CONSTRAINT commit_autor_tipo_check CHECK (((autor_tipo)::text = ANY (ARRAY[('usuario'::character varying)::text, ('agente'::character varying)::text, ('sistema'::character varying)::text]))),
    CONSTRAINT commit_check CHECK (((NOT es_merge) OR (cardinality(parent_ids) = 2))),
    CONSTRAINT commit_check1 CHECK (((NOT es_amend) OR (cardinality(parent_ids) = 1))),
    CONSTRAINT commit_origen_dato_check CHECK (((origen_dato)::text = ANY (ARRAY[('MANUAL'::character varying)::text, ('WORKFLOW'::character varying)::text, ('AGENTE'::character varying)::text, ('IMPORT'::character varying)::text]))),
    CONSTRAINT commit_parent_ids_check CHECK ((cardinality(parent_ids) <= 2))
);

ALTER TABLE ONLY chat.commit FORCE ROW LEVEL SECURITY;


