    commit_id uuid NOT NULL,
    orden integer NOT NULL,
    rol character varying(10) NOT NULL,
    contenido text,
    contenido_json jsonb,
    hash character(64) NOT NULL,
    blob_ref character(64),
    tool_calls jsonb,
    tokens_in integer,
    tokens_out integer,
    latencia_ms integer,
    modelo_id uuid,
    agente character varying(30),
    llm_call_id uuid,
    politica_snapshot_id uuid,
    atributos jsonb,
    nivel_clasificacion smallint DEFAULT 2 NOT NULL,
    CONSTRAINT turno_agente_check CHECK (((agente IS NULL) OR ((agente)::text = ANY (ARRAY[('A1'::character varying)::text, ('A2'::character varying)::text, ('A3'::character varying)::text, ('critic'::character varying)::text])))),
    CONSTRAINT turno_check CHECK ((((rol)::text <> 'assistant'::text) OR ((modelo_id IS NOT NULL) AND (agente IS NOT NULL)))),
    CONSTRAINT turno_check1 CHECK ((((rol)::text = 'assistant'::text) OR (modelo_id IS NULL))),
    CONSTRAINT turno_orden_check CHECK ((orden >= 0)),
    CONSTRAINT turno_rol_check CHECK (((rol)::text = ANY (ARRAY[('user'::character varying)::text, ('assistant'::character varying)::text, ('tool'::character varying)::text, ('system'::character varying)::text])))
);

