-- Name: aplicacion; Type: TABLE; Schema: config; Owner: -
--

CREATE TABLE config.aplicacion (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    codigo character varying(60) NOT NULL,
    nombre character varying(120) NOT NULL,
    tipo character varying(12) NOT NULL,
    modelo_card_id uuid,
    libreria_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    config jsonb DEFAULT '{}'::jsonb NOT NULL,
    estado character varying(12) DEFAULT 'propuesta'::character varying NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT aplicacion_check CHECK ((((estado)::text <> 'activa'::text) OR ((tipo)::text <> 'agente'::text) OR (modelo_card_id IS NOT NULL))),
    CONSTRAINT aplicacion_check1 CHECK ((((estado)::text <> 'activa'::text) OR ((tipo)::text <> ALL (ARRAY[('servicio'::character varying)::text, ('worker'::character varying)::text])) OR (cardinality(libreria_ids) >= 1))),
    CONSTRAINT aplicacion_estado_check CHECK (((estado)::text = ANY (ARRAY[('propuesta'::character varying)::text, ('activa'::character varying)::text, ('en_revision'::character varying)::text, ('retirada'::character varying)::text]))),
    CONSTRAINT aplicacion_tipo_check CHECK (((tipo)::text = ANY (ARRAY[('agente'::character varying)::text, ('servicio'::character varying)::text, ('modulo'::character varying)::text, ('worker'::character varying)::text, ('cron'::character varying)::text])))
);


