-- Name: COLUMN schema_registry.esquema_json; Type: COMMENT; Schema: config; Owner: -
--

COMMENT ON COLUMN config.schema_registry.esquema_json IS 'Estructura esperada del registro, con sus campos y restricciones';


--
-- Name: COLUMN schema_registry.vigente_desde; Type: COMMENT; Schema: config; Owner: -
--

COMMENT ON COLUMN config.schema_registry.vigente_desde IS 'Fecha desde la que la versión del esquema es válida';


--
-- Name: COLUMN schema_registry.vigente_hasta; Type: COMMENT; Schema: config; Owner: -
--

COMMENT ON COLUMN config.schema_registry.vigente_hasta IS 'Fecha en que la versión deja de aplicarse, vacía si sigue vigente';


--
-- Name: servicio_externo; Type: TABLE; Schema: config; Owner: -
--

CREATE TABLE config.servicio_externo (
    codigo text NOT NULL,
    nombre text NOT NULL,
    unidad text NOT NULL,
    costo_unitario_usd numeric(12,6),
    moneda text DEFAULT 'USD'::text NOT NULL,
    activo boolean DEFAULT true NOT NULL,
    observacion text,
    creado_en timestamp with time zone DEFAULT now() NOT NULL
);

ALTER TABLE ONLY config.servicio_externo FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE servicio_externo; Type: COMMENT; Schema: config; Owner: -
--

COMMENT ON TABLE config.servicio_externo IS 'Catálogo de los servicios externos que generan gasto, con la unidad en que se mide su consumo (token, mensaje, consulta). Da nombre y unidad a los códigos SVC-xx que usa el ERS.';


--
-- Name: COLUMN servicio_externo.codigo; Type: COMMENT; Schema: config; Owner: -
--

COMMENT ON COLUMN config.servicio_externo.codigo IS 'Código del servicio en el ERS (SVC-02, SVC-06, SVC-07, SVC-16).';


--
-- Name: COLUMN servicio_externo.nombre; Type: COMMENT; Schema: config; Owner: -
--

COMMENT ON COLUMN config.servicio_externo.nombre IS 'Nombre legible del servicio, el que se muestra en el panel de costos.';


--
-- Name: COLUMN servicio_externo.unidad; Type: COMMENT; Schema: config; Owner: -
--

COMMENT ON COLUMN config.servicio_externo.unidad IS 'Unidad de medida del consumo: token, mensaje o consulta.';


--
-- Name: COLUMN servicio_externo.costo_unitario_usd; Type: COMMENT; Schema: config; Owner: -
--

COMMENT ON COLUMN config.servicio_externo.costo_unitario_usd IS 'Costo de referencia por unidad. NULL si el proveedor cobra por tramos y el costo real solo se conoce al cerrar el mes.';


--
-- Name: COLUMN servicio_externo.moneda; Type: COMMENT; Schema: config; Owner: -
--

COMMENT ON COLUMN config.servicio_externo.moneda IS 'Moneda del costo unitario. Hoy siempre USD: si alguien factura en soles, aquí se ve antes de que el total mezcle monedas.';


--
-- Name: COLUMN servicio_externo.activo; Type: COMMENT; Schema: config; Owner: -
--

COMMENT ON COLUMN config.servicio_externo.activo IS 'false cuando el servicio deja de usarse; los históricos de consumo se conservan.';


--
-- Name: COLUMN servicio_externo.observacion; Type: COMMENT; Schema: config; Owner: -
--

COMMENT ON COLUMN config.servicio_externo.observacion IS 'Qué se cobra y con qué periodicidad; el detalle que explica el costo unitario.';


--
-- Name: COLUMN servicio_externo.creado_en; Type: COMMENT; Schema: config; Owner: -
--

COMMENT ON COLUMN config.servicio_externo.creado_en IS 'Cuándo se dio de alta el servicio en el catálogo.';


--
-- Name: tope_gasto; Type: TABLE; Schema: config; Owner: -
--

CREATE TABLE config.tope_gasto (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    servicio_codigo text NOT NULL,
    periodo text DEFAULT 'mensual'::text NOT NULL,
    monto_usd numeric(12,2) NOT NULL,
    umbral_aviso_pct smallint DEFAULT 80 NOT NULL,
    vigente_desde date DEFAULT (date_trunc('month'::text, now()))::date NOT NULL,
    vigente_hasta date,
    aprobado_por uuid,
    aprobado_en timestamp with time zone,
    observacion text,
    creado_en timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_tope_monto_positivo CHECK ((monto_usd > (0)::numeric)),
    CONSTRAINT ck_tope_periodo CHECK ((periodo = 'mensual'::text)),
    CONSTRAINT ck_tope_umbral CHECK (((umbral_aviso_pct >= 1) AND (umbral_aviso_pct <= 100))),
    CONSTRAINT ck_tope_vigencia CHECK (((vigente_hasta IS NULL) OR (vigente_hasta >= vigente_desde)))
);

ALTER TABLE ONLY config.tope_gasto FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE tope_gasto; Type: COMMENT; Schema: config; Owner: -
--

COMMENT ON TABLE config.tope_gasto IS 'Tope de gasto por servicio y periodo (RNF-13). Mientras no exista fila para un servicio, su estado es `sin_tope`: el mecanismo está listo pero el monto lo fija la decisión H-65.';


--
-- Name: COLUMN tope_gasto.id; Type: COMMENT; Schema: config; Owner: -
--

COMMENT ON COLUMN config.tope_gasto.id IS 'Identificador del tope. Existe para poder versionar el monto de un mismo servicio y periodo sin sobrescribir el anterior.';


--
-- Name: COLUMN tope_gasto.servicio_codigo; Type: COMMENT; Schema: config; Owner: -
--

COMMENT ON COLUMN config.tope_gasto.servicio_codigo IS 'Servicio externo al que se aplica el tope.';


--
-- Name: COLUMN tope_gasto.periodo; Type: COMMENT; Schema: config; Owner: -
--

COMMENT ON COLUMN config.tope_gasto.periodo IS 'Periodo que cubre el tope. Hoy solo admite mensual (restricción ck_tope_periodo).';


--
-- Name: COLUMN tope_gasto.monto_usd; Type: COMMENT; Schema: config; Owner: -
--

COMMENT ON COLUMN config.tope_gasto.monto_usd IS 'Gasto máximo admitido en el periodo, en dólares.';


--
-- Name: COLUMN tope_gasto.umbral_aviso_pct; Type: COMMENT; Schema: config; Owner: -
--

COMMENT ON COLUMN config.tope_gasto.umbral_aviso_pct IS 'Porcentaje del tope a partir del cual se emite el aviso previo (80 % por defecto). Con 100 el estado pasa de normal a excedido sin aviso intermedio.';


--
-- Name: COLUMN tope_gasto.vigente_desde; Type: COMMENT; Schema: config; Owner: -
--

COMMENT ON COLUMN config.tope_gasto.vigente_desde IS 'Primer día del periodo cubierto. Junto con servicio y periodo forma la clave única del tope vigente.';


--
-- Name: COLUMN tope_gasto.vigente_hasta; Type: COMMENT; Schema: config; Owner: -
--

COMMENT ON COLUMN config.tope_gasto.vigente_hasta IS 'Último día cubierto. NULL significa que el tope sigue vigente hasta que otro lo reemplace.';


--
-- Name: COLUMN tope_gasto.aprobado_por; Type: COMMENT; Schema: config; Owner: -
--

COMMENT ON COLUMN config.tope_gasto.aprobado_por IS 'Usuario que aprobó el tope. Un tope sin aprobación es una estimación, no una decisión.';


--
-- Name: COLUMN tope_gasto.aprobado_en; Type: COMMENT; Schema: config; Owner: -
--

COMMENT ON COLUMN config.tope_gasto.aprobado_en IS 'Cuándo se aprobó. Un tope sin fecha está propuesto, pero **sí limita**: en gasto es preferible quedarse corto por un tope no aprobado que pasarse por no tener ninguno. La fecha sirve para saber quién decidió el monto, no para desactivarlo.';


--
-- Name: COLUMN tope_gasto.observacion; Type: COMMENT; Schema: config; Owner: -
--

COMMENT ON COLUMN config.tope_gasto.observacion IS 'Motivo del monto y de dónde salió la cifra.';


--
-- Name: COLUMN tope_gasto.creado_en; Type: COMMENT; Schema: config; Owner: -
--

COMMENT ON COLUMN config.tope_gasto.creado_en IS 'Cuándo se registró la fila.';


--
-- Name: consulta_reniec; Type: TABLE; Schema: core; Owner: -
--

CREATE TABLE core.consulta_reniec (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    actor_uid uuid NOT NULL,
    caso_id uuid,
    consultado_por_usuario_id uuid NOT NULL,
    motivo text NOT NULL,
    fecha_consulta timestamp with time zone DEFAULT now() NOT NULL,
    integracion_id uuid,
    resultado_cifrado bytea NOT NULL,
    resultado_hmac character(64) NOT NULL,
    nivel_clasificacion smallint DEFAULT 3 NOT NULL,
    CONSTRAINT ck_consulta_reniec_confidencial CHECK ((nivel_clasificacion = 3)),
    CONSTRAINT ck_consulta_reniec_motivo CHECK ((length(btrim(motivo)) >= 15))
);

ALTER TABLE ONLY core.consulta_reniec FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE consulta_reniec; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON TABLE core.consulta_reniec IS 'Registro de cada consulta a PIDE-RENIEC (SVC-16): quién la pidió, sobre qué actor, por qué y cuándo, con el resultado cifrado. Sin columna de etiqueta: la base no clasifica personas (prohibición de etiquetado sin sentencia firme). Origen: RF-D13, RA-07, RA-08, RN-17.';


--
-- Name: COLUMN consulta_reniec.id; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.consulta_reniec.id IS 'Identificador interno de la consulta.';


--
-- Name: COLUMN consulta_reniec.actor_uid; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.consulta_reniec.actor_uid IS 'Actor sobre el que se consultó, según core.actores.';


--
-- Name: COLUMN consulta_reniec.caso_id; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.consulta_reniec.caso_id IS 'Caso en cuyo contexto se pidió la consulta, si la consulta se hizo por uno.';


--
-- Name: COLUMN consulta_reniec.consultado_por_usuario_id; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.consulta_reniec.consultado_por_usuario_id IS 'Persona que pidió y ejecutó la consulta; solo puede ser quien tiene el privilegio.';


--
-- Name: COLUMN consulta_reniec.motivo; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.consulta_reniec.motivo IS 'Motivo del pedido, escrito por la persona. Obligatorio y de al menos 15 caracteres: es la justificación de finalidad que exige la Ley 29733.';


--
-- Name: COLUMN consulta_reniec.fecha_consulta; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.consulta_reniec.fecha_consulta IS 'Momento en que se hizo la consulta a PIDE-RENIEC.';


--
-- Name: COLUMN consulta_reniec.integracion_id; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.consulta_reniec.integracion_id IS 'Integración por la que se llegó al servicio, según core.integraciones.';


--
-- Name: COLUMN consulta_reniec.resultado_cifrado; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.consulta_reniec.resultado_cifrado IS 'Resultado de la consulta cifrado con AES-256 (pgp_sym_encrypt). Se descifra solo con la clave de sesión app.crypto_key.';


--
-- Name: COLUMN consulta_reniec.resultado_hmac; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.consulta_reniec.resultado_hmac IS 'Huella del resultado en claro (SHA-256 con sal de la aplicación). Sirve para detectar consultas repetidas sin descifrar el contenido.';


--
-- Name: COLUMN consulta_reniec.nivel_clasificacion; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.consulta_reniec.nivel_clasificacion IS 'Fijo en 3 (Confidencial). Las reglas de acceso solo distinguen niveles 1 a 3; fijarlo impide degradar la protección por error.';


--
-- Name: envios_comunicacion; Type: TABLE; Schema: core; Owner: -
--

CREATE TABLE core.envios_comunicacion (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    codigo character varying(50),
    fecha_envio timestamp with time zone NOT NULL,
    canal character varying(20) NOT NULL,
    entidad_tipo character varying(30),
    entidad_id uuid,
    remitente_usuario_id uuid,
    rol_remitente character varying(60),
    destinatario_texto text,
    url_pdf character varying(500),
    resultado character varying(255),
    observacion text,
    id_externo character varying(120),
    plantilla_codigo character varying(80),
    estado_entrega character varying(20),
    costo_estimado_usd numeric(12,6),
    actualizado_en timestamp with time zone,
    CONSTRAINT ck_envio_estado_entrega CHECK (((estado_entrega IS NULL) OR ((estado_entrega)::text = ANY (ARRAY['enviado'::text, 'entregado'::text, 'leido'::text, 'fallido'::text, 'sin_confirmar'::text])))),
    CONSTRAINT envios_comunicacion_canal_check CHECK (((canal)::text = ANY (ARRAY[('Correo'::character varying)::text, ('WhatsApp'::character varying)::text, ('Otro'::character varying)::text])))
);


--
-- Name: TABLE envios_comunicacion; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON TABLE core.envios_comunicacion IS 'Envío de comunicaciones y oficios, con su canal, remitente, destinatario, documento adjunto y resultado de la entrega.';


--
-- Name: COLUMN envios_comunicacion.id; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.envios_comunicacion.id IS 'Identificador interno de la fila';


--
-- Name: COLUMN envios_comunicacion.codigo; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.envios_comunicacion.codigo IS 'Código único con el que se identifica el envío';


--
-- Name: COLUMN envios_comunicacion.fecha_envio; Type: COMMENT; Schema: core; Owner: -
