COMMENT ON COLUMN core.envios_comunicacion.fecha_envio IS 'Momento en que se realizó el envío';


--
-- Name: COLUMN envios_comunicacion.canal; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.envios_comunicacion.canal IS 'Canal usado para el envío, como correo o mesa de partes';


--
-- Name: COLUMN envios_comunicacion.entidad_tipo; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.envios_comunicacion.entidad_tipo IS 'Tipo de registro al que se asocia el envío';


--
-- Name: COLUMN envios_comunicacion.entidad_id; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.envios_comunicacion.entidad_id IS 'Identificador del registro al que se asocia el envío';


--
-- Name: COLUMN envios_comunicacion.remitente_usuario_id; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.envios_comunicacion.remitente_usuario_id IS 'Usuario que remitió la comunicación';


--
-- Name: COLUMN envios_comunicacion.rol_remitente; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.envios_comunicacion.rol_remitente IS 'Rol con el que actuó el remitente del envío';


--
-- Name: COLUMN envios_comunicacion.destinatario_texto; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.envios_comunicacion.destinatario_texto IS 'Destinatario del envío tal como se consignó';


--
-- Name: COLUMN envios_comunicacion.url_pdf; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.envios_comunicacion.url_pdf IS 'Enlace al PDF del oficio o comunicación enviada';


--
-- Name: COLUMN envios_comunicacion.resultado; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.envios_comunicacion.resultado IS 'Resultado de la entrega de la comunicación';


--
-- Name: COLUMN envios_comunicacion.observacion; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.envios_comunicacion.observacion IS 'Observaciones sobre el envío o sobre su resultado';


--
-- Name: COLUMN envios_comunicacion.id_externo; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.envios_comunicacion.id_externo IS 'Identificador del mensaje en el proveedor (wamid de WhatsApp Cloud API). Su ausencia era la razón por la que no se podía confirmar una entrega.';


--
-- Name: COLUMN envios_comunicacion.plantilla_codigo; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.envios_comunicacion.plantilla_codigo IS 'Código de la plantilla de mensaje con la que se redactó el envío.';


--
-- Name: COLUMN envios_comunicacion.estado_entrega; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.envios_comunicacion.estado_entrega IS 'enviado · entregado · leido · fallido · sin_confirmar. Lo actualiza el webhook de Meta; el envío nace en sin_confirmar.';


--
-- Name: COLUMN envios_comunicacion.costo_estimado_usd; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.envios_comunicacion.costo_estimado_usd IS 'Costo del mensaje de utilidad. RNF-13: consumo por servicio y por mes.';


--
-- Name: COLUMN envios_comunicacion.actualizado_en; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.envios_comunicacion.actualizado_en IS 'Momento de la última actualización del estado del envío.';


--
-- Name: v_consumo_servicio_mes; Type: VIEW; Schema: config; Owner: -
--

CREATE VIEW config.v_consumo_servicio_mes AS
 WITH medicion AS (
         SELECT 'SVC-02'::text AS servicio_codigo,
            (date_trunc('month'::text, l.ts))::date AS mes,
            count(*) AS unidades,
            sum(((COALESCE(l.tokens_in, 0) + COALESCE(l.tokens_out, 0)) + COALESCE(l.tokens_thinking, 0))) AS tokens,
            (sum(COALESCE(l.costo_estimado_usd, (0)::numeric)))::numeric(14,4) AS costo_usd
           FROM agent.llm_call l
          GROUP BY 'SVC-02'::text, ((date_trunc('month'::text, l.ts))::date)
        UNION ALL
         SELECT
                CASE
                    WHEN (lower((e.canal)::text) ~~ '%whatsapp%'::text) THEN 'SVC-07'::text
                    WHEN ((lower((e.canal)::text) ~~ '%correo%'::text) OR (lower((e.canal)::text) ~~ '%email%'::text)) THEN 'SVC-06'::text
                    ELSE 'SVC-OTROS'::text
                END AS servicio_codigo,
            (date_trunc('month'::text, e.fecha_envio))::date AS mes,
            count(*) AS unidades,
            (0)::bigint AS tokens,
            (sum(COALESCE(e.costo_estimado_usd, (0)::numeric)))::numeric(14,4) AS costo_usd
           FROM core.envios_comunicacion e
          WHERE (e.fecha_envio IS NOT NULL)
          GROUP BY
                CASE
                    WHEN (lower((e.canal)::text) ~~ '%whatsapp%'::text) THEN 'SVC-07'::text
                    WHEN ((lower((e.canal)::text) ~~ '%correo%'::text) OR (lower((e.canal)::text) ~~ '%email%'::text)) THEN 'SVC-06'::text
                    ELSE 'SVC-OTROS'::text
                END, ((date_trunc('month'::text, e.fecha_envio))::date)
        UNION ALL
         SELECT 'SVC-16'::text AS servicio_codigo,
            (date_trunc('month'::text, r.fecha_consulta))::date AS mes,
            count(*) AS unidades,
            (0)::bigint AS tokens,
            (0)::numeric(14,4) AS costo_usd
           FROM core.consulta_reniec r
          WHERE (r.fecha_consulta IS NOT NULL)
          GROUP BY 'SVC-16'::text, ((date_trunc('month'::text, r.fecha_consulta))::date)
        )
 SELECT m.servicio_codigo,
    COALESCE(s.nombre, m.servicio_codigo) AS servicio,
    s.unidad,
    m.mes,
    m.unidades,
    m.tokens,
    m.costo_usd,
    t.monto_usd AS tope_usd,
    t.umbral_aviso_pct,
        CASE
            WHEN ((t.monto_usd IS NULL) OR (t.monto_usd = (0)::numeric)) THEN NULL::numeric
            ELSE round(((m.costo_usd / t.monto_usd) * (100)::numeric), 1)
        END AS pct_consumido,
        CASE
            WHEN (t.id IS NULL) THEN 'sin_tope'::text
            WHEN (m.costo_usd >= t.monto_usd) THEN 'excedido'::text
            WHEN (m.costo_usd >= ((t.monto_usd * (t.umbral_aviso_pct)::numeric) / 100.0)) THEN 'aviso'::text
            ELSE 'normal'::text
        END AS estado
   FROM ((medicion m
     LEFT JOIN config.servicio_externo s ON ((s.codigo = m.servicio_codigo)))
     LEFT JOIN LATERAL ( SELECT t2.id,
            t2.monto_usd,
            t2.umbral_aviso_pct
           FROM config.tope_gasto t2
          WHERE ((t2.servicio_codigo = m.servicio_codigo) AND (t2.periodo = 'mensual'::text) AND (m.mes >= t2.vigente_desde) AND ((t2.vigente_hasta IS NULL) OR (m.mes <= t2.vigente_hasta)))
          ORDER BY t2.vigente_desde DESC, t2.creado_en DESC
         LIMIT 1) t ON (true));


--
-- Name: VIEW v_consumo_servicio_mes; Type: COMMENT; Schema: config; Owner: -
--

COMMENT ON VIEW config.v_consumo_servicio_mes IS 'Consumo y costo de cada servicio externo por mes, con su tope y el estado del tope (sin_tope, normal, aviso, excedido). Es la cifra que alimenta el panel de costos de RNF-13. Corre con los permisos del dueño para que el total de un mes no dependa del nivel de quien consulta.';


--
-- Name: v_tope_aviso; Type: VIEW; Schema: config; Owner: -
--

CREATE VIEW config.v_tope_aviso AS
 SELECT servicio_codigo,
    servicio,
    unidad,
    mes,
    unidades,
    costo_usd,
    tope_usd,
    pct_consumido,
    estado
   FROM config.v_consumo_servicio_mes
  WHERE (estado = ANY (ARRAY['aviso'::text, 'excedido'::text]));


--
-- Name: VIEW v_tope_aviso; Type: COMMENT; Schema: config; Owner: -
--

COMMENT ON VIEW config.v_tope_aviso IS 'Solo los servicios que cruzaron el umbral de aviso o agotaron su tope. Si esta vista devuelve filas, el aplicativo tiene que avisar (RNF-13). Vacía significa que no hay nada que avisar.';


--
-- Name: actores; Type: TABLE; Schema: consultation; Owner: -
--

CREATE TABLE consultation.actores (
    proceso_id uuid NOT NULL,
    actor_id uuid NOT NULL,
    rol_en_consulta character varying(50)
);


--
-- Name: TABLE actores; Type: COMMENT; Schema: consultation; Owner: -
--

COMMENT ON TABLE consultation.actores IS 'Participación de un actor en un proceso de consulta previa, con el rol que cumple en esa consulta y su vinculación con el padrón general.';


--
-- Name: COLUMN actores.proceso_id; Type: COMMENT; Schema: consultation; Owner: -
--

COMMENT ON COLUMN consultation.actores.proceso_id IS 'Proceso de consulta previa en el que participa el actor';


--
-- Name: COLUMN actores.actor_id; Type: COMMENT; Schema: consultation; Owner: -
--

COMMENT ON COLUMN consultation.actores.actor_id IS 'Actor del padrón general vinculado a la consulta previa';


--
-- Name: COLUMN actores.rol_en_consulta; Type: COMMENT; Schema: consultation; Owner: -
--

COMMENT ON COLUMN consultation.actores.rol_en_consulta IS 'Rol que cumple el actor dentro de ese proceso de consulta';


--
-- Name: etapas; Type: TABLE; Schema: consultation; Owner: -
--

CREATE TABLE consultation.etapas (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    proceso_id uuid NOT NULL,
    tipo_etapa character varying(50) NOT NULL,
    fecha_inicio date,
    fecha_fin date,
    documento_evidencia_url character varying(500),
    observaciones text,
