    base_legal_id smallint,
    CONSTRAINT actor_datos_personales_genero_check CHECK (((genero)::text = ANY (ARRAY[('Femenino'::character varying)::text, ('Masculino'::character varying)::text, ('No_binario'::character varying)::text, ('No_declara'::character varying)::text])))
);

ALTER TABLE ONLY core.actor_datos_personales FORCE ROW LEVEL SECURITY;


--
