-- Name: COLUMN actor_datos_personales.nivel_clasificacion; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.actor_datos_personales.nivel_clasificacion IS 'Nivel de acceso al dato: 1 público, 2 reservado, 3 confidencial';


