    CONSTRAINT acuerdo_ospa_sni_precio_acordado_sol_kg_check CHECK (((precio_acordado_sol_kg IS NULL) OR (precio_acordado_sol_kg >= (0)::numeric))),
    CONSTRAINT acuerdo_ospa_sni_precio_efectivo_sol_kg_check CHECK (((precio_efectivo_sol_kg IS NULL) OR (precio_efectivo_sol_kg >= (0)::numeric))),
    CONSTRAINT acuerdo_ospa_sni_volumen_comprometido_tn_check CHECK (((volumen_comprometido_tn IS NULL) OR (volumen_comprometido_tn >= (0)::numeric))),
    CONSTRAINT acuerdo_ospa_sni_volumen_entregado_tn_check CHECK (((volumen_entregado_tn IS NULL) OR (volumen_entregado_tn >= (0)::numeric)))
);

