-- Name: COLUMN acuerdo_ospa_sni.denominador_conocido; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.acuerdo_ospa_sni.denominador_conocido IS 'Indica si se conoce el universo total con el que se mide el cumplimiento';


--
-- Name: COLUMN acuerdo_ospa_sni.nivel_clasificacion; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.acuerdo_ospa_sni.nivel_clasificacion IS 'Nivel de acceso al dato: 1 público, 2 reservado, 3 confidencial';


--
-- Name: COLUMN acuerdo_ospa_sni.notas; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.acuerdo_ospa_sni.notas IS 'Observaciones libres sobre la suscripción, ejecución o incumplimiento del acuerdo';


--
-- Name: adjunto; Type: TABLE; Schema: core; Owner: -
--

CREATE TABLE core.adjunto (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    entidad_tipo character varying(30) NOT NULL,
    entidad_id uuid NOT NULL,
    nombre character varying(255) NOT NULL,
    mime character varying(120),
    tamano_bytes bigint,
    contenido bytea,
    hash_sha256 character(64),
    descripcion text,
    subido_por uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    anulado_en timestamp with time zone,
    anulado_por uuid,
    motivo_anulacion text,
    CONSTRAINT adjunto_entidad_tipo_check CHECK (((entidad_tipo)::text = ANY ((ARRAY['alerta'::character varying, 'compromiso'::character varying, 'hito'::character varying, 'documento'::character varying, 'reunion'::character varying, 'caso'::character varying, 'demanda'::character varying])::text[])))
);


--
-- Name: TABLE adjunto; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON TABLE core.adjunto IS 'Adjuntos de alertas, compromisos, hitos, documentos, reuniones, casos y demandas. Binario en bytea, igual que core.medios.';


--
-- Name: alerta_destinatario; Type: TABLE; Schema: core; Owner: -
--

CREATE TABLE core.alerta_destinatario (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    alerta_id uuid NOT NULL,
    usuario_id uuid,
    cargo character varying(80),
    canal character varying(20) DEFAULT 'correo'::character varying NOT NULL,
    motivo character varying(120),
    notificado_en timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_by uuid,
    CONSTRAINT alerta_destinatario_canal_valido CHECK (((canal)::text = ANY (ARRAY[('correo'::character varying)::text, ('whatsapp'::character varying)::text, ('sms'::character varying)::text]))),
    CONSTRAINT alerta_destinatario_identidad CHECK (((usuario_id IS NULL) <> (cargo IS NULL))),
    CONSTRAINT alerta_destinatario_notificado_coherente CHECK (((notificado_en IS NULL) OR (notificado_en >= created_at)))
);

ALTER TABLE ONLY core.alerta_destinatario FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE alerta_destinatario; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON TABLE core.alerta_destinatario IS 'Destinatarios nombrados de una alerta: las personas a las que se remite cuando la visibilidad es «sectorial». El destinatario es un usuario del sistema (usuario_id) o un cargo sin cuenta (cargo), nunca los dos. Reemplaza el mapeo aproximado a core.alertas_actores, que relaciona la alerta con los actores del conflicto y no con quienes reciben el aviso';


--
-- Name: COLUMN alerta_destinatario.id; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.alerta_destinatario.id IS 'Identificador interno de la fila';


--
-- Name: COLUMN alerta_destinatario.alerta_id; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.alerta_destinatario.alerta_id IS 'Alerta a la que pertenece el destinatario, según core.alertas_tempranas. Al borrar la alerta se borran sus destinatarios';


--
-- Name: COLUMN alerta_destinatario.usuario_id; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.alerta_destinatario.usuario_id IS 'Persona con cuenta en el sistema a la que se remite la alerta. Excluyente con cargo';


--
-- Name: COLUMN alerta_destinatario.cargo; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.alerta_destinatario.cargo IS 'Cargo sin cuenta en el sistema al que se remite la alerta, por ejemplo una jefatura de gabinete. Excluyente con usuario_id. Se compara sin distinguir mayúsculas en la unicidad';


--
-- Name: COLUMN alerta_destinatario.canal; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.alerta_destinatario.canal IS 'Canal del aviso: correo, whatsapp o sms. Un mismo destinatario puede tener una fila por canal';


--
-- Name: COLUMN alerta_destinatario.motivo; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.alerta_destinatario.motivo IS 'Motivo o causa del aviso, cuando el canal no basta para explicar por qué se remite a esta persona o cargo';


--
-- Name: COLUMN alerta_destinatario.notificado_en; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.alerta_destinatario.notificado_en IS 'Momento en que el envío se completó por este canal. NULL mientras el aviso esté pendiente; no puede ser anterior a la creación de la fila';


--
-- Name: COLUMN alerta_destinatario.created_at; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.alerta_destinatario.created_at IS 'Momento en que se creó el registro';


--
-- Name: COLUMN alerta_destinatario.updated_at; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.alerta_destinatario.updated_at IS 'Momento de la última modificación del registro';


--
-- Name: COLUMN alerta_destinatario.created_by; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.alerta_destinatario.created_by IS 'Usuario que registró el destinatario';


--
-- Name: COLUMN alerta_destinatario.updated_by; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.alerta_destinatario.updated_by IS 'Usuario que realizó la última modificación del registro';


--
-- Name: alerta_especies; Type: TABLE; Schema: core; Owner: -
--

CREATE TABLE core.alerta_especies (
    alerta_id uuid NOT NULL,
    especie_id smallint NOT NULL
);

ALTER TABLE ONLY core.alerta_especies FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE alerta_especies; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON TABLE core.alerta_especies IS 'Especies involucradas en una alerta temprana, como vínculo entre la alerta y el catálogo de especies del sector.';


--
-- Name: COLUMN alerta_especies.alerta_id; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.alerta_especies.alerta_id IS 'Alerta temprana a la que se vincula la especie';


--
-- Name: COLUMN alerta_especies.especie_id; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.alerta_especies.especie_id IS 'Especie involucrada en la alerta, tomada del catálogo de especies';


--
-- Name: alerta_revision; Type: TABLE; Schema: core; Owner: -
--

CREATE TABLE core.alerta_revision (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    alerta_id uuid NOT NULL,
    usuario_id uuid,
    accion character varying(255),
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE alerta_revision; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON TABLE core.alerta_revision IS 'Historial de revisiones de la alerta: quién la revisó, cuándo y con qué acción (validar, aprobar, solicitar modificación, enviar a revisión).';


--
-- Name: alerta_triaje; Type: TABLE; Schema: core; Owner: -
--

CREATE TABLE core.alerta_triaje (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    alerta_id uuid NOT NULL,
    estado character varying(20) DEFAULT 'pendiente'::character varying NOT NULL,
    motivo text,
    duplicada_de uuid,
    nivel_clasificacion smallint DEFAULT 2 NOT NULL,
    triado_por uuid,
    triado_en timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_by uuid,
    CONSTRAINT alerta_triaje_estado_check CHECK (((estado)::text = ANY ((ARRAY['pendiente'::character varying, 'en_triage'::character varying, 'confirmada'::character varying, 'descartada'::character varying, 'duplicada'::character varying])::text[]))),
    CONSTRAINT alerta_triaje_motivo_obligatorio CHECK ((((estado)::text <> ALL ((ARRAY['descartada'::character varying, 'duplicada'::character varying])::text[])) OR ((motivo IS NOT NULL) AND (btrim(motivo) <> ''::text)))),
    CONSTRAINT alerta_triaje_no_autoduplicada CHECK (((duplicada_de IS NULL) OR (duplicada_de <> alerta_id)))
);

ALTER TABLE ONLY core.alerta_triaje FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE alerta_triaje; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON TABLE core.alerta_triaje IS 'Estado de triaje de una alerta temprana en la bandeja RED-RADAR. Una fila por alerta; guarda la decisión (confirmada, descartada, duplicada…), su motivo obligatorio y quién la tomó.';


--
-- Name: COLUMN alerta_triaje.estado; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.alerta_triaje.estado IS 'pendiente | en_triage | confirmada | descartada | duplicada. Una alerta sin fila aquí se trata como «pendiente» en la cola.';


--
-- Name: COLUMN alerta_triaje.motivo; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.alerta_triaje.motivo IS 'Motivo de la decisión. Obligatorio cuando el estado es «descartada» o «duplicada» (Anexo 03 · item 38).';


--
-- Name: COLUMN alerta_triaje.duplicada_de; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.alerta_triaje.duplicada_de IS 'Alerta existente de la que ésta es duplicada. Sólo aplica al estado «duplicada»; la regla de deduplicación es manual.';


--
-- Name: alertas_actores; Type: TABLE; Schema: core; Owner: -
--

CREATE TABLE core.alertas_actores (
    alerta_id uuid NOT NULL,
    actor_id uuid NOT NULL
);

ALTER TABLE ONLY core.alertas_actores FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE alertas_actores; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON TABLE core.alertas_actores IS 'Actores implicados en una alerta temprana, como vínculo entre la alerta y el padrón de actores.';


--
-- Name: COLUMN alertas_actores.alerta_id; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.alertas_actores.alerta_id IS 'Alerta temprana en la que participa el actor';


--
-- Name: COLUMN alertas_actores.actor_id; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.alertas_actores.actor_id IS 'Actor implicado en la alerta temprana registrada';


--
-- Name: banco_datos_tratamiento; Type: TABLE; Schema: core; Owner: -
--

CREATE TABLE core.banco_datos_tratamiento (
    id smallint NOT NULL,
    codigo character varying(40) NOT NULL,
    nombre character varying(200) NOT NULL,
    finalidad text NOT NULL,
    categorias_datos text NOT NULL,
    colectivos_afectados text,
    tiempo_conservacion_meses smallint NOT NULL,
    nivel_seguridad smallint DEFAULT 3 NOT NULL,
    medidas_seguridad text,
    flujo_transfronterizo boolean DEFAULT false NOT NULL,
    oficial_datos_usuario_id uuid,
    fecha_inscripcion_anpdp date,
    codigo_registro_anpdp character varying(40),
    estado character varying(25) DEFAULT 'pendiente'::character varying NOT NULL,
    nivel_clasificacion smallint DEFAULT 2 NOT NULL,
    activo boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_banco_conservacion CHECK ((tiempo_conservacion_meses > 0)),
    CONSTRAINT ck_banco_estado CHECK (((estado)::text = ANY (ARRAY[('pendiente'::character varying)::text, ('inscrito'::character varying)::text, ('actualizacion_pendiente'::character varying)::text, ('baja'::character varying)::text]))),
    CONSTRAINT ck_banco_inscripcion CHECK ((((estado)::text <> 'inscrito'::text) OR ((fecha_inscripcion_anpdp IS NOT NULL) AND (codigo_registro_anpdp IS NOT NULL)))),
    CONSTRAINT ck_banco_nivel_seguridad CHECK (((nivel_seguridad >= 1) AND (nivel_seguridad <= 3)))
);

ALTER TABLE ONLY core.banco_datos_tratamiento FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE banco_datos_tratamiento; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON TABLE core.banco_datos_tratamiento IS 'Registro del banco de datos personales que exige la Ley 29733: finalidad, categorías tratadas, plazo de conservación, nivel de seguridad, oficial responsable, flujo transfronterizo y estado de inscripción ante la autoridad.';


--
-- Name: COLUMN banco_datos_tratamiento.id; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.banco_datos_tratamiento.id IS 'Identificador interno del banco de datos';


--
-- Name: COLUMN banco_datos_tratamiento.codigo; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.banco_datos_tratamiento.codigo IS 'Identificador corto del banco, usado en la documentación y en el expediente.';


--
-- Name: COLUMN banco_datos_tratamiento.nombre; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.banco_datos_tratamiento.nombre IS 'Nombre oficial del banco de datos personales, tal como se declara ante la autoridad';


--
-- Name: COLUMN banco_datos_tratamiento.finalidad; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.banco_datos_tratamiento.finalidad IS 'Para qué se tratan los datos. Debe coincidir con la declaración inscrita: tratar para un fin no declarado es infracción.';


--
-- Name: COLUMN banco_datos_tratamiento.categorias_datos; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.banco_datos_tratamiento.categorias_datos IS 'Qué categorías se recogen (DNI, nombres, gremio de pertenencia, etc.).';


--
-- Name: COLUMN banco_datos_tratamiento.colectivos_afectados; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.banco_datos_tratamiento.colectivos_afectados IS 'A quiénes se refieren los datos: dirigentes, socios, participantes de mesas.';


--
-- Name: COLUMN banco_datos_tratamiento.tiempo_conservacion_meses; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.banco_datos_tratamiento.tiempo_conservacion_meses IS 'Plazo declarado de conservación, en meses. Pasado el plazo, el dato se elimina o se anonimiza.';


--
-- Name: COLUMN banco_datos_tratamiento.nivel_seguridad; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.banco_datos_tratamiento.nivel_seguridad IS 'Nivel de seguridad exigido (1 básico, 2 medio, 3 alto). Los datos de afiliación sindical o gremial son sensibles: nivel alto.';


--
-- Name: COLUMN banco_datos_tratamiento.medidas_seguridad; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.banco_datos_tratamiento.medidas_seguridad IS 'Resumen de las medidas técnicas y organizativas aplicadas: TLS en tránsito, AES-256 en reposo, RLS por rol, bitácora inmutable.';


--
-- Name: COLUMN banco_datos_tratamiento.flujo_transfronterizo; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.banco_datos_tratamiento.flujo_transfronterizo IS 'Si los datos salen del país. Debe declararse aunque sea negativo.';


--
-- Name: COLUMN banco_datos_tratamiento.oficial_datos_usuario_id; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.banco_datos_tratamiento.oficial_datos_usuario_id IS 'Oficial de Datos Personales (ODP) designado ante la ANPDP.';


--
-- Name: COLUMN banco_datos_tratamiento.fecha_inscripcion_anpdp; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.banco_datos_tratamiento.fecha_inscripcion_anpdp IS 'Fecha de inscripción en el Registro Nacional. NULL = trámite pendiente.';


--
-- Name: COLUMN banco_datos_tratamiento.codigo_registro_anpdp; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.banco_datos_tratamiento.codigo_registro_anpdp IS 'Código que asigna la Autoridad Nacional de Protección de Datos Personales al inscribir el banco; vacío mientras el trámite está pendiente';


--
-- Name: COLUMN banco_datos_tratamiento.estado; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.banco_datos_tratamiento.estado IS 'pendiente | inscrito | actualizacion_pendiente | baja.';


--
-- Name: COLUMN banco_datos_tratamiento.nivel_clasificacion; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.banco_datos_tratamiento.nivel_clasificacion IS 'Nivel de clasificación de la información del propio registro (1 público, 2 interno, 3 reservado)';


--
-- Name: COLUMN banco_datos_tratamiento.activo; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.banco_datos_tratamiento.activo IS 'Indica si el banco sigue en operación; un banco inactivo conserva su historial pero no recibe datos nuevos';


--
-- Name: COLUMN banco_datos_tratamiento.created_at; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.banco_datos_tratamiento.created_at IS 'Momento en que se registró el banco en el sistema';


--
-- Name: COLUMN banco_datos_tratamiento.updated_at; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.banco_datos_tratamiento.updated_at IS 'Momento de la última actualización del registro del banco';


--
-- Name: cambio_normativo; Type: TABLE; Schema: core; Owner: -
--

CREATE TABLE core.cambio_normativo (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tabla_objetivo character varying(60) NOT NULL,
    accion character varying(10) NOT NULL,
    fila_id smallint,
    payload_antes jsonb,
    payload_despues jsonb NOT NULL,
    norma_referencia character varying(120) NOT NULL,
    solicitado_por uuid NOT NULL,
    aprobado_por uuid,
    aprobado_en timestamp with time zone,
    aplicado_en timestamp with time zone,
    revertido_en timestamp with time zone,
    revertido_por uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT cambio_normativo_accion_check CHECK (((accion)::text = ANY (ARRAY[('insertar'::character varying)::text, ('modificar'::character varying)::text, ('desactivar'::character varying)::text]))),
    CONSTRAINT cambio_normativo_check CHECK (((aplicado_en IS NULL) OR (aprobado_por IS NOT NULL)))
);


--
-- Name: TABLE cambio_normativo; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON TABLE core.cambio_normativo IS 'Solicitud de cambio sobre datos normativos, con el antes y el después de la fila, la norma que lo respalda y su aprobación o reversión.';


--
-- Name: COLUMN cambio_normativo.id; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.cambio_normativo.id IS 'Identificador interno de la fila';


--
-- Name: COLUMN cambio_normativo.tabla_objetivo; Type: COMMENT; Schema: core; Owner: -
