COMMENT ON COLUMN core.cambio_normativo.tabla_objetivo IS 'Tabla de datos normativos sobre la que se solicita el cambio';


--
-- Name: COLUMN cambio_normativo.accion; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.cambio_normativo.accion IS 'Operación solicitada sobre la fila: alta, edición o baja';


--
-- Name: COLUMN cambio_normativo.fila_id; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.cambio_normativo.fila_id IS 'Identificador de la fila afectada dentro de la tabla objetivo';


--
-- Name: COLUMN cambio_normativo.payload_antes; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.cambio_normativo.payload_antes IS 'Contenido de la fila antes del cambio, guardado como estructura';


--
-- Name: COLUMN cambio_normativo.payload_despues; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.cambio_normativo.payload_despues IS 'Contenido propuesto de la fila después del cambio';


--
-- Name: COLUMN cambio_normativo.norma_referencia; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.cambio_normativo.norma_referencia IS 'Norma que respalda el cambio solicitado sobre los datos';


--
-- Name: COLUMN cambio_normativo.solicitado_por; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.cambio_normativo.solicitado_por IS 'Usuario que presenta la solicitud de cambio';


--
-- Name: COLUMN cambio_normativo.aprobado_por; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.cambio_normativo.aprobado_por IS 'Usuario que aprueba la solicitud de cambio';


--
-- Name: COLUMN cambio_normativo.aprobado_en; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.cambio_normativo.aprobado_en IS 'Momento en que se aprobó la solicitud';


--
-- Name: COLUMN cambio_normativo.aplicado_en; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.cambio_normativo.aplicado_en IS 'Momento en que el cambio se aplicó efectivamente a los datos';


--
-- Name: COLUMN cambio_normativo.revertido_en; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.cambio_normativo.revertido_en IS 'Momento en que el cambio aplicado fue revertido';


--
-- Name: COLUMN cambio_normativo.revertido_por; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.cambio_normativo.revertido_por IS 'Usuario que dispuso la reversión del cambio';


--
-- Name: COLUMN cambio_normativo.created_at; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.cambio_normativo.created_at IS 'Momento en que se creó el registro';


