-- Name: caso_nudo_critico; Type: TABLE; Schema: core; Owner: -
--

CREATE TABLE core.caso_nudo_critico (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    caso_id uuid NOT NULL,
    compromiso_id uuid,
    semana_desde date NOT NULL,
    semana_hasta date NOT NULL,
    descripcion text,
    seguimiento text,
    estado_id smallint,
    autor_usuario_id uuid,
    autor_texto character varying(200),
    origen_dato character varying(20) DEFAULT 'importacion'::character varying NOT NULL,
    nivel_clasificacion smallint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    anulado_en timestamp with time zone,
    anulado_por uuid,
    anulacion_id uuid,
    motivo_anulacion text,
    origen_ref character varying(40),
    hito_id uuid,
    validado_por_usuario_id uuid,
    validado_en timestamp with time zone,
    CONSTRAINT chk_caso_nudo_critico_contenido CHECK (((descripcion IS NOT NULL) OR (seguimiento IS NOT NULL))),
    CONSTRAINT chk_caso_nudo_critico_semanas CHECK ((semana_hasta >= semana_desde))
);


--
-- Name: TABLE caso_nudo_critico; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON TABLE core.caso_nudo_critico IS 'Nudos críticos semanales de un caso: los obstáculos o cuellos de botella que explican por qué un hito no se cumple. Se registran por periodo y opcionalmente por compromiso.';


--
-- Name: COLUMN caso_nudo_critico.semana_desde; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.caso_nudo_critico.semana_desde IS 'Inicio del periodo que cubre el nudo crítico.';


--
-- Name: COLUMN caso_nudo_critico.semana_hasta; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.caso_nudo_critico.semana_hasta IS 'Fin del periodo que cubre el nudo crítico.';


--
-- Name: COLUMN caso_nudo_critico.descripcion; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.caso_nudo_critico.descripcion IS 'El nudo: el obstáculo o cuello de botella observado en el periodo. NULL cuando la matriz trae sólo el seguimiento (66 celdas en el Excel 2026). Nunca se rellena con texto inventado.';


--
-- Name: COLUMN caso_nudo_critico.seguimiento; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.caso_nudo_critico.seguimiento IS 'Relato del seguimiento en el periodo, con el formato [AÑO] + [ACTOR] + [ACCIÓN] que pide el equipo.';


--
-- Name: COLUMN caso_nudo_critico.estado_id; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.caso_nudo_critico.estado_id IS 'Estado del nudo. Reutiliza core.cat_estados_hito para no crear un tercer vocabulario de estados.';


--
-- Name: COLUMN caso_nudo_critico.origen_dato; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.caso_nudo_critico.origen_dato IS 'Origen del registro: importacion, captura manual o agente.';


--
-- Name: COLUMN caso_nudo_critico.origen_ref; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.caso_nudo_critico.origen_ref IS 'Identificador determinista de la celda de origen en la matriz (p. ej. MATRIZ-N0002-C22). Clave de idempotencia del importador. NULL en captura manual.';


--
-- Name: COLUMN caso_nudo_critico.hito_id; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.caso_nudo_critico.hito_id IS 'Hito al que se refiere el nudo. Nulo cuando la fila de origen no tiene hito (2 de 87 filas del Excel 2026): en ese caso el nudo cuelga sólo del compromiso y el código se declara en el texto. El disparador exige coherencia con compromiso_id.';


--
-- Name: COLUMN caso_nudo_critico.validado_por_usuario_id; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.caso_nudo_critico.validado_por_usuario_id IS 'Usuario que validó el texto del nudo. Distinto de estado_id: validar el contenido no es mover la máquina de estados.';


--
-- Name: COLUMN caso_nudo_critico.validado_en; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.caso_nudo_critico.validado_en IS 'Momento de la validación del texto.';


--
-- Name: CONSTRAINT chk_caso_nudo_critico_contenido ON caso_nudo_critico; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON CONSTRAINT chk_caso_nudo_critico_contenido ON core.caso_nudo_critico IS 'Una fila de nudo debe aportar al menos descripción o seguimiento.';


