-- Name: demandas; Type: TABLE; Schema: core; Owner: -
--

CREATE TABLE core.demandas (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    caso_id uuid,
    problema_3p text,
    propuesta_3p text,
    pedido_3p text,
    estado_atencion character varying(20) DEFAULT 'Pendiente'::character varying NOT NULL,
    motivo_no_atencion text,
    fecha_vencimiento_respuesta date,
    afecta_diferenciadamente_mujeres boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_by uuid,
    origen_dato character varying(20) DEFAULT 'MANUAL'::character varying NOT NULL,
    confidence numeric(3,2),
    es_validado_humano boolean DEFAULT false NOT NULL,
    nivel_clasificacion smallint DEFAULT 2 NOT NULL,
    descripcion_demanda text,
    alerta_id uuid,
    tematica_id integer,
    fecha_registro date,
    tipo_evidencia_legado character varying(80),
    referencia_evidencia_legado character varying(255),
    codigo_legado character varying(50),
    documento_origen_id uuid,
    codigo_padre_legado character varying(50),
    anulado_en timestamp with time zone,
    anulado_por uuid,
    anulacion_id uuid,
    motivo_anulacion text,
    CONSTRAINT demandas_confidence_check CHECK (((confidence >= (0)::numeric) AND (confidence <= (1)::numeric))),
    CONSTRAINT demandas_estado_atencion_check CHECK (((estado_atencion)::text = ANY (ARRAY[('Pendiente'::character varying)::text, ('En proceso'::character varying)::text, ('Atendida'::character varying)::text, ('Desestimada'::character varying)::text]))),
    CONSTRAINT demandas_origen_dato_check CHECK (((origen_dato)::text = ANY (ARRAY[('MANUAL'::character varying)::text, ('KAG'::character varying)::text, ('WORKFLOW'::character varying)::text, ('AVISA_HISTORICO'::character varying)::text, ('WHATSAPP'::character varying)::text])))
);

ALTER TABLE ONLY core.demandas FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE demandas; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON TABLE core.demandas IS 'Demanda planteada por los actores, desagregada en problema, propuesta y pedido, con su estado de atención y su sustento.';


