-- Name: COLUMN log_accesos.rol_declarado; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.log_accesos.rol_declarado IS 'Rol que el usuario declaró al intentar acceder';


--
-- Name: COLUMN log_accesos.resultado; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.log_accesos.resultado IS 'Resultado del intento de acceso, por ejemplo exitoso o denegado';


