--

COMMENT ON COLUMN core.log_accesos.nivel_clasificacion IS 'Nivel de acceso al dato: 1 público, 2 reservado, 3 confidencial';


--
-- Name: log_accesos_id_seq; Type: SEQUENCE; Schema: core; Owner: -
--

ALTER TABLE core.log_accesos ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY (
