);


--
-- Name: mapa_matriz_excel; Type: TABLE; Schema: core; Owner: -
--

CREATE TABLE core.mapa_matriz_excel (
    id smallint NOT NULL,
    fuente character varying(40) DEFAULT 'MATRIZ_OAIPCS_2026'::character varying NOT NULL,
    codigo_excel character varying(40),
    bloque_fila integer NOT NULL,
    caso_id uuid NOT NULL,
    confianza character varying(10) DEFAULT 'alta'::character varying NOT NULL,
    nota text,
    creado_en timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_mapa_matriz_excel_confianza CHECK (((confianza)::text = ANY ((ARRAY['alta'::character varying, 'media'::character varying, 'baja'::character varying])::text[])))
);


--
-- Name: TABLE mapa_matriz_excel; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON TABLE core.mapa_matriz_excel IS 'Equivalencia entre un bloque de la matriz XLSX del equipo y un caso de AVISA. Es la única fuente de verdad para el importador: los códigos del Excel y de la base usan esquemas distintos y colisionan por casualidad.';


--
-- Name: COLUMN mapa_matriz_excel.fuente; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.mapa_matriz_excel.fuente IS 'Identificador de la fuente/versión del Excel (por defecto MATRIZ_OAIPCS_2026).';


--
-- Name: COLUMN mapa_matriz_excel.codigo_excel; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.mapa_matriz_excel.codigo_excel IS 'Código tal como lo escribe la hoja METADATOS CASOS. Nulo en los bloques que no llevan código. NO es comparable con core.casos.codigo_caso.';


--
-- Name: COLUMN mapa_matriz_excel.bloque_fila; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.mapa_matriz_excel.bloque_fila IS 'Fila del Excel donde la columna E (Nombre de Caso) tiene valor por primera vez. Es la clave estable: el N° de la columna A falta en 3 bloques y se repite en 1.';


--
-- Name: COLUMN mapa_matriz_excel.caso_id; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.mapa_matriz_excel.caso_id IS 'Caso de core.casos al que corresponde el bloque (RESTRICT: no se puede borrar un caso mapeado).';


--
-- Name: COLUMN mapa_matriz_excel.confianza; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.mapa_matriz_excel.confianza IS 'Grado de confianza de la equivalencia: alta, media o baja.';


--
-- Name: COLUMN mapa_matriz_excel.nota; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.mapa_matriz_excel.nota IS 'Advertencia de la equivalencia: códigos cruzados, duplicados, casos anulados.';


--
-- Name: mapa_matriz_excel_id_seq; Type: SEQUENCE; Schema: core; Owner: -
--

ALTER TABLE core.mapa_matriz_excel ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME core.mapa_matriz_excel_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: medios; Type: TABLE; Schema: core; Owner: -
--

CREATE TABLE core.medios (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    entidad_tipo character varying(24) NOT NULL,
    entidad_id text NOT NULL,
    rol character varying(12) DEFAULT 'galeria'::character varying NOT NULL,
    titulo character varying(160),
    descripcion text,
    url text NOT NULL,
    mime character varying(100) DEFAULT 'image/jpeg'::character varying NOT NULL,
    ancho integer,
    alto integer,
    bytes bigint,
    orden smallint DEFAULT 0 NOT NULL,
    es_principal boolean DEFAULT false NOT NULL,
    alt character varying(240),
    credito character varying(160),
    fuente character varying(20) DEFAULT 'MANUAL'::character varying NOT NULL,
    consentimiento_fecha date,
    base_legal character varying(120),
    nivel_clasificacion smallint DEFAULT 2 NOT NULL,
    anulado_en timestamp with time zone,
    motivo_anulacion text,
    anulado_por uuid,
    anulacion_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_by uuid,
    contenido bytea,
    content_type text,
    hash text,
    cargado_en timestamp with time zone,
    CONSTRAINT medios_alto_check CHECK (((alto IS NULL) OR (alto > 0))),
    CONSTRAINT medios_ancho_check CHECK (((ancho IS NULL) OR (ancho > 0))),
    CONSTRAINT medios_bytes_check CHECK (((bytes IS NULL) OR (bytes >= 0))),
    CONSTRAINT medios_entidad_tipo_check CHECK (((entidad_tipo)::text = ANY ((ARRAY['actor'::character varying, 'organizacion'::character varying, 'local'::character varying, 'caso'::character varying, 'documento'::character varying, 'reunion'::character varying])::text[]))),
    CONSTRAINT medios_fuente_check CHECK (((fuente)::text = ANY ((ARRAY['MANUAL'::character varying, 'CARGA'::character varying, 'WORKFLOW'::character varying, 'AVISA_HISTORICO'::character varying, 'WHATSAPP'::character varying, 'KAG'::character varying])::text[]))),
    CONSTRAINT medios_rol_check CHECK (((rol)::text = ANY ((ARRAY['principal'::character varying, 'galeria'::character varying, 'adjunto'::character varying, 'evidencia'::character varying])::text[])))
);

ALTER TABLE ONLY core.medios FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE medios; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON TABLE core.medios IS 'Galería de medios por entidad (persona, organización, local, caso, documento o reunión). Una entidad puede tener varias fotos; la principal se marca con es_principal. La clave es polimórfica: la integridad la valida la aplicación, no una FK.';


--
-- Name: COLUMN medios.entidad_tipo; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.medios.entidad_tipo IS 'Tipo de entidad dueña del medio. No es una FK: el endpoint valida el valor.';


--
-- Name: COLUMN medios.entidad_id; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.medios.entidad_id IS 'Identificador de la entidad en texto (UUID, código o entero).';


--
-- Name: COLUMN medios.rol; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.medios.rol IS 'principal | galeria | adjunto | evidencia. Ordena el uso en la interfaz.';


--
-- Name: COLUMN medios.url; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.medios.url IS 'URL o ruta del archivo. No se guardan binarios en la base.';


--
-- Name: COLUMN medios.es_principal; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.medios.es_principal IS 'Foto que se muestra en la tabla y en la cabecera. Hay un único índice parcial que impide dos principales vigentes por entidad.';


--
-- Name: COLUMN medios.alt; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.medios.alt IS 'Texto alternativo para lectores de pantalla. Si falta, la UI usa el título.';


--
-- Name: COLUMN medios.consentimiento_fecha; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.medios.consentimiento_fecha IS 'Fecha del consentimiento para publicar la imagen. NULL = sin dato; no se estima.';


--
-- Name: COLUMN medios.nivel_clasificacion; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.medios.nivel_clasificacion IS 'Nivel de acceso de la imagen (1 público … 3 restringido). Se aplica con la misma RLS que el resto de core.';


--
-- Name: COLUMN medios.contenido; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.medios.contenido IS 'Bytes de la imagen almacenados en la base. Es una EXCEPCIÓN APROBADA al criterio «no se guardan binarios en la base» de la migración 41: sirve como respaldo servible porque el archivo estático (angular/public/medios, untracked en git) no llega a un clon limpio ni a producción. El archivo estático se conserva como respaldo. NULL = aún no cargado; no se estima.';


--
-- Name: COLUMN medios.content_type; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.medios.content_type IS 'Tipo MIME de `contenido` (p. ej. image/jpeg), deducido de la extensión al cargar con scripts/cargar-medios-neon.mjs. NULL si no se ha cargado.';


--
-- Name: COLUMN medios.hash; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.medios.hash IS 'sha256 hexadecimal de `contenido`. Es la guarda de idempotencia de la carga (si coincide, no se reescribe) y el ETag estable que expone el endpoint de contenido. NULL si no se ha cargado.';


--
-- Name: COLUMN medios.cargado_en; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.medios.cargado_en IS 'Momento en que se guardaron los bytes en la base. NULL si aún no se cargó.';


--
-- Name: mesa_miembros; Type: TABLE; Schema: core; Owner: -
--

CREATE TABLE core.mesa_miembros (
