    CONSTRAINT mesas_dialogo_origen_dato_check CHECK (((origen_dato)::text = ANY (ARRAY[('MANUAL'::character varying)::text, ('KAG'::character varying)::text, ('WORKFLOW'::character varying)::text, ('AVISA_HISTORICO'::character varying)::text, ('WHATSAPP'::character varying)::text])))
);

ALTER TABLE ONLY core.mesas_dialogo FORCE ROW LEVEL SECURITY;


--
