--
-- Name: migracion_conflicto; Type: TABLE; Schema: core; Owner: -
--

CREATE TABLE core.migracion_conflicto (
    id bigint NOT NULL,
    fase smallint NOT NULL,
    categoria character varying(40) NOT NULL,
    hoja_legado character varying(60),
    fila_legado integer,
    codigo_legado character varying(80),
    detalle jsonb DEFAULT '{}'::jsonb NOT NULL,
    resuelto boolean DEFAULT false NOT NULL,
    resuelto_por uuid,
    resuelto_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT migracion_conflicto_categoria_chk CHECK (((categoria)::text = ANY (ARRAY[('DNI_DUPLICADO'::character varying)::text, ('PERSONA_HOMONIMA'::character varying)::text, ('MEMBRESIA_SIN_MATCH'::character varying)::text, ('ORGANIZACION_SIN_ACTOR'::character varying)::text, ('CASO_CODIGO_SERIE_ANTERIOR'::character varying)::text, ('ALERTA_INEXISTENTE'::character varying)::text, ('ESPECIE_NOMBRE_CIENTIFICO_DIVERGENTE'::character varying)::text, ('HITO_SIN_COMPROMISO'::character varying)::text, ('PARTICIPANTE_SIN_CAPACITACION'::character varying)::text, ('TERRITORIO_NO_RESUELTO'::character varying)::text])))
);


--
-- Name: TABLE migracion_conflicto; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON TABLE core.migracion_conflicto IS 'Conflicto detectado al cargar los datos del sistema anterior, con su hoja y fila de origen y el estado de resolución.';


--
-- Name: COLUMN migracion_conflicto.id; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.migracion_conflicto.id IS 'Identificador interno de la fila';


--
-- Name: COLUMN migracion_conflicto.fase; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.migracion_conflicto.fase IS 'Número de la fase del cargador en la que se detectó el conflicto';


--
-- Name: COLUMN migracion_conflicto.categoria; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.migracion_conflicto.categoria IS 'Tipo de conflicto detectado, como DNI duplicado o membresía sin coincidencia';


--
-- Name: COLUMN migracion_conflicto.hoja_legado; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.migracion_conflicto.hoja_legado IS 'Hoja del libro original donde se originó el conflicto';


--
-- Name: COLUMN migracion_conflicto.fila_legado; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.migracion_conflicto.fila_legado IS 'Número de fila dentro de la hoja de origen del conflicto';


--
-- Name: COLUMN migracion_conflicto.codigo_legado; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.migracion_conflicto.codigo_legado IS 'Código del registro de origen, conservado para poder rastrearlo';


--
-- Name: COLUMN migracion_conflicto.detalle; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.migracion_conflicto.detalle IS 'Datos del conflicto en formato libre, con los valores que no se pudieron conciliar';


--
-- Name: COLUMN migracion_conflicto.resuelto; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.migracion_conflicto.resuelto IS 'Indica si el conflicto ya fue revisado y dado por resuelto';


--
-- Name: COLUMN migracion_conflicto.resuelto_por; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.migracion_conflicto.resuelto_por IS 'Usuario que dio por resuelto el conflicto';


