-- Name: COLUMN migracion_conflicto.resuelto_at; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.migracion_conflicto.resuelto_at IS 'Momento en que se resolvió el conflicto';


--
-- Name: COLUMN migracion_conflicto.created_at; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.migracion_conflicto.created_at IS 'Momento en que se creó el registro';


