--
-- Name: normativas; Type: TABLE; Schema: core; Owner: -
--

CREATE TABLE core.normativas (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    codigo character varying(60),
    titulo character varying(255) NOT NULL,
    tipo_norma character varying(40) DEFAULT 'Otra'::character varying NOT NULL,
    ambito character varying(20) DEFAULT 'nacional'::character varying NOT NULL,
    entidad_emisora character varying(200),
    fecha_publicacion date,
    url character varying(500),
    resumen text,
    origen_dato character varying(20) DEFAULT 'MANUAL'::character varying NOT NULL,
    nivel_clasificacion smallint DEFAULT 1 NOT NULL,
    anulado_en timestamp with time zone,
    motivo_anulacion text,
    anulado_por uuid,
    anulacion_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_by uuid,
    CONSTRAINT normativas_ambito_check CHECK (((ambito)::text = ANY ((ARRAY['nacional'::character varying, 'regional'::character varying, 'local'::character varying, 'sectorial'::character varying])::text[]))),
    CONSTRAINT normativas_origen_dato_check CHECK (((origen_dato)::text = ANY ((ARRAY['MANUAL'::character varying, 'KAG'::character varying, 'WORKFLOW'::character varying, 'AVISA_HISTORICO'::character varying, 'WHATSAPP'::character varying])::text[]))),
    CONSTRAINT normativas_tipo_norma_check CHECK (((tipo_norma)::text = ANY ((ARRAY['Ley'::character varying, 'Ley Orgánica'::character varying, 'Decreto Supremo'::character varying, 'Decreto Legislativo'::character varying, 'Decreto de Urgencia'::character varying, 'Resolución Ministerial'::character varying, 'Resolución Directoral'::character varying, 'Resolución Jefatural'::character varying, 'Ordenanza'::character varying, 'Acuerdo'::character varying, 'Directiva'::character varying, 'Convenio'::character varying, 'Otra'::character varying])::text[])))
);

ALTER TABLE ONLY core.normativas FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE normativas; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON TABLE core.normativas IS 'Marco normativo para el árbol del RAG. Incluye leyes, decretos, resoluciones, ordenanzas y convenios, con ámbito y entidad emisora.';


--
