-- Name: COLUMN normativas.nivel_clasificacion; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.normativas.nivel_clasificacion IS 'Nivel de acceso (1 público … 3 restringido). Por defecto 1: la normativa es pública.';


