-- Name: COLUMN outbox_integracion.estado_id; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.outbox_integracion.estado_id IS 'Estado del envío según el catálogo de estados de integración';


--
-- Name: COLUMN outbox_integracion.intentos; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.outbox_integracion.intentos IS 'Cantidad de intentos de envío realizados hasta el momento';


--
-- Name: COLUMN outbox_integracion.ultimo_error; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.outbox_integracion.ultimo_error IS 'Mensaje del último fallo ocurrido al intentar el envío';


