-- Name: COLUMN outbox_integracion.created_at; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.outbox_integracion.created_at IS 'Momento en que se creó el registro';


--
-- Name: output_contracts; Type: TABLE; Schema: core; Owner: -
--

CREATE TABLE core.output_contracts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    query_id uuid NOT NULL,
