    created_at timestamp with time zone DEFAULT now() NOT NULL,
    policy_snapshot_id uuid,
    chat_commit_id uuid,
    CONSTRAINT output_contracts_formato_check CHECK (((formato)::text = ANY (ARRAY[('office'::character varying)::text, ('minister'::character varying)::text])))
);

ALTER TABLE ONLY core.output_contracts FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE output_contracts; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON TABLE core.output_contracts IS 'Contrato de cada salida generada, con su formato, la consulta que la originó y el commit y snapshot que la respaldan.';


--
-- Name: COLUMN output_contracts.id; Type: COMMENT; Schema: core; Owner: -
--

