--
-- Name: permiso_aprobacion; Type: TABLE; Schema: core; Owner: -
--

CREATE TABLE core.permiso_aprobacion (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    usuario_id uuid NOT NULL,
    objeto character varying(60) NOT NULL,
    vigente_desde date DEFAULT CURRENT_DATE NOT NULL,
    vigente_hasta date,
    otorgado_por uuid,
    CONSTRAINT permiso_aprobacion_check CHECK (((vigente_hasta IS NULL) OR (vigente_hasta >= vigente_desde)))
);

ALTER TABLE ONLY core.permiso_aprobacion FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE permiso_aprobacion; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON TABLE core.permiso_aprobacion IS 'Autorización temporal que habilita a un usuario a aprobar un objeto determinado, con su vigencia y quién la otorgó. Desde el parche 22 tiene consumidor: core.puede_aprobar() la consulta para la suplencia del aprobador y core.vw_permiso_aprobacion la expone a la pantalla de administración. Una fila aquí no concede un rol: solo habilita a esa persona para ese objeto mientras la vigencia esté abierta. Vacía significa que no hay suplencia designada';


--
-- Name: COLUMN permiso_aprobacion.id; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.permiso_aprobacion.id IS 'Identificador interno de la fila';


--
