    desde date DEFAULT CURRENT_DATE NOT NULL,
    hasta date,
    activo boolean DEFAULT true NOT NULL,
    creado_en timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_privilegio_motivo CHECK ((length(btrim(motivo)) >= 10)),
    CONSTRAINT ck_privilegio_vigencia CHECK (((hasta IS NULL) OR (hasta >= desde)))
);


--
-- Name: TABLE privilegio_usuario; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON TABLE core.privilegio_usuario IS 'Concesiones nominales y con fecha de caducidad. Una persona puede tener el privilegio y perderlo sin cambiar de rol. Origen: RA-07.';


--
-- Name: COLUMN privilegio_usuario.id; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.privilegio_usuario.id IS 'Identificador interno de la fila';


--
-- Name: COLUMN privilegio_usuario.usuario_id; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.privilegio_usuario.usuario_id IS 'Persona que recibe el privilegio, según core.usuarios.';


--
-- Name: COLUMN privilegio_usuario.privilegio_id; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.privilegio_usuario.privilegio_id IS 'Privilegio concedido, según core.cat_privilegio.';


--
-- Name: COLUMN privilegio_usuario.motivo; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.privilegio_usuario.motivo IS 'Por qué se concede. Obligatorio: una concesión sin motivo no es auditable ante la ANPDP.';


--
-- Name: COLUMN privilegio_usuario.otorgado_por_usuario_id; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.privilegio_usuario.otorgado_por_usuario_id IS 'Persona que autorizó la concesión; queda registrada para la auditoría.';


--
-- Name: COLUMN privilegio_usuario.desde; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.privilegio_usuario.desde IS 'Fecha desde la que rige la concesión.';


--
-- Name: COLUMN privilegio_usuario.hasta; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.privilegio_usuario.hasta IS 'Fin de vigencia. NULL = sin fecha de fin, revisable en cada auditoría.';


--
-- Name: COLUMN privilegio_usuario.activo; Type: COMMENT; Schema: core; Owner: -
--

