-- Name: roles; Type: TABLE; Schema: core; Owner: -
--

CREATE TABLE core.roles (
    id smallint NOT NULL,
    codigo character varying(30) NOT NULL,
    max_clasificacion smallint NOT NULL,
    puede_crear boolean DEFAULT false NOT NULL,
    puede_editar boolean DEFAULT false NOT NULL,
    puede_eliminar boolean DEFAULT false NOT NULL,
    CONSTRAINT ck_roles_capacidades CHECK (((NOT puede_eliminar) OR puede_editar))
);

ALTER TABLE ONLY core.roles FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE roles; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON TABLE core.roles IS 'Rol de acceso del sistema con su nivel máximo de clasificación, base del control de permisos por perfil.';


--
-- Name: COLUMN roles.id; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.roles.id IS 'Identificador interno del rol de acceso';


--
-- Name: COLUMN roles.codigo; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.roles.codigo IS 'Código corto del rol, usado en la asignación de permisos';


--
-- Name: COLUMN roles.max_clasificacion; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.roles.max_clasificacion IS 'Nivel máximo de clasificación que el rol puede consultar';


--
-- Name: COLUMN roles.puede_crear; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.roles.puede_crear IS 'Autoriza INSERT en las tablas con RLS por clasificación. El nivel máximo sigue limitando qué filas (max_clasificacion).';


--
-- Name: COLUMN roles.puede_editar; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.roles.puede_editar IS 'Autoriza UPDATE en las tablas con RLS por clasificación.';


--
-- Name: COLUMN roles.puede_eliminar; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.roles.puede_eliminar IS 'Autoriza DELETE. Nunca se concede sin puede_editar (ver ck_roles_capacidades). El borrado de registros de conflictividad es destructivo y queda reservado a los roles que administran el dato.';


--
-- Name: secuencia_codigo; Type: TABLE; Schema: core; Owner: -
--

CREATE TABLE core.secuencia_codigo (
    ambito text NOT NULL,
    ultimo bigint DEFAULT 0 NOT NULL,
    actualizado_en timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT secuencia_codigo_ultimo_check CHECK ((ultimo >= 0))
);


--
-- Name: TABLE secuencia_codigo; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON TABLE core.secuencia_codigo IS 'Contadores monótonos por ámbito. Un número jamás se reutiliza.';


--
-- Name: sugerencia; Type: TABLE; Schema: core; Owner: -
--

CREATE TABLE core.sugerencia (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    codigo character varying(40) NOT NULL,
    entidad_tipo character varying(20) NOT NULL,
    caso_id uuid,
    region_id integer,
    provincia_id integer,
    distrito_id integer,
    territorio_texto character varying(200),
    tipo_id smallint DEFAULT 6 NOT NULL,
    titulo character varying(240) NOT NULL,
    detalle text,
    destinatario character varying(200),
    unidad_responsable_id integer,
    prioridad_id smallint DEFAULT 2 NOT NULL,
    estado_id smallint DEFAULT 1 NOT NULL,
    responsable_usuario_id uuid,
    responsable_texto character varying(160),
    sustento text,
    sustento_uri character varying(500),
    origen character varying(20) DEFAULT 'persona'::character varying NOT NULL,
    confianza numeric(5,2),
    decision_nota text,
    motivo_rechazo text,
    decidido_por uuid,
    decidido_en timestamp with time zone,
    vence_en date,
    nivel_clasificacion smallint DEFAULT 2 NOT NULL,
    anulado_en timestamp with time zone,
    anulado_por uuid,
    motivo_anulacion text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_by uuid,
    CONSTRAINT chk_sugerencia_entidad CHECK (((((entidad_tipo)::text = 'caso'::text) AND (caso_id IS NOT NULL)) OR (((entidad_tipo)::text = 'territorio'::text) AND ((region_id IS NOT NULL) OR (provincia_id IS NOT NULL) OR (distrito_id IS NOT NULL) OR (territorio_texto IS NOT NULL))))),
    CONSTRAINT sugerencia_confianza_check CHECK (((confianza IS NULL) OR ((confianza >= (0)::numeric) AND (confianza <= (100)::numeric)))),
    CONSTRAINT sugerencia_entidad_tipo_check CHECK (((entidad_tipo)::text = ANY ((ARRAY['caso'::character varying, 'territorio'::character varying])::text[]))),
    CONSTRAINT sugerencia_origen_check CHECK (((origen)::text = ANY ((ARRAY['persona'::character varying, 'agente'::character varying, 'mesa'::character varying, 'sistema'::character varying])::text[])))
);

ALTER TABLE ONLY core.sugerencia FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE sugerencia; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON TABLE core.sugerencia IS 'Sugerencias y recomendaciones de intervención por caso o territorio: qué se sugiere, a quién, con qué prioridad, en qué estado, quién la atiende y con qué sustento. La decisión siempre es humana; `decidido_por` y `decidido_en` la registran.';


--
-- Name: COLUMN sugerencia.entidad_tipo; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.sugerencia.entidad_tipo IS 'caso = la sugerencia apunta a core.casos; territorio = apunta a región/provincia/distrito o a territorio_texto.';


--
-- Name: COLUMN sugerencia.sustento; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.sugerencia.sustento IS 'Sustento declarado de la sugerencia (qué la respalda). NULL = sin dato.';


--
-- Name: COLUMN sugerencia.confianza; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.sugerencia.confianza IS 'Confianza declarada de la sugerencia, 0–100. NULL = sin dato; no se estima.';


--
-- Name: COLUMN sugerencia.decidido_por; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.sugerencia.decidido_por IS 'Usuario que tomó la decisión. Obligatorio para los estados decididos; nunca lo completa el sistema.';


