--
-- Name: tablero_tarjeta; Type: TABLE; Schema: core; Owner: -
--

CREATE TABLE core.tablero_tarjeta (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    entidad_tipo character varying(20) NOT NULL,
    entidad_id uuid NOT NULL,
    columna character varying(20) DEFAULT 'backlog'::character varying NOT NULL,
    asignacion_texto character varying(160),
    responsable_usuario_id uuid,
    responsable_texto character varying(160),
    fecha_limite date,
    pospuesto_hasta date,
    motivo_posposicion text,
    orden integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_by uuid,
    CONSTRAINT tablero_tarjeta_columna_check CHECK (((columna)::text = ANY ((ARRAY['backlog'::character varying, 'en_curso'::character varying, 'en_espera'::character varying, 'hecho'::character varying])::text[]))),
    CONSTRAINT tablero_tarjeta_entidad_tipo_check CHECK (((entidad_tipo)::text = ANY ((ARRAY['alerta'::character varying, 'compromiso'::character varying, 'demanda'::character varying, 'caso'::character varying])::text[])))
);


--
-- Name: TABLE tablero_tarjeta; Type: COMMENT; Schema: core; Owner: -
