--
-- Name: vw_actor_territorio; Type: VIEW; Schema: core; Owner: -
--

CREATE VIEW core.vw_actor_territorio AS
 SELECT a.actor_uid,
    a.nombre_actual,
    a.nivel_identificacion_id,
    ni.codigo AS nivel_identificacion,
    a.region_id,
    r.nombre AS region,
    a.distrito_id,
    d.nombre AS distrito,
    p.nombre AS provincia,
    ( SELECT count(*) AS count
           FROM territorio.lugar_actores la
          WHERE ((la.actor_uid = a.actor_uid) AND ((la.valid_to IS NULL) OR (la.valid_to >= CURRENT_DATE)))) AS lugares_vigentes
   FROM ((((core.actores a
     LEFT JOIN core.cat_nivel_identificacion ni ON ((ni.id = a.nivel_identificacion_id)))
     LEFT JOIN core.regiones r ON ((r.id = a.region_id)))
     LEFT JOIN core.distritos d ON ((d.id = a.distrito_id)))
     LEFT JOIN core.provincias p ON ((p.id = d.provincia_id)));


--
-- Name: VIEW vw_actor_territorio; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON VIEW core.vw_actor_territorio IS 'Territorio de cada actor en una sola lectura, con la precisión real del dato: departamento cuando sólo hay departamento, y distrito sólo cuando existe.';


--
-- Name: vw_agregacion_compromiso_externo; Type: VIEW; Schema: core; Owner: -
--

CREATE VIEW core.vw_agregacion_compromiso_externo AS
 SELECT sistema_destino,
    entidad_destino_ref,
    count(*) AS hitos_locales_asociados,
    array_agg(DISTINCT entidad_origen_tipo ORDER BY entidad_origen_tipo) AS tipos_origen,
    min(ultima_sincronizacion) AS primera_sincronizacion,
    max(ultima_sincronizacion) AS ultima_sincronizacion,
    bool_and(((estado)::text = 'activa'::text)) AS todos_activos
   FROM core.integraciones
  WHERE (entidad_destino_ref IS NOT NULL)
  GROUP BY sistema_destino, entidad_destino_ref;


--
-- Name: vw_alerta_estado; Type: VIEW; Schema: core; Owner: -
--

CREATE VIEW core.vw_alerta_estado AS
 SELECT a.id AS alerta_id,
    a.codigo_alerta,
    a.titulo,
    a.prioridad_id,
    a.nivel_alerta_id,
    a.fecha_reporte,
    pi.id AS proceso_id,
    pi.orden AS paso,
    d.nombre AS paso_nombre,
    pi.estado_id,
    e.codigo AS estado_codigo,
    e.nombre AS estado_nombre,
    e.es_final,
    pi.ocurrido_en AS estado_desde,
    a.es_validado_humano,
    a.fecha_validacion,
    a.fecha_remision,
    a.aprobada_por,
    a.aprobada_en,
    a.visibilidad,
    a.validada_por,
    ( SELECT count(*) AS count
           FROM core.alerta_destinatario d2
          WHERE (d2.alerta_id = a.id)) AS destinatarios
   FROM (((core.alertas_tempranas a
     LEFT JOIN LATERAL ( SELECT p.id,
            p.tipo_origen,
            p.caso_id,
            p.codigo_caso_legado,
            p.alerta_id,
            p.codigo_reporte,
            p.flujo_definicion_id,
            p.estado_id,
            p.usuario_id,
            p.codigo_responsable_legado,
            p.ocurrido_en,
            p.finalizado_en,
            p.orden,
            p.nota,
            p.codigo_legado,
            p.fila_legado,
            p.created_at,
            p.updated_at,
            p.created_by,
            p.updated_by,
            p.nivel_clasificacion
           FROM core.proceso_instancia p
          WHERE (((p.tipo_origen)::text = 'alerta'::text) AND (p.alerta_id = a.id))
          ORDER BY p.orden DESC, p.ocurrido_en DESC NULLS LAST
         LIMIT 1) pi ON (true))
     LEFT JOIN core.flujo_estado e ON ((e.id = pi.estado_id)))
     LEFT JOIN core.flujo_definicion d ON ((d.id = pi.flujo_definicion_id)));


--
-- Name: VIEW vw_alerta_estado; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON VIEW core.vw_alerta_estado IS 'Estado consolidado de cada alerta: su paso y estado vigentes, sus dos firmas de aprobación y su visibilidad. Desde el parche 23 expone también el autor de la validación previa (validada_por) y cuántos destinatarios nombrados tiene (destinatarios), que es lo que la pantalla necesita para saber si la alerta puede publicarse como sectorial';


--
-- Name: COLUMN vw_alerta_estado.validada_por; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.vw_alerta_estado.validada_por IS 'Autor de la validación previa del Sectorista; primera de las dos firmas de G21';


--
-- Name: COLUMN vw_alerta_estado.destinatarios; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON COLUMN core.vw_alerta_estado.destinatarios IS 'Número de destinatarios nombrados en core.alerta_destinatario. Una alerta con visibilidad sectorial necesita al menos uno';


--
-- Name: vw_permiso_aprobacion; Type: VIEW; Schema: core; Owner: -
--

CREATE VIEW core.vw_permiso_aprobacion WITH (security_invoker='true') AS
 SELECT pa.id,
    pa.usuario_id,
    u.nombre AS usuario_nombre,
    u.codigo_legado AS usuario_codigo_legado,
    pa.objeto,
    pa.vigente_desde,
    pa.vigente_hasta,
    ((pa.vigente_desde <= CURRENT_DATE) AND ((pa.vigente_hasta IS NULL) OR (pa.vigente_hasta >= CURRENT_DATE))) AS vigente,
    pa.otorgado_por,
    o.nombre AS otorgado_por_nombre
   FROM ((core.permiso_aprobacion pa
     JOIN core.usuarios u ON ((u.id = pa.usuario_id)))
     LEFT JOIN core.usuarios o ON ((o.id = pa.otorgado_por)));


--
-- Name: VIEW vw_permiso_aprobacion; Type: COMMENT; Schema: core; Owner: -
--

COMMENT ON VIEW core.vw_permiso_aprobacion IS 'Suplencias de aprobación con nombre de la persona habilitada, objeto, vigencia y una marca vigente calculada al consultar. Es la lectura de la pantalla de administración de membresías; no cambia permisos, solo los muestra. Hoy devuelve 0 filas porque no hay suplente designado';


