--

CREATE TABLE ctx.observaciones (
    id bigint NOT NULL,
    fecha date NOT NULL,
    variable_id smallint NOT NULL,
    fuente_id smallint NOT NULL,
    valor numeric(18,4) NOT NULL,
    especie_id smallint,
    region_id integer,
    provincia_id integer,
    distrito_id integer,
    lugar_id uuid,
    zona_maritima_id smallint,
    ingerido_en timestamp with time zone DEFAULT now() NOT NULL,
    metadata jsonb,
    CONSTRAINT observaciones_check CHECK ((num_nonnulls(region_id, provincia_id, distrito_id, lugar_id, zona_maritima_id) <= 1))
)
PARTITION BY RANGE (fecha);


--
-- Name: TABLE observaciones; Type: COMMENT; Schema: ctx; Owner: -
