-- Name: snapshot; Type: TABLE; Schema: ctx; Owner: -
--

CREATE TABLE ctx.snapshot (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    caso_id uuid NOT NULL,
    fecha date DEFAULT CURRENT_DATE NOT NULL,
    contenido jsonb NOT NULL,
    hash character(64) NOT NULL,
    creado_por uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE snapshot; Type: COMMENT; Schema: ctx; Owner: -
--

COMMENT ON TABLE ctx.snapshot IS 'Foto del contexto vigente de un caso en una fecha, con su hash, que respalda lo que el sistema sabía en ese momento.';


--
-- Name: COLUMN snapshot.id; Type: COMMENT; Schema: ctx; Owner: -
--

COMMENT ON COLUMN ctx.snapshot.id IS 'Identificador interno de la fila';


--
-- Name: COLUMN snapshot.caso_id; Type: COMMENT; Schema: ctx; Owner: -
--

COMMENT ON COLUMN ctx.snapshot.caso_id IS 'Caso cuyo contexto se fotografía en este snapshot';


--
-- Name: COLUMN snapshot.fecha; Type: COMMENT; Schema: ctx; Owner: -
--

COMMENT ON COLUMN ctx.snapshot.fecha IS 'Fecha a la que corresponde el contexto capturado';


--
-- Name: COLUMN snapshot.contenido; Type: COMMENT; Schema: ctx; Owner: -
--

COMMENT ON COLUMN ctx.snapshot.contenido IS 'Contexto vigente del caso, congelado como documento JSON';


--
-- Name: COLUMN snapshot.hash; Type: COMMENT; Schema: ctx; Owner: -
--

COMMENT ON COLUMN ctx.snapshot.hash IS 'Huella del contenido, para comprobar que la foto no fue alterada';


--
-- Name: COLUMN snapshot.creado_por; Type: COMMENT; Schema: ctx; Owner: -
--

COMMENT ON COLUMN ctx.snapshot.creado_por IS 'Usuario o proceso que generó el snapshot de contexto';


--
-- Name: COLUMN snapshot.created_at; Type: COMMENT; Schema: ctx; Owner: -
--

COMMENT ON COLUMN ctx.snapshot.created_at IS 'Momento en que se creó el registro';


