-- Name: trabajo_recoleccion; Type: TABLE; Schema: ctx; Owner: -
--

CREATE TABLE ctx.trabajo_recoleccion (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    variable_id smallint,
    indicador_id uuid,
    herramienta_id smallint NOT NULL,
    estado character varying(10) DEFAULT 'activo'::character varying NOT NULL,
    ultima_ejecucion timestamp with time zone,
    error text,
    CONSTRAINT trabajo_recoleccion_check CHECK (((variable_id IS NOT NULL) OR (indicador_id IS NOT NULL))),
    CONSTRAINT trabajo_recoleccion_estado_check CHECK (((estado)::text = ANY (ARRAY[('activo'::character varying)::text, ('pausado'::character varying)::text, ('error'::character varying)::text])))
);


--
-- Name: TABLE trabajo_recoleccion; Type: COMMENT; Schema: ctx; Owner: -
--

COMMENT ON TABLE ctx.trabajo_recoleccion IS 'Trabajo programado de recolección de una variable o indicador, con su herramienta, estado y último error registrado.';


--
-- Name: COLUMN trabajo_recoleccion.id; Type: COMMENT; Schema: ctx; Owner: -
--

COMMENT ON COLUMN ctx.trabajo_recoleccion.id IS 'Identificador interno de la fila';


