-- Name: COLUMN trabajo_recoleccion.indicador_id; Type: COMMENT; Schema: ctx; Owner: -
--

COMMENT ON COLUMN ctx.trabajo_recoleccion.indicador_id IS 'Indicador para el que se recolecta la variable, cuando aplica';


--
-- Name: COLUMN trabajo_recoleccion.herramienta_id; Type: COMMENT; Schema: ctx; Owner: -
--

COMMENT ON COLUMN ctx.trabajo_recoleccion.herramienta_id IS 'Herramienta con la que se ejecuta la recolección';


--
-- Name: COLUMN trabajo_recoleccion.estado; Type: COMMENT; Schema: ctx; Owner: -
--

COMMENT ON COLUMN ctx.trabajo_recoleccion.estado IS 'Situación del trabajo de recolección, por defecto activo';


--
-- Name: COLUMN trabajo_recoleccion.ultima_ejecucion; Type: COMMENT; Schema: ctx; Owner: -
--

COMMENT ON COLUMN ctx.trabajo_recoleccion.ultima_ejecucion IS 'Momento de la última vez que se ejecutó el trabajo';


--
-- Name: COLUMN trabajo_recoleccion.error; Type: COMMENT; Schema: ctx; Owner: -
--

COMMENT ON COLUMN ctx.trabajo_recoleccion.error IS 'Mensaje del último error ocurrido durante la recolección';


