    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tipo_artefacto_id uuid NOT NULL,
    codigo character varying(60) NOT NULL,
    tipo_regla character varying(12) NOT NULL,
    estado_desde_id smallint,
    estado_hasta_id smallint,
    condicion_sql text,
    mensaje_error text NOT NULL,
    nivel_clasificacion smallint DEFAULT 2 NOT NULL,
    activo boolean DEFAULT true NOT NULL,
    version character varying(10) DEFAULT '1.0'::character varying NOT NULL,
    CONSTRAINT regla_negocio_tipo_regla_check CHECK (((tipo_regla)::text = ANY (ARRAY[('transicion'::character varying)::text, ('invariante'::character varying)::text, ('validacion'::character varying)::text, ('calculo'::character varying)::text, ('alerta'::character varying)::text])))
);


--
-- Name: TABLE regla_negocio; Type: COMMENT; Schema: domain; Owner: -
--

COMMENT ON TABLE domain.regla_negocio IS 'Regla que condiciona el paso de un artefacto entre estados, con su condición de evaluación y su mensaje de error.';


--
-- Name: COLUMN regla_negocio.id; Type: COMMENT; Schema: domain; Owner: -
--

COMMENT ON COLUMN domain.regla_negocio.id IS 'Identificador interno de la fila';


