--

COMMENT ON COLUMN domain.regla_negocio.codigo IS 'Código que identifica la regla dentro del catálogo de negocio';


--
-- Name: COLUMN regla_negocio.tipo_regla; Type: COMMENT; Schema: domain; Owner: -
--

COMMENT ON COLUMN domain.regla_negocio.tipo_regla IS 'Clase de la regla, como obligatoria, advertencia o bloqueo';


