-- Name: infraestructuras_puntos; Type: TABLE; Schema: gis; Owner: -
--

CREATE TABLE gis.infraestructuras_puntos (
    id text NOT NULL,
    tipo_registro text NOT NULL,
    nombre text,
    identi text,
    sede text,
    nombre_infraestructura text,
    direccion text,
    direccion_predio text,
    departamento text,
    provincia text,
    distrito text,
    ubigeo character varying(6),
    ubigeo_region character varying(2) GENERATED ALWAYS AS ("left"((ubigeo)::text, 2)) STORED,
    ubigeo_provincia character varying(4) GENERATED ALWAYS AS ("left"((ubigeo)::text, 4)) STORED,
    metodo_ubigeo text,
    latitud double precision,
    longitud double precision,
    coincide_coords boolean,
    codigo text,
    ambito text,
    tipo_derecho text,
    categoria_productiva text,
    categoria_codigo character varying(8),
    especie text,
    tipo_recurso text,
    nombre_recurso text,
    estado text,
    area_total_ha numeric(12,3),
    fecha_emision date,
    fecha_vigencia date,
    resolucion text,
    zona text,
    tipo_coord text,
    titular text,
    fid_origen integer,
    tipo_geometria text,
    otros jsonb,
    distrito_id integer,
    geom public.geometry(Point,4326),
    CONSTRAINT infraestructuras_puntos_tipo_registro_check CHECK ((tipo_registro = ANY (ARRAY['derecho_acuicola'::text, 'institucional'::text])))
);


--
-- Name: TABLE infraestructuras_puntos; Type: COMMENT; Schema: gis; Owner: -
--

COMMENT ON TABLE gis.infraestructuras_puntos IS 'Puntos de gis/Infraestructuras.kml. Mayoritariamente derechos acuícolas privados (tipo_registro = derecho_acuicola), no instalaciones de PRODUCE. Ver gis/derived/README.md para el diccionario completo.';


--
-- Name: COLUMN infraestructuras_puntos.tipo_registro; Type: COMMENT; Schema: gis; Owner: -
--

COMMENT ON COLUMN gis.infraestructuras_puntos.tipo_registro IS 'derecho_acuicola (13 229, reconocidos por codigo) o institucional (227, por identi).';


--
-- Name: COLUMN infraestructuras_puntos.nombre; Type: COMMENT; Schema: gis; Owner: -
--

COMMENT ON COLUMN gis.infraestructuras_puntos.nombre IS 'PII · <name> del placemark. En derechos y PNACP repite el titular.';


--
-- Name: COLUMN infraestructuras_puntos.identi; Type: COMMENT; Schema: gis; Owner: -
--

COMMENT ON COLUMN gis.infraestructuras_puntos.identi IS 'Institución dueña cuando el punto es una sede (ITP, SANIPES, IMARPE, DIREPRO, FONDEPES…). Conserva la errata "DPA -GORE" (1 fila): filtrar con identi LIKE ''DPA%''.';


--
-- Name: COLUMN infraestructuras_puntos.departamento; Type: COMMENT; Schema: gis; Owner: -
--

COMMENT ON COLUMN gis.infraestructuras_puntos.departamento IS 'Nombre oficial del ubigeo cuando se resolvió. El KML dice CALLAO; la provincia oficial es PROV. CONST. DEL CALLAO.';


--
-- Name: COLUMN infraestructuras_puntos.distrito; Type: COMMENT; Schema: gis; Owner: -
--

