--
-- Name: v_desembarcaderos; Type: VIEW; Schema: gis; Owner: -
--

CREATE VIEW gis.v_desembarcaderos AS
 SELECT id,
    identi,
    COALESCE(nombre_infraestructura, nombre) AS nombre,
    departamento,
    provincia,
    distrito,
    ubigeo,
    latitud,
    longitud,
    geom
   FROM gis.infraestructuras_puntos
  WHERE ((tipo_registro = 'institucional'::text) AND (identi ~~ 'DPA%'::text));


--
-- Name: VIEW v_desembarcaderos; Type: COMMENT; Schema: gis; Owner: -
--

COMMENT ON VIEW gis.v_desembarcaderos IS 'Puntos DPA - GORE (desembarcaderos artesanales). Incluye la fila con la errata "DPA -GORE".';


--
-- Name: v_infraestructuras_por_distrito; Type: VIEW; Schema: gis; Owner: -
--

CREATE VIEW gis.v_infraestructuras_por_distrito AS
 SELECT d.id AS distrito_id,
    (d.ubigeo)::text AS ubigeo,
    d.nombre AS distrito,
    p.nombre AS provincia,
    r.nombre AS departamento,
    count(*) FILTER (WHERE (i.tipo_registro = 'derecho_acuicola'::text)) AS derechos_acuicolas,
    count(*) FILTER (WHERE (i.tipo_registro = 'institucional'::text)) AS institucionales,
    count(*) AS total,
    COALESCE(sum(i.area_total_ha) FILTER (WHERE (i.tipo_registro = 'derecho_acuicola'::text)), (0)::numeric) AS area_otorgada_ha
   FROM (((gis.infraestructuras_puntos i
     JOIN core.distritos d ON ((d.id = i.distrito_id)))
     JOIN core.provincias p ON ((p.id = d.provincia_id)))
     JOIN core.regiones r ON ((r.id = p.region_id)))
  GROUP BY d.id, d.ubigeo, d.nombre, p.nombre, r.nombre;


--
-- Name: VIEW v_infraestructuras_por_distrito; Type: COMMENT; Schema: gis; Owner: -
--

COMMENT ON VIEW gis.v_infraestructuras_por_distrito IS 'Resumen por distrito de la capa GIS. Sólo cubre los ubigeos presentes en core.distritos.';


