    es_validado_humano boolean DEFAULT false NOT NULL,
    nivel_clasificacion smallint DEFAULT 2 NOT NULL,
    CONSTRAINT actor_profile_attribute_attribute_type_check CHECK (((attribute_type)::text = ANY (ARRAY[('interes_declarado'::character varying)::text, ('interes_real'::character varying)::text, ('necesidad_basica'::character varying)::text, ('limitacion_legal'::character varying)::text, ('limitacion_presupuestal'::character varying)::text, ('limitacion_politica'::character varying)::text, ('limitacion_cultural'::character varying)::text, ('estrategia_historica'::character varying)::text, ('capacidad'::character varying)::text]))),
    CONSTRAINT actor_profile_attribute_check CHECK (((valid_to IS NULL) OR (valid_to > valid_from))),
    CONSTRAINT actor_profile_attribute_confidence_check CHECK (((confidence >= (0)::numeric) AND (confidence <= (1)::numeric))),
    CONSTRAINT actor_profile_attribute_severity_check CHECK (((severity >= 1) AND (severity <= 5)))
);

