--
-- Name: clase; Type: TABLE; Schema: lex; Owner: -
--

CREATE TABLE lex.clase (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    corrida_id uuid NOT NULL,
    num smallint NOT NULL,
    pct_uce numeric(5,2),
    descripcion_analista text,
    CONSTRAINT clase_pct_uce_check CHECK (((pct_uce >= (0)::numeric) AND (pct_uce <= (100)::numeric)))
);


--
-- Name: TABLE clase; Type: COMMENT; Schema: lex; Owner: -
--

COMMENT ON TABLE lex.clase IS 'Clase de discurso obtenida en una corrida de análisis léxico, con su porcentaje de unidades de contexto clasificadas.';


--
-- Name: COLUMN clase.id; Type: COMMENT; Schema: lex; Owner: -
--

COMMENT ON COLUMN lex.clase.id IS 'Identificador interno de la fila';


--
-- Name: COLUMN clase.corrida_id; Type: COMMENT; Schema: lex; Owner: -
--

COMMENT ON COLUMN lex.clase.corrida_id IS 'Corrida léxica en la que se obtuvo la clase de discurso';


--
-- Name: COLUMN clase.num; Type: COMMENT; Schema: lex; Owner: -
--

COMMENT ON COLUMN lex.clase.num IS 'Número de la clase dentro de la corrida';


--
-- Name: COLUMN clase.pct_uce; Type: COMMENT; Schema: lex; Owner: -
--

COMMENT ON COLUMN lex.clase.pct_uce IS 'Porcentaje de unidades de contexto asignadas a la clase';


--
-- Name: COLUMN clase.descripcion_analista; Type: COMMENT; Schema: lex; Owner: -
--

COMMENT ON COLUMN lex.clase.descripcion_analista IS 'Descripción de la clase redactada por el analista';


--
-- Name: clase_termino; Type: TABLE; Schema: lex; Owner: -
--

CREATE TABLE lex.clase_termino (
    clase_id uuid NOT NULL,
