-- Name: corrida; Type: TABLE; Schema: lex; Owner: -
--

CREATE TABLE lex.corrida (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    corpus_id uuid NOT NULL,
    metodo character varying(15) NOT NULL,
    software character varying(60),
    version character varying(30),
    parametros jsonb DEFAULT '{}'::jsonb NOT NULL,
    semilla bigint,
    origen character varying(10) NOT NULL,
    archivo_hash character(64),
    plan_paso_id uuid,
    estado character varying(12) DEFAULT 'en_curso'::character varying NOT NULL,
    metricas jsonb DEFAULT '{}'::jsonb NOT NULL,
    nivel_clasificacion smallint DEFAULT 2 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT corrida_check CHECK ((((origen)::text = 'interno'::text) OR (archivo_hash IS NOT NULL))),
    CONSTRAINT corrida_estado_check CHECK (((estado)::text = ANY (ARRAY[('en_curso'::character varying)::text, ('completa'::character varying)::text, ('fallida'::character varying)::text, ('descartada'::character varying)::text]))),
    CONSTRAINT corrida_metodo_check CHECK (((metodo)::text = ANY (ARRAY[('frecuencias'::character varying)::text, ('coocurrencia'::character varying)::text, ('chd_reinert'::character varying)::text, ('diccionario'::character varying)::text, ('especificidades'::character varying)::text]))),
    CONSTRAINT corrida_origen_check CHECK (((origen)::text = ANY (ARRAY[('interno'::character varying)::text, ('importado'::character varying)::text])))
);

ALTER TABLE ONLY lex.corrida FORCE ROW LEVEL SECURITY;


