--
-- Name: vw_clases_publicables; Type: VIEW; Schema: lex; Owner: -
--

CREATE VIEW lex.vw_clases_publicables AS
 SELECT cl.id,
    cl.corrida_id,
    cl.num,
    cl.pct_uce,
    cl.descripcion_analista,
    (c.metricas ->> 'estabilidad'::text) AS estabilidad
   FROM (lex.clase cl
     JOIN lex.corrida c ON ((c.id = cl.corrida_id)))
  WHERE (((c.estado)::text = 'completa'::text) AND (c.metricas ? 'estabilidad'::text));


--
-- Name: model_card; Type: TABLE; Schema: model; Owner: -
--

CREATE TABLE model.model_card (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    codigo character varying(60) NOT NULL,
    version character varying(20) DEFAULT '1.0'::character varying NOT NULL,
    tipo_modelo character varying(20) NOT NULL,
    libreria_id uuid,
    aplicacion_id uuid,
    proposito text NOT NULL,
    datos_entrenamiento_hash character(64),
    variables_entrada jsonb DEFAULT '[]'::jsonb NOT NULL,
    variables_salida jsonb DEFAULT '[]'::jsonb NOT NULL,
    parametros jsonb DEFAULT '{}'::jsonb NOT NULL,
    metricas jsonb,
    limitaciones text,
    incertidumbre character varying(30),
    estado character varying(12) DEFAULT 'propuesto'::character varying NOT NULL,
    reviewer character varying(120),
    proximo_review date,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_model_card_activo_completo CHECK ((((estado)::text <> 'activo'::text) OR (libreria_id IS NOT NULL))),
    CONSTRAINT model_card_estado_check CHECK (((estado)::text = ANY (ARRAY[('propuesto'::character varying)::text, ('activo'::character varying)::text, ('en_revision'::character varying)::text, ('retirado'::character varying)::text]))),
    CONSTRAINT model_card_tipo_modelo_check CHECK (((tipo_modelo)::text = ANY (ARRAY[('clasificacion'::character varying)::text, ('regresion'::character varying)::text, ('serie_tiempo'::character varying)::text, ('did'::character varying)::text, ('glmm'::character varying)::text, ('regla'::character varying)::text, ('score_aditivo'::character varying)::text, ('llm'::character varying)::text, ('otro'::character varying)::text])))
);


