--
-- Name: ejecucion_nec; Type: TABLE; Schema: mype; Owner: -
--

CREATE TABLE mype.ejecucion_nec (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    nec_codigo character varying(60) NOT NULL,
    lote_codigo character varying(60) NOT NULL,
    mype_actor_uid uuid NOT NULL,
    monto_adjudicado_sol numeric(15,2) NOT NULL,
    fecha_adjudicacion date NOT NULL,
    fecha_entrega_pactada date,
    fecha_recepcion_cite date,
    fecha_conformidad date,
    fecha_pago_efectivo date,
    estado_pago character varying(20) DEFAULT 'pendiente'::character varying NOT NULL,
    dias_mora integer GENERATED ALWAYS AS (
CASE
    WHEN ((fecha_pago_efectivo IS NOT NULL) AND (fecha_entrega_pactada IS NOT NULL)) THEN GREATEST(0, (fecha_pago_efectivo - fecha_entrega_pactada))
    ELSE NULL::integer
END) STORED,
    fuente_documento_id uuid,
    nivel_clasificacion smallint DEFAULT 2 NOT NULL,
    tipo_artefacto_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ejecucion_nec_estado_pago_check CHECK (((estado_pago)::text = ANY (ARRAY[('pendiente'::character varying)::text, ('en_revision'::character varying)::text, ('aprobado'::character varying)::text, ('pagado'::character varying)::text, ('rechazado'::character varying)::text]))),
    CONSTRAINT ejecucion_nec_monto_adjudicado_sol_check CHECK ((monto_adjudicado_sol >= (0)::numeric))
);

ALTER TABLE ONLY mype.ejecucion_nec FORCE ROW LEVEL SECURITY;


