--
-- Name: inspeccion_cite; Type: VIEW; Schema: mype; Owner: -
--

CREATE VIEW mype.inspeccion_cite AS
 SELECT a.id,
    ((a.payload ->> 'ejecucion_id'::text))::uuid AS ejecucion_id,
    ((a.payload ->> 'fecha_inspeccion'::text))::date AS fecha_inspeccion,
    (a.payload ->> 'resultado'::text) AS resultado,
    (a.payload ->> 'observaciones'::text) AS observaciones,
    (a.payload ->> 'inspector'::text) AS inspector,
    a.nivel_clasificacion,
    a.created_at
   FROM (domain.artefacto a
     JOIN domain.tipo_artefacto t ON ((t.id = a.tipo_id)))
  WHERE (((t.codigo)::text = 'inspeccion_cite'::text) AND (a.superseded_at IS NULL));


--
-- Name: mv_concentracion_lotes; Type: MATERIALIZED VIEW; Schema: mype; Owner: -
--

CREATE MATERIALIZED VIEW mype.mv_concentracion_lotes AS
 WITH lote AS (
         SELECT (date_trunc('month'::text, (ejecucion_nec.fecha_adjudicacion)::timestamp with time zone))::date AS periodo,
            ejecucion_nec.nec_codigo,
            ejecucion_nec.mype_actor_uid,
            sum(ejecucion_nec.monto_adjudicado_sol) AS monto_mype
           FROM mype.ejecucion_nec
          GROUP BY ((date_trunc('month'::text, (ejecucion_nec.fecha_adjudicacion)::timestamp with time zone))::date), ejecucion_nec.nec_codigo, ejecucion_nec.mype_actor_uid
        ), total AS (
         SELECT lote.periodo,
            lote.nec_codigo,
            sum(lote.monto_mype) AS monto_total,
            count(*) AS numero_mypes
           FROM lote
          GROUP BY lote.periodo, lote.nec_codigo
        )
 SELECT l.periodo,
    l.nec_codigo,
    t.numero_mypes,
    ( SELECT count(*) AS count
           FROM mype.ejecucion_nec e
          WHERE (((date_trunc('month'::text, (e.fecha_adjudicacion)::timestamp with time zone))::date = l.periodo) AND ((e.nec_codigo)::text = (l.nec_codigo)::text))) AS numero_lotes,
    sum(power((l.monto_mype / NULLIF(t.monto_total, (0)::numeric)), (2)::numeric)) AS hhi,
    jsonb_agg(jsonb_build_object('mype_actor_uid', l.mype_actor_uid, 'monto', l.monto_mype) ORDER BY l.monto_mype DESC) AS top_mypes_json
   FROM (lote l
     JOIN total t ON (((t.periodo = l.periodo) AND ((t.nec_codigo)::text = (l.nec_codigo)::text))))
  GROUP BY l.periodo, l.nec_codigo, t.numero_mypes, t.monto_total
  WITH NO DATA;


--
-- Name: v_ejecucion_nec_mora_vigente; Type: VIEW; Schema: mype; Owner: -
--

CREATE VIEW mype.v_ejecucion_nec_mora_vigente WITH (security_invoker='true') AS
 SELECT id,
    nec_codigo,
    lote_codigo,
    mype_actor_uid,
    monto_adjudicado_sol,
    fecha_adjudicacion,
    fecha_entrega_pactada,
    fecha_recepcion_cite,
    fecha_conformidad,
    fecha_pago_efectivo,
    estado_pago,
    dias_mora,
    fuente_documento_id,
    nivel_clasificacion,
    tipo_artefacto_id,
    created_at,
    updated_at,
    COALESCE(dias_mora,
        CASE
            WHEN ((fecha_entrega_pactada IS NOT NULL) AND (fecha_pago_efectivo IS NULL)) THEN GREATEST(0, (CURRENT_DATE - fecha_entrega_pactada))
            ELSE NULL::integer
        END) AS dias_mora_vigente
   FROM mype.ejecucion_nec;


--
-- Name: cuota_cites_especie; Type: VIEW; Schema: pesca; Owner: -
--

CREATE VIEW pesca.cuota_cites_especie AS
 SELECT a.id,
    a.sujeto_especie_id AS especie_id,
    ((a.payload ->> 'anio'::text))::integer AS anio,
    ((a.payload ->> 'cuota_total_kg'::text))::numeric AS cuota_total_kg,
    COALESCE(((a.payload ->> 'cuota_consumida_kg'::text))::numeric, (0)::numeric) AS cuota_consumida_kg,
    COALESCE((a.payload ->> 'estado'::text), 'vigente'::text) AS estado,
    a.sujeto_documento_id AS fuente_documento_id
   FROM (domain.artefacto a
     JOIN domain.tipo_artefacto t ON ((t.id = a.tipo_id)))
  WHERE (((t.codigo)::text = 'cites_cuota'::text) AND (a.superseded_at IS NULL));


