    fecha_solicitud timestamp with time zone NOT NULL,
    fecha_dictamen_imarpe timestamp with time zone,
    fecha_emision_permiso timestamp with time zone,
    estado_permiso character varying(20) DEFAULT 'solicitado'::character varying NOT NULL,
    trazabilidad_qr_validada boolean DEFAULT false NOT NULL,
    fuente_documento_id uuid,
    nivel_clasificacion smallint DEFAULT 2 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    tipo_artefacto_id uuid NOT NULL,
    CONSTRAINT licencia_cites_denp_check CHECK (((volumen_autorizado_denp_kg IS NULL) OR (volumen_solicitado_kg IS NULL) OR (volumen_autorizado_denp_kg <= volumen_solicitado_kg))),
    CONSTRAINT licencia_cites_denp_check1 CHECK ((((estado_permiso)::text <> 'emitido'::text) OR (fecha_emision_permiso IS NOT NULL))),
    CONSTRAINT licencia_cites_denp_estado_permiso_check CHECK (((estado_permiso)::text = ANY (ARRAY[('solicitado'::character varying)::text, ('dictaminado'::character varying)::text, ('emitido'::character varying)::text, ('rechazado'::character varying)::text, ('vencido'::character varying)::text]))),
    CONSTRAINT licencia_cites_denp_volumen_autorizado_denp_kg_check CHECK (((volumen_autorizado_denp_kg IS NULL) OR (volumen_autorizado_denp_kg >= (0)::numeric))),
    CONSTRAINT licencia_cites_denp_volumen_solicitado_kg_check CHECK (((volumen_solicitado_kg IS NULL) OR (volumen_solicitado_kg >= (0)::numeric)))
);

