    CONSTRAINT registro_parametrico_estado_check CHECK (((estado)::text = ANY (ARRAY[('piloto'::character varying)::text, ('activo'::character varying)::text, ('vencido'::character varying)::text, ('suspendido'::character varying)::text]))),
    CONSTRAINT registro_parametrico_monto_maximo_sol_check CHECK (((monto_maximo_sol IS NULL) OR (monto_maximo_sol >= (0)::numeric)))
);

ALTER TABLE ONLY proteccion.registro_parametrico FORCE ROW LEVEL SECURITY;


