-- Name: COLUMN base_legal_tratamiento.articulo; Type: COMMENT; Schema: ref; Owner: -
--

COMMENT ON COLUMN ref.base_legal_tratamiento.articulo IS 'Artículo o inciso de la norma que sirve de sustento';


