--
-- Name: nivel_identificacion; Type: VIEW; Schema: ref; Owner: -
--

CREATE VIEW ref.nivel_identificacion AS
 SELECT id,
    codigo,
    descripcion
   FROM core.cat_nivel_identificacion;


--
-- Name: VIEW nivel_identificacion; Type: COMMENT; Schema: ref; Owner: -
--

COMMENT ON VIEW ref.nivel_identificacion IS 'Alias de core.cat_nivel_identificacion con el nombre que usa el plan del MVP. Una sola fuente de datos, dos nombres válidos.';


--
-- Name: vw_base_legal_fuente; Type: VIEW; Schema: ref; Owner: -
--

CREATE VIEW ref.vw_base_legal_fuente AS
 SELECT bl.id AS base_legal_id,
    bl.codigo,
    bl.finalidad,
    be.rol,
    f.id AS fragmento_id,
    f.orden AS fragmento_orden,
    f.pagina_o_minuto,
    "left"(f.texto, 400) AS extracto,
    df.id AS documento_id,
    df.titulo AS documento_titulo,
    df.tipo AS documento_tipo,
    df.url AS documento_url
   FROM (((ref.base_legal_tratamiento bl
     JOIN ref.base_legal_evidencia be ON ((be.base_legal_id = bl.id)))
     JOIN kag.documento_fragmento f ON ((f.id = be.fragmento_id)))
     JOIN kag.documento_fuente df ON ((df.id = f.documento_id)));


--
-- Name: VIEW vw_base_legal_fuente; Type: COMMENT; Schema: ref; Owner: -
--

COMMENT ON VIEW ref.vw_base_legal_fuente IS 'Cada base legal con el fragmento del corpus que la sustenta y el documento del que procede.';


