CREATE TABLE staging.lote (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    punto_ingesta_id smallint NOT NULL,
    plan_paso_id uuid,
    origen_software character varying(60),
    version_software character varying(30),
    archivo_uri character varying(500) NOT NULL,
    hash_archivo character(64) NOT NULL,
    estado character varying(12) DEFAULT 'recibido'::character varying NOT NULL,
    validacion jsonb,
    cargado_por uuid,
    aprobado_por uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    nivel_clasificacion smallint DEFAULT 2 NOT NULL,
    CONSTRAINT lote_check CHECK ((((estado)::text <> 'promovido'::text) OR (aprobado_por IS NOT NULL))),
    CONSTRAINT lote_estado_check CHECK (((estado)::text = ANY (ARRAY[('recibido'::character varying)::text, ('validado'::character varying)::text, ('con_errores'::character varying)::text, ('promovido'::character varying)::text, ('rechazado'::character varying)::text])))
);

