--
-- Name: distrito; Type: TABLE; Schema: territorio; Owner: -
--

CREATE TABLE territorio.distrito (
    ubigeo character(6) NOT NULL,
    nombre character varying(120) NOT NULL,
    provincia character varying(120),
    region character varying(120),
    poblacion_total bigint,
    poblacion_hombres bigint,
    poblacion_mujeres bigint,
    procedencia_poblacion text,
    geom public.geometry(MultiPolygon,4326),
    centroide public.geometry(Point,4326),
    creado_en timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT distrito_poblacion_total_check CHECK ((poblacion_total >= 0)),
    CONSTRAINT distrito_ubigeo_check CHECK ((ubigeo ~ '^[0-9]{6}$'::text))
);


--
-- Name: TABLE distrito; Type: COMMENT; Schema: territorio; Owner: -
--

COMMENT ON TABLE territorio.distrito IS 'Capa distrital GIS de geogpsperu, rotulada «Censo 2025» (no es una publicación del INEI). La geometría dice dónde está un territorio, no cuánto pesa: la población es SÓLO denominador (tasas por 100 000 hab.) y no entra en el nivel de riesgo. 1 892 filas: 1 891 del catálogo INEI y 160405 SANTA ROSA DE LORETO, que la capa trae y el INEI no. Sin FK a core.distritos por ese ubigeo; la identidad es el ubigeo, nunca el id.';


--
-- Name: COLUMN distrito.ubigeo; Type: COMMENT; Schema: territorio; Owner: -
--

COMMENT ON COLUMN territorio.distrito.ubigeo IS 'Código INEI de 6 dígitos (PK). Identidad estable entre entornos; no usar el id de core.distritos para exportar, importar ni comparar.';


--
-- Name: COLUMN distrito.nombre; Type: COMMENT; Schema: territorio; Owner: -
--

COMMENT ON COLUMN territorio.distrito.nombre IS 'Nombre del distrito tal como lo trae la capa. No se normaliza contra el catálogo INEI: el nombre oficial y el de la capa pueden diferir en grafía.';


--
-- Name: COLUMN distrito.provincia; Type: COMMENT; Schema: territorio; Owner: -
--

COMMENT ON COLUMN territorio.distrito.provincia IS 'Provincia de la capa (varchar, sin FK). Provincia y región son contexto de lectura, no una segunda fuente de verdad territorial.';


--
-- Name: COLUMN distrito.region; Type: COMMENT; Schema: territorio; Owner: -
--

COMMENT ON COLUMN territorio.distrito.region IS 'Departamento (región) de la capa. Sólo para filtrar y rotular.';


--
-- Name: COLUMN distrito.poblacion_total; Type: COMMENT; Schema: territorio; Owner: -
--

COMMENT ON COLUMN territorio.distrito.poblacion_total IS 'Población censal del insumo (`properties.total` del GeoJSON; si falta, `Total` de distritos_capa.csv o `poblacion_capa` de distritos_maestro.csv, casando por UBIGEO). Denominador, no peso de riesgo. NULL si ningún insumo la trae: no se estima ni se reparte.';


--
-- Name: COLUMN distrito.poblacion_hombres; Type: COMMENT; Schema: territorio; Owner: -
--

COMMENT ON COLUMN territorio.distrito.poblacion_hombres IS '`Hombre_T` de gis/derived/distritos_capa.csv, casado por UBIGEO (el GeoJSON no trae sexo). NULL cuando no hay fila o cuando Hombre_T+Mujer_T no cuadra con poblacion_total: no se estima ni se prorratea.';


--
-- Name: COLUMN distrito.poblacion_mujeres; Type: COMMENT; Schema: territorio; Owner: -
--

COMMENT ON COLUMN territorio.distrito.poblacion_mujeres IS '`Mujer_T` de gis/derived/distritos_capa.csv, casado por UBIGEO. Mismas reglas de NULL que poblacion_hombres: sin dato, no hay cifra inventada.';


--
-- Name: COLUMN distrito.procedencia_poblacion; Type: COMMENT; Schema: territorio; Owner: -
--

COMMENT ON COLUMN territorio.distrito.procedencia_poblacion IS 'Texto por fila que declara de dónde salió cada cifra y qué quedó NULL. Auditoría de la carga; no se recalcula en consulta.';


--
-- Name: COLUMN distrito.geom; Type: COMMENT; Schema: territorio; Owner: -
--

COMMENT ON COLUMN territorio.distrito.geom IS 'MultiPolygon WGS84 (EPSG:4326). Dice dónde está el territorio, no cuánto pesa. La carga usa la capa simplificada salvo que se pida --completo.';


--
-- Name: COLUMN distrito.centroide; Type: COMMENT; Schema: territorio; Owner: -
--

COMMENT ON COLUMN territorio.distrito.centroide IS 'PointOnSurface (no centroide geométrico): garantiza un punto dentro del polígono para etiquetas y mapas. Se calcula en la carga.';


--
-- Name: COLUMN distrito.creado_en; Type: COMMENT; Schema: territorio; Owner: -
--

COMMENT ON COLUMN territorio.distrito.creado_en IS 'Primera carga de la fila. Las recargas no la modifican.';


