COMMENT ON COLUMN territorio.estacion_hidrica_detalle.tipo_estacion IS 'Tipo de estación de monitoreo hídrico';


--
-- Name: expansion_informal; Type: TABLE; Schema: territorio; Owner: -
--

CREATE TABLE territorio.expansion_informal (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    lugar_id uuid NOT NULL,
    fecha_deteccion date NOT NULL,
    area_m2 numeric(10,2) NOT NULL,
    "precision" numeric(4,3),
    exhaustividad numeric(4,3),
    fuente_satelite character varying(40) NOT NULL,
    unidad_minima_mapeable_m2 numeric(6,2) NOT NULL,
    validacion_humana boolean DEFAULT false NOT NULL,
    puntos_validados integer,
    puntos_correctos integer,
    CONSTRAINT expansion_informal_area_m2_check CHECK ((area_m2 > (0)::numeric)),
    CONSTRAINT expansion_informal_check CHECK (((puntos_correctos IS NULL) OR (puntos_validados IS NULL) OR (puntos_correctos <= puntos_validados))),
    CONSTRAINT expansion_informal_exhaustividad_check CHECK (((exhaustividad IS NULL) OR ((exhaustividad >= (0)::numeric) AND (exhaustividad <= (1)::numeric)))),
    CONSTRAINT expansion_informal_precision_check CHECK ((("precision" IS NULL) OR (("precision" >= (0)::numeric) AND ("precision" <= (1)::numeric)))),
    CONSTRAINT expansion_informal_puntos_correctos_check CHECK (((puntos_correctos IS NULL) OR (puntos_correctos >= 0))),
    CONSTRAINT expansion_informal_puntos_validados_check CHECK (((puntos_validados IS NULL) OR (puntos_validados >= 0))),
    CONSTRAINT expansion_informal_unidad_minima_mapeable_m2_check CHECK ((unidad_minima_mapeable_m2 > (0)::numeric))
);


--
-- Name: TABLE expansion_informal; Type: COMMENT; Schema: territorio; Owner: -
--

COMMENT ON TABLE territorio.expansion_informal IS 'Detección de expansión informal en un lugar, con su área, la precisión del método y su validación humana.';


--
-- Name: COLUMN expansion_informal.id; Type: COMMENT; Schema: territorio; Owner: -
--

COMMENT ON COLUMN territorio.expansion_informal.id IS 'Identificador interno de la fila';


--
-- Name: COLUMN expansion_informal.lugar_id; Type: COMMENT; Schema: territorio; Owner: -
--

COMMENT ON COLUMN territorio.expansion_informal.lugar_id IS 'Lugar donde se detectó la expansión informal';


--
