    CONSTRAINT parque_industrial_hectareas_con_cerco_check CHECK ((hectareas_con_cerco >= (0)::numeric)),
    CONSTRAINT parque_industrial_hectareas_saneadas_check CHECK ((hectareas_saneadas >= (0)::numeric)),
    CONSTRAINT parque_industrial_hectareas_total_check CHECK ((hectareas_total > (0)::numeric)),
    CONSTRAINT parque_industrial_hectareas_utiles_check CHECK (((hectareas_utiles IS NULL) OR (hectareas_utiles >= (0)::numeric)))
);


