--
-- Name: vw_monitoreo_hidrico_excede_eca; Type: VIEW; Schema: territorio; Owner: -
--

CREATE VIEW territorio.vw_monitoreo_hidrico_excede_eca AS
 WITH od AS (
         SELECT observaciones.lugar_id,
            observaciones.fecha,
            observaciones.valor AS od
           FROM ctx.observaciones
          WHERE (observaciones.variable_id = 29)
        ), ph AS (
         SELECT observaciones.lugar_id,
            observaciones.fecha,
            observaciones.valor AS ph
           FROM ctx.observaciones
          WHERE (observaciones.variable_id = 30)
        ), met AS (
         SELECT observaciones.lugar_id,
            observaciones.fecha,
            observaciones.valor AS metales
           FROM ctx.observaciones
          WHERE (observaciones.variable_id = 31)
        )
 SELECT COALESCE(od.lugar_id, ph.lugar_id, met.lugar_id) AS lugar_id,
    COALESCE(od.fecha, ph.fecha, met.fecha) AS fecha,
    od.od,
    ph.ph,
    met.metales,
    (COALESCE((od.od < ((config.leer_parametro('G17.od_min'::text) #>> '{}'::text[]))::numeric), false) OR COALESCE((met.metales > ((config.leer_parametro('G17.metales_max_ppm'::text) #>> '{}'::text[]))::numeric), false) OR COALESCE(((ph.ph < 6.5) OR (ph.ph > 9.0)), false)) AS excede_eca
   FROM ((od
     FULL JOIN ph ON (((ph.lugar_id = od.lugar_id) AND (ph.fecha = od.fecha))))
     FULL JOIN met ON (((met.lugar_id = COALESCE(od.lugar_id, ph.lugar_id)) AND (met.fecha = COALESCE(od.fecha, ph.fecha)))));


