--
-- Name: hitos_compromiso r_herencia; Type: POLICY; Schema: core; Owner: -
--

CREATE POLICY r_herencia ON core.hitos_compromiso AS RESTRICTIVE USING ((EXISTS ( SELECT 1
   FROM core.compromisos hp
  WHERE ((hp.id = hitos_compromiso.compromiso_id) AND (hp.nivel_clasificacion <= core.clasificacion_max())))));


--
-- Name: output_contracts r_herencia; Type: POLICY; Schema: core; Owner: -
--

CREATE POLICY r_herencia ON core.output_contracts AS RESTRICTIVE USING (((caso_id IS NULL) OR (EXISTS ( SELECT 1
   FROM core.casos hp
  WHERE ((hp.id = output_contracts.caso_id) AND (hp.nivel_clasificacion <= core.clasificacion_max()))))));


