--
-- Name: lote p_clasificacion; Type: POLICY; Schema: staging; Owner: -
--

CREATE POLICY p_clasificacion ON staging.lote FOR SELECT USING ((nivel_clasificacion <= core.clasificacion_max()));


--
-- Name: lote p_delete; Type: POLICY; Schema: staging; Owner: -
--

CREATE POLICY p_delete ON staging.lote FOR DELETE USING (((core.clasificacion_max() >= 3) AND (nivel_clasificacion <= core.clasificacion_max())));


--
-- Name: lote p_insert; Type: POLICY; Schema: staging; Owner: -
--

CREATE POLICY p_insert ON staging.lote FOR INSERT WITH CHECK (((core.clasificacion_max() >= 2) AND (nivel_clasificacion <= core.clasificacion_max())));


--
-- Name: lote p_update; Type: POLICY; Schema: staging; Owner: -
--

CREATE POLICY p_update ON staging.lote FOR UPDATE USING (((core.clasificacion_max() >= 2) AND (nivel_clasificacion <= core.clasificacion_max()))) WITH CHECK ((nivel_clasificacion <= core.clasificacion_max()));


